package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A single local-model decision. Parsing does not authorize or execute an action.
 * The controller must still validate the exact current observation, package,
 * node, viewport and action preconditions.
 */
public final class ActionDecision {
    public static final String IME_ACTION_SCHEMA="hepta.observed-action-gbnf.v5-ime-enter";
    public static final String FIXED_INTENT_ACTION_SCHEMA="hepta.observed-action-gbnf.v6-fixed-intents";
    /** Internal typed requests never enter the model JSON parser or its grammar. */
    static final String TOOL_CHILD_SCHEMA="hepta.internal-tool-child.v1";
    interface ToolChildOrigin {
        void enterService(String task,String authorizationSha,String run,String observation);
        void requireDispatch(String task,String authorizationSha,String run,ActionDecision action);
        Map<String,Object> evidence();
    }
    private static final int MAX_JSON_UTF8_BYTES = 16384;
    private static final int MAX_TEXT_UTF8_BYTES = 4096;
    private static final Pattern OBSERVATION_ID = Pattern.compile("[0-9a-fA-F]{32}");
    private static final Pattern NODE_ID = Pattern.compile("n[0-9]{1,5}");

    public final String action;
    public final String observationId;
    public final String packageName;
    public final String appLabel;
    public final String actionSchema;
    public final String nodeId;
    public final String nodeLabel;
    public final String text;
    public final String direction;
    public final String status;
    public final String summary;
    public final String reason;
    public final String query;
    public final int x;
    public final int y;
    public final int durationMs;
    public final int offset;
    final ToolChildOrigin toolChildOrigin;

    private ActionDecision(String action, String observationId, String packageName, String appLabel, String actionSchema,
                           String nodeId, String nodeLabel, String text, String direction, String status,
                           String summary, String reason, int x, int y, int durationMs, String query, int offset) {
        this(action,observationId,packageName,appLabel,actionSchema,nodeId,nodeLabel,text,direction,status,
                summary,reason,x,y,durationMs,query,offset,null);
    }
    private ActionDecision(String action,String observationId,String packageName,String appLabel,String actionSchema,
                           String nodeId,String nodeLabel,String text,String direction,String status,
                           String summary,String reason,int x,int y,int durationMs,String query,int offset,ToolChildOrigin origin) {
        this.action = action;
        this.observationId = observationId;
        this.packageName = packageName;
        this.appLabel = appLabel;
        this.actionSchema = actionSchema;
        this.nodeId = nodeId;
        this.nodeLabel = nodeLabel;
        this.text = text;
        this.direction = direction;
        this.status = status;
        this.summary = summary;
        this.reason = reason;
        this.x = x;
        this.y = y;
        this.durationMs = durationMs;
        this.query = query;
        this.offset = offset;
        this.toolChildOrigin=origin;
    }

    /** A capability supplied by the controller's already-authorized parent tool,
     * never by JSON, screen text or a manufactured model response. */
    static ActionDecision toolChild(ToolChildOrigin origin,String action,String observation,String pkg,String node,String label){
        if(origin==null||!("back".equals(action)||"click".equals(action))||observation==null
                ||!OBSERVATION_ID.matcher(observation).matches()||!"com.motorola.stylus".equals(pkg))
            throw new IllegalArgumentException("invalid internal Notes child");
        if("click".equals(action)&&(node==null||!NODE_ID.matcher(node).matches()||label==null||label.isEmpty()))
            throw new IllegalArgumentException("internal click requires an observed node/label");
        if("back".equals(action)&&(node!=null||label!=null))throw new IllegalArgumentException("internal Back has no target node");
        return new ActionDecision(action,observation,pkg,null,TOOL_CHILD_SCHEMA,node,label,null,null,null,null,
                "Authorized Notes tool child; not a model decision",-1,-1,0,null,0,origin);
    }

    public static final class InvalidActionException extends Exception {
        private static final long serialVersionUID = 1L;

        public InvalidActionException(String message) {
            super(message);
        }
    }

    /** Accepts exactly one flat JSON object; no recovery or substring extraction. */
    public static ActionDecision parse(String raw) throws InvalidActionException {
        return parse(raw, ObservedTargetLabels.ACTION_SCHEMA);
    }

    /** The caller selects an explicit protocol; older or unknown node schemas are not inferred. */
    public static ActionDecision parse(String raw, String schema) throws InvalidActionException {
        boolean fixedIntents = FIXED_INTENT_ACTION_SCHEMA.equals(schema);
        boolean imeProtocol = fixedIntents || IME_ACTION_SCHEMA.equals(schema);
        boolean appLabeled = imeProtocol || ObservedAppLabels.ACTION_SCHEMA.equals(schema);
        require(appLabeled || ObservedTargetLabels.ACTION_SCHEMA.equals(schema), "Unknown action schema");
        require(raw != null && !raw.isEmpty(), "Empty model output");
        require(raw.length() <= MAX_JSON_UTF8_BYTES, "Model output exceeds size bound");
        validateUnicode(raw);
        require(utf8Bytes(raw) <= MAX_JSON_UTF8_BYTES, "Model output exceeds 16384 UTF-8 bytes");
        Map<String, Object> fields = new JsonParser(raw).readObject();
        String action = string(fields, "action");
        String observationId = string(fields, "observation_id");
        require(OBSERVATION_ID.matcher(observationId).matches(), "Invalid observation_id");
        String packageName = string(fields, "package");
        require(validPackageName(packageName), "Invalid package");
        String reason = fields.containsKey("reason") ? string(fields, "reason") : "";
        require(codePoints(reason) <= 256, "reason exceeds 256 characters");

        String nodeId = null;
        String appLabel = null;
        String nodeLabel = null;
        String text = null;
        String direction = null;
        String status = null;
        String summary = null;
        int x = -1;
        int y = -1;
        int durationMs = -1;
        String query = null;
        int offset = -1;

        switch (action) {
            case "notes.create":
            case "web.search":
                require(fixedIntents,"fixed intent tools require the explicit v6 schema");
                requireFields(fields,"app_label","package","notes.create".equals(action)?"text":"query");
                appLabel=appLabel(fields);
                String payload=string(fields,"notes.create".equals(action)?"text":"query");
                org.trillionnium.hepta.background.FixedIntentTools.Profile profile=org.trillionnium.hepta.background.FixedIntentTools.forAction(action);
                require(profile.packageName.equals(packageName),"fixed intent package mismatch");
                try{profile.validatePayload(payload);}catch(IllegalArgumentException invalid){throw new InvalidActionException(invalid.getMessage());}
                if("notes.create".equals(action))text=payload;else query=payload;
                break;
            case "open":
                if (appLabeled) {
                    requireFields(fields, "app_label", "package");
                    appLabel = appLabel(fields);
                } else requireFields(fields, "package");
                break;
            case "find_app":
                requireFields(fields, "package", "query", "offset");
                query = string(fields, "query");
                require(query.indexOf('\0') < 0, "query contains NUL");
                require(codePoints(query) <= 64, "query exceeds 64 characters");
                offset = integer(fields, "offset", 0, 4095);
                break;
            case "click":
                if (fields.containsKey("node_id")) {
                    requireFields(fields, "package", "node_label", "node_id");
                    nodeLabel = nodeLabel(fields);
                    nodeId = node(fields);
                } else {
                    requireFields(fields, "package", "x", "y");
                    x = integer(fields, "x", 0, 1000);
                    y = integer(fields, "y", 0, 1000);
                }
                break;
            case "type":
                requireFields(fields, "package", "node_label", "node_id", "text");
                nodeLabel = nodeLabel(fields);
                nodeId = node(fields);
                text = string(fields, "text");
                require(text.indexOf('\0') < 0, "text contains NUL");
                require(utf8Bytes(text) <= MAX_TEXT_UTF8_BYTES, "text exceeds 4096 UTF-8 bytes");
                break;
            case "submit":
                require(imeProtocol,"submit requires the observed IME action protocol");
                requireFields(fields,"package","node_label","node_id");
                nodeLabel=nodeLabel(fields);nodeId=node(fields);
                break;
            case "scroll":
                requireFields(fields, "package", "node_label", "node_id", "direction");
                nodeLabel = nodeLabel(fields);
                nodeId = node(fields);
                direction = string(fields, "direction");
                require(oneOf(direction, "forward", "backward", "up", "down", "left", "right"),
                        "Invalid scroll direction");
                break;
            case "back":
            case "home":
                requireFields(fields, "package");
                break;
            case "wait":
                requireFields(fields, "package", "duration_ms");
                durationMs = integer(fields, "duration_ms", 100, 2000);
                break;
            case "done":
                requireFields(fields, "package", "status", "summary");
                status = string(fields, "status");
                require(oneOf(status, "success", "partial", "failure"), "Invalid done status");
                summary = string(fields, "summary");
                require(!summary.isEmpty() && codePoints(summary) <= 1024,
                        "summary must contain 1..1024 characters");
                break;
            default:
                throw new InvalidActionException("Unsupported action");
        }
        return new ActionDecision(action, observationId, packageName, appLabel, schema, nodeId, nodeLabel, text,
                direction, status, summary, reason, x, y, durationMs, query, offset);
    }

    public static String schemaGuide() {
        return "Return exactly one flat JSON object, with double-quoted keys and strings. "
                + "Every action requires action, observation_id (the exact current 32-hex ID), "
                + "and package (the current verified package; open names its target package). "
                + "reason is optional and at most 256 Unicode characters. "
                + "Allowed actions and additional fields: "
                + "open: no additional fields; "
                + "find_app: query,offset (read-only installed launcher search, not an app launch); "
                + "click: either node_label,node_id or both x,y, never both forms; "
                + "type: node_label,node_id,text; "
                + "scroll: node_label,node_id,direction; "
                + "back: no additional fields; home: no additional fields; "
                + "wait: duration_ms; done: status,summary. "
                + "node_id is n followed by 1..5 ASCII digits. "
                + "node_label must precede node_id and copy its exact supplied label, including empty or duplicate labels. "
                + "The label and ID are a pair from this observation; reason never identifies or changes the target. "
                + "x,y are canonical integers 0..1000 from the current observation. "
                + "duration_ms is a canonical integer 100..2000. "
                + "query has 0..64 Unicode characters, no NUL; empty query browses apps. "
                + "offset is a canonical integer 0..4095; use the returned next_offset to page. "
                + "direction is forward,backward,up,down,left,right. "
                + "status is success,partial,failure; summary has 1..1024 Unicode characters. "
                + "text preserves exact Unicode and escaped newlines, contains no NUL, "
                + "and is at most 4096 UTF-8 bytes. "
                + "No other fields, duplicate keys, nested values, booleans, null, "
                + "floating-point numbers, Markdown, explanations, or trailing content. "
                + "The entire JSON is at most 16384 UTF-8 bytes.";
    }

    public static String schemaGuide(String schema) throws InvalidActionException {
        require(ObservedTargetLabels.ACTION_SCHEMA.equals(schema) || ObservedAppLabels.ACTION_SCHEMA.equals(schema) || IME_ACTION_SCHEMA.equals(schema) || FIXED_INTENT_ACTION_SCHEMA.equals(schema), "Unknown action schema");
        if (ObservedTargetLabels.ACTION_SCHEMA.equals(schema)) return schemaGuide();
        String guide=schemaGuide().replace("open: no additional fields; ",
                "open: app_label before package, copying the exact supplied app-label/package pair, including empty or duplicate labels; ");
        if(FIXED_INTENT_ACTION_SCHEMA.equals(schema))guide+=" notes.create: exact supplied app_label,package,text; web.search: exact supplied app_label,package,query. These only request an editor or web search; never imply saved content or verified results. Fixed payload has 1..1024 Unicode scalars, at most 4096 UTF-8 bytes.";
        return (IME_ACTION_SCHEMA.equals(schema)||FIXED_INTENT_ACTION_SCHEMA.equals(schema))?guide.replace("scroll: node_label,node_id,direction; ",
                "submit: node_label,node_id, only a currently supplied query-labelled IME-enter capability; scroll: node_label,node_id,direction; "):guide;
    }

    private static void requireFields(Map<String, Object> fields, String... required)
            throws InvalidActionException {
        Set<String> allowed = new HashSet<String>(
                Arrays.asList("action", "observation_id", "reason"));
        for (String name : required) {
            require(fields.containsKey(name), "Missing field: " + name);
            allowed.add(name);
        }
        for (String name : fields.keySet()) {
            require(allowed.contains(name), "Field '"+name+"' is not allowed for action '"+fields.get("action")+"'");
        }
    }

    private static String string(Map<String, Object> fields, String name)
            throws InvalidActionException {
        Object value = fields.get(name);
        require(value instanceof String, "Missing or non-string field: " + name);
        return (String) value;
    }

    private static String node(Map<String, Object> fields) throws InvalidActionException {
        String value = string(fields, "node_id");
        require(NODE_ID.matcher(value).matches(), "Invalid node_id");
        return value;
    }

    private static String nodeLabel(Map<String, Object> fields) throws InvalidActionException {
        String label = string(fields, "node_label");
        try { ObservedTargetLabels.requireProjectedLabel(label); }
        catch (IllegalArgumentException error) { throw new InvalidActionException(error.getMessage()); }
        for (String key : fields.keySet()) {
            if ("node_label".equals(key)) return label;
            require(!"node_id".equals(key), "node_label must precede node_id");
        }
        throw new InvalidActionException("Missing node_label");
    }

    private static String appLabel(Map<String, Object> fields) throws InvalidActionException {
        String label = string(fields, "app_label");
        try { ObservedAppLabels.requireProjectedLabel(label); }
        catch (IllegalArgumentException error) { throw new InvalidActionException(error.getMessage()); }
        for (String key : fields.keySet()) {
            if ("app_label".equals(key)) return label;
            require(!"package".equals(key), "app_label must precede package");
        }
        throw new InvalidActionException("Missing app_label");
    }

    private static int integer(Map<String, Object> fields, String name, int minimum, int maximum)
            throws InvalidActionException {
        Object value = fields.get(name);
        require(value instanceof Integer, "Missing or non-integer field: " + name);
        int number = ((Integer) value).intValue();
        require(number >= minimum && number <= maximum, "Out-of-range field: " + name);
        return number;
    }

    private static boolean oneOf(String value, String... allowed) {
        for (String item : allowed) {
            if (item.equals(value)) {
                return true;
            }
        }
        return false;
    }

    private static int codePoints(String value) {
        return value.codePointCount(0, value.length());
    }

    /**
     * Equivalent to [A-Za-z][A-Za-z0-9_]*(?:\.[A-Za-z][A-Za-z0-9_]*)+.
     * Iterate segments so a long model string cannot overflow a regex backtracking stack.
     */
    private static boolean validPackageName(String value) {
        // System dialogs legitimately expose package="android". This only parses
        // identity: open still needs a fresh installed launcher catalogue entry.
        if ("android".equals(value)) return true;
        boolean firstInSegment = true;
        boolean sawDot = false;
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            if (ch == '.') {
                if (firstInSegment) return false;
                firstInSegment = true;
                sawDot = true;
            } else {
                boolean letter = (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
                if (firstInSegment) {
                    if (!letter) return false;
                    firstInSegment = false;
                } else if (!letter && !(ch >= '0' && ch <= '9') && ch != '_') {
                    return false;
                }
            }
        }
        return sawDot && !firstInSegment;
    }

    private static int utf8Bytes(String value) {
        return value.getBytes(StandardCharsets.UTF_8).length;
    }

    private static void validateUnicode(String value) throws InvalidActionException {
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            if (Character.isHighSurrogate(ch)) {
                require(i + 1 < value.length() && Character.isLowSurrogate(value.charAt(i + 1)),
                        "Unpaired UTF-16 high surrogate");
                i++;
            } else {
                require(!Character.isLowSurrogate(ch), "Unpaired UTF-16 low surrogate");
            }
        }
    }

    private static void require(boolean condition, String message)
            throws InvalidActionException {
        if (!condition) {
            throw new InvalidActionException(message);
        }
    }

    /** Only JSON strings and canonical integral tokens are admitted as values. */
    private static final class JsonParser {
        private final String source;
        private int position;

        JsonParser(String source) {
            this.source = source;
        }

        Map<String, Object> readObject() throws InvalidActionException {
            Map<String, Object> fields = new LinkedHashMap<String, Object>();
            whitespace();
            expect('{');
            whitespace();
            if (!take('}')) {
                while (true) {
                    require(peek('"'), "Expected double-quoted JSON key");
                    String key = readString();
                    require(!fields.containsKey(key), "Duplicate JSON key");
                    whitespace();
                    expect(':');
                    whitespace();
                    Object value;
                    if (peek('"')) {
                        value = readString();
                    } else {
                        value = readInteger();
                    }
                    fields.put(key, value);
                    whitespace();
                    if (take('}')) {
                        break;
                    }
                    expect(',');
                    whitespace();
                }
            }
            whitespace();
            require(position == source.length(), "Trailing JSON content");
            return fields;
        }

        private String readString() throws InvalidActionException {
            expect('"');
            StringBuilder value = new StringBuilder();
            while (position < source.length()) {
                char ch = source.charAt(position++);
                if (ch == '"') {
                    String decoded = value.toString();
                    validateUnicode(decoded);
                    return decoded;
                }
                require(ch >= 0x20, "Unescaped JSON control character");
                if (ch != '\\') {
                    value.append(ch);
                    continue;
                }
                require(position < source.length(), "Incomplete JSON escape");
                char escaped = source.charAt(position++);
                switch (escaped) {
                    case '"': value.append('"'); break;
                    case '\\': value.append('\\'); break;
                    case '/': value.append('/'); break;
                    case 'b': value.append('\b'); break;
                    case 'f': value.append('\f'); break;
                    case 'n': value.append('\n'); break;
                    case 'r': value.append('\r'); break;
                    case 't': value.append('\t'); break;
                    case 'u':
                        require(source.length() - position >= 4, "Incomplete Unicode escape");
                        int codeUnit = 0;
                        for (int i = 0; i < 4; i++) {
                            char digit = source.charAt(position++);
                            int hex = hexDigit(digit);
                            require(hex >= 0, "Invalid Unicode escape");
                            codeUnit = (codeUnit << 4) | hex;
                        }
                        value.append((char) codeUnit);
                        break;
                    default:
                        throw new InvalidActionException("Invalid JSON escape");
                }
            }
            throw new InvalidActionException("Unterminated JSON string");
        }

        private Integer readInteger() throws InvalidActionException {
            int start = position;
            boolean negative = take('-');
            require(position < source.length(), "Missing integer");
            if (take('0')) {
                require(!negative, "Negative zero is not a canonical action integer");
                require(position == source.length() || !asciiDigit(source.charAt(position)),
                        "Leading zero in integer");
            } else {
                require(position < source.length() && source.charAt(position) >= '1'
                                && source.charAt(position) <= '9',
                        "Only string or canonical integer JSON values are permitted");
                while (position < source.length() && asciiDigit(source.charAt(position))) {
                    position++;
                }
            }
            if (position < source.length()) {
                char next = source.charAt(position);
                require(next == ',' || next == '}' || isWhitespace(next),
                        "Invalid integer token");
            }
            try {
                return Integer.valueOf(source.substring(start, position));
            } catch (NumberFormatException error) {
                throw new InvalidActionException("Integer exceeds 32-bit range");
            }
        }

        private static int hexDigit(char value) {
            if (value >= '0' && value <= '9') return value - '0';
            if (value >= 'a' && value <= 'f') return value - 'a' + 10;
            if (value >= 'A' && value <= 'F') return value - 'A' + 10;
            return -1;
        }

        private static boolean asciiDigit(char value) {
            return value >= '0' && value <= '9';
        }

        private static boolean isWhitespace(char value) {
            return value == ' ' || value == '\t' || value == '\r' || value == '\n';
        }

        private void whitespace() {
            while (position < source.length() && isWhitespace(source.charAt(position))) {
                position++;
            }
        }

        private boolean peek(char expected) {
            return position < source.length() && source.charAt(position) == expected;
        }

        private boolean take(char expected) {
            if (!peek(expected)) return false;
            position++;
            return true;
        }

        private void expect(char expected) throws InvalidActionException {
            require(take(expected), "Malformed JSON object");
        }
    }
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Immutable local launcher snapshot. Searching this data never launches an app. */
public final class AppCatalogueRanker {
    public static final int PAGE_SIZE = 6;
    public static final int MAX_APPS = 4096;
    public static final int MAX_OFFSET = MAX_APPS - 1;
    public static final int MAX_QUERY_CODE_POINTS = 64;
    public static final String SOURCE = "installed_launcher_snapshot";

    public static final class Entry {
        public final String packageName, label;
        private final String normalizedPackage, normalizedLabel;

        private Entry(String packageName, String label) {
            this.packageName = packageName;
            this.label = label;
            normalizedPackage = normalize(packageName);
            normalizedLabel = normalize(label);
        }
    }

    public static final class Page {
        public final String query, catalogueSha256;
        public final int offset, totalApps, matchingApps;
        public final List<Entry> apps;

        private Page(String query, int offset, int totalApps, int matchingApps,
                     String catalogueSha256, List<Entry> apps) {
            this.query = query;
            this.offset = offset;
            this.totalApps = totalApps;
            this.matchingApps = matchingApps;
            this.catalogueSha256 = catalogueSha256;
            this.apps = Collections.unmodifiableList(new ArrayList<Entry>(apps));
        }

        /** Advance past the prefix actually supplied to the model, not omitted rows. */
        public int nextOffset(int shown) {
            if (shown < 0 || shown > apps.size()) throw new IllegalArgumentException("invalid app projection");
            return offset + shown < matchingApps ? offset + shown : -1;
        }
    }

    private final List<Entry> ranked;
    public final String catalogueSha256;

    public AppCatalogueRanker(Map<String, String> installedLauncherApps, String owner) {
        if (installedLauncherApps == null || installedLauncherApps.size() > MAX_APPS || owner == null)
            throw new IllegalArgumentException("invalid installed launcher snapshot");
        final String normalizedOwner = normalize(owner);
        List<Entry> rows = new ArrayList<Entry>();
        for (Map.Entry<String, String> value : installedLauncherApps.entrySet()) {
            String pkg = value.getKey();
            if (pkg == null || pkg.length() > 255 || !pkg.matches("[A-Za-z][A-Za-z0-9_]*(?:\\.[A-Za-z][A-Za-z0-9_]*)+"))
                throw new IllegalArgumentException("invalid installed launcher package");
            // The displayed label is untrusted data. Limit only the stored display
            // label; every installed package stays searchable and pageable.
            rows.add(new Entry(pkg, boundedLabel(value.getValue())));
        }
        Collections.sort(rows, new Comparator<Entry>() {
            @Override public int compare(Entry a, Entry b) { return a.packageName.compareTo(b.packageName); }
        });
        catalogueSha256 = fingerprint(rows);
        Collections.sort(rows, new Comparator<Entry>() {
            @Override public int compare(Entry a, Entry b) {
                int priority = Integer.compare(ownerPriority(b, normalizedOwner), ownerPriority(a, normalizedOwner));
                return priority != 0 ? priority : a.packageName.compareTo(b.packageName);
            }
        });
        ranked = Collections.unmodifiableList(rows);
    }

    /** Empty query browses all installed launcher entries; nonempty query is a substring search. */
    public Page search(String query, int offset) {
        validateQuery(query);
        if (offset < 0 || offset > MAX_OFFSET) throw new IllegalArgumentException("app search offset out of range");
        final String term = normalize(query);
        List<Entry> matches = new ArrayList<Entry>();
        for (Entry entry : ranked) {
            if (term.isEmpty() || entry.normalizedPackage.contains(term) || entry.normalizedLabel.contains(term))
                matches.add(entry);
        }
        if (!term.isEmpty()) {
            // Collections.sort is stable: ties retain the owner's ranking and
            // existing package order, independent of PackageManager iteration.
            Collections.sort(matches, new Comparator<Entry>() {
                @Override public int compare(Entry a, Entry b) {
                    return Integer.compare(searchPriority(b, term), searchPriority(a, term));
                }
            });
        }
        int from = Math.min(offset, matches.size()), to = Math.min(from + PAGE_SIZE, matches.size());
        return new Page(query, offset, ranked.size(), matches.size(), catalogueSha256, matches.subList(from, to));
    }

    public static void validateQuery(String query) {
        if (query == null || query.length() > 2 * MAX_QUERY_CODE_POINTS || query.indexOf('\0') >= 0)
            throw new IllegalArgumentException("invalid app search query");
        for (int i = 0; i < query.length(); i++) {
            char c = query.charAt(i);
            if (Character.isHighSurrogate(c)) {
                if (i + 1 >= query.length() || !Character.isLowSurrogate(query.charAt(++i)))
                    throw new IllegalArgumentException("invalid app search Unicode");
            } else if (Character.isLowSurrogate(c)) throw new IllegalArgumentException("invalid app search Unicode");
        }
        if (query.codePointCount(0, query.length()) > MAX_QUERY_CODE_POINTS)
            throw new IllegalArgumentException("app search query exceeds 64 characters");
    }

    private static int ownerPriority(Entry entry, String owner) {
        if (containsPackage(owner, entry.normalizedPackage)) return 2;
        return !entry.normalizedLabel.isEmpty() && owner.contains(entry.normalizedLabel) ? 1 : 0;
    }

    private static boolean containsPackage(String text, String pkg) {
        int from = 0;
        while (from <= text.length() - pkg.length()) {
            int at = text.indexOf(pkg, from);
            if (at < 0) return false;
            int end = at + pkg.length();
            if ((at == 0 || !packageCharacter(text.charAt(at - 1)))
                    && (end == text.length() || !packageCharacter(text.charAt(end)))) return true;
            from = at + 1;
        }
        return false;
    }

    private static boolean packageCharacter(char value) {
        return value >= 'a' && value <= 'z' || value >= '0' && value <= '9' || value == '_' || value == '.';
    }

    private static int searchPriority(Entry entry, String term) {
        if (entry.normalizedPackage.equals(term)) return 3;
        if (entry.normalizedLabel.equals(term)) return 2;
        return entry.normalizedLabel.startsWith(term) ? 1 : 0;
    }

    private static String normalize(String value) {
        String normalized = Normalizer.normalize(value, Normalizer.Form.NFKC).toLowerCase(Locale.ROOT);
        StringBuilder result = new StringBuilder();
        boolean space = false;
        for (int i = 0; i < normalized.length();) {
            int cp = normalized.codePointAt(i); i += Character.charCount(cp);
            if (Character.isWhitespace(cp) || Character.isSpaceChar(cp)) { space = result.length() > 0; continue; }
            if (space) result.append(' ');
            result.appendCodePoint(cp); space = false;
        }
        return result.toString();
    }

    private static String boundedLabel(String label) {
        if (label == null) return "";
        StringBuilder safe = new StringBuilder();
        for (int i = 0, count = 0; i < label.length() && count < 256; count++) {
            int cp = label.codePointAt(i); i += Character.charCount(cp);
            // Android labels can be supplied by other apps; malformed text must
            // not introduce invalid UTF-8/NUL into the local model prompt.
            safe.appendCodePoint(cp == 0 || cp >= 0xd800 && cp <= 0xdfff ? 0xfffd : cp);
        }
        return safe.toString();
    }

    private static String fingerprint(List<Entry> entries) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            for (Entry entry : entries) {
                hashField(digest, entry.packageName); hashField(digest, entry.label);
            }
            StringBuilder out = new StringBuilder(64);
            for (byte value : digest.digest()) out.append(String.format(Locale.ROOT, "%02x", value & 255));
            return out.toString();
        } catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }

    private static void hashField(MessageDigest digest, String value) {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        digest.update(new byte[] {(byte)(bytes.length >>> 24), (byte)(bytes.length >>> 16),
                (byte)(bytes.length >>> 8), (byte)bytes.length});
        digest.update(bytes);
    }
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.trillionnium.hepta.background.FixedIntentTools;

/** A small, completely consumed natural note request, not a semantic planner.
 *
 * The body is one exact UTF-16 span of immutable OWNER. This class neither
 * dispatches nor grants tools. A standard supported note request asks for
 * persistence; save/list/reopen is the verification policy, not an invented
 * reminder or a claim that the user literally said "reopen".
 *
 * The older explicit save/list/reopen contract remains owned by its existing
 * parser. Unknown or ambiguous forms must keep their original authorization
 * text, rather than having a model-proposed payload masked out of it.
 */
public final class NotesOwnerIntent {
    public static final String SCHEMA = "hepta.notes-owner-intent.v1";
    /** The current complete list evidence requires body.length() < 95. */
    public static final int MAX_BODY_UTF16 = 94;
    private static final String SPACE = "[ \\t]*";
    private static final String POLITE = "(?:(?:请帮我|帮我|请)" + SPACE + ")?";
    private static final String END = SPACE + "[。.!！]?" + SPACE;
    private static final String PREFIX = "(?:记一下|记录一下|记个笔记|记一条笔记|新建(?:一条|一个)?(?:笔记|备忘录))[：:]";
    private static final String QUOTED_NEW = "(?:新建|创建|写)(?:一条|一个|一则)?(?:笔记|备忘录)"
            + "[，,]?" + SPACE + "(?:正文|内容)(?:为|是)[：:]?" + SPACE;
    private static final String DESTINATION = "(?:记到|记在|写入|保存到)(?:备忘录|笔记)(?:里|中)?";
    private static final Pattern UNQUOTED_PREFIX = full(SPACE + POLITE + PREFIX + "(.+)");
    // Do not consume an apparent polite word from the body: 请假申请记一下
    // must retain 请假申请, rather than silently changing it to 假申请.
    private static final Pattern UNQUOTED_SUFFIX = full(SPACE + "(.+?)[，,]?记一下" + END);
    private static final Pattern UNQUOTED_DESTINATION = full(SPACE + POLITE + "把(.+?)" + DESTINATION + END);
    private static final Pattern AMBIGUOUS_UNQUOTED = Pattern.compile(
            "[，,；;！!？?]|然后|随后|并且|同时|顺便|另外|接着|还要|再帮我|并帮我"
            + "|提醒|闹钟|报警|定时|日历"
            + "|记一下|记录一下|记到(?:备忘录|笔记)|记在(?:备忘录|笔记)"
            + "|(?:^|。)(?:只允许|仅允许|禁止|不得|不允许)");
    // A complete comma-led note request owns the exact remainder as one body.
    // Commas inside that body are data; additional actions or authority clauses
    // still require explicit quotation instead of being silently masked.
    private static final Pattern UNQUOTED_COMMA_PREFIX =
            full(SPACE + POLITE + "(?:记一下|记录一下)[，,](.+)");
    private static final Pattern AMBIGUOUS_COMMA_BODY = Pattern.compile(
            "[；;！!？?]|然后|随后|并且|同时|顺便|另外|接着|还要|再帮我|并帮我"
            + "|提醒|闹钟|报警|定时|日历"
            + "|记一下|记录一下|记到(?:备忘录|笔记)|记在(?:备忘录|笔记)"
            + "|只允许|仅允许|禁止|不得|不允许"
            + "|删除|清空|擦除|下单|付款|支付|转账|发送|发微信|发邮件|拨打|打电话"
            + "|打开|启动|关闭|退出|点击|返回|回到|滑动|滚动|输入|搜索|查询|查机票"
            + "|创建|新建|添加|截图|截屏"
            + "|\\b(?:then|also|remind|alarm|delete|erase|remove|open|launch|close|click|tap|scroll|swipe|send|call|pay|purchase|order|transfer|checkout)\\b"
            + "|\\bonly[ \\t]+allow\\b|\\bdo[ \\t]+not[ \\t]+save\\b",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern DRAFT_ONLY = Pattern.compile(
            "(?:只|仅|先)(?:新建|打开|写)?(?:一个|一条)?(?:笔记)?草稿"
            + "|(?:新建|打开|写)(?:一个|一条)?(?:笔记)?草稿"
            + "|不要保存|不保存|不必保存|无需保存|只打开(?:笔记)?编辑器");
    private static final char[][] QUOTES = {{'“','”'}, {'‘','’'}, {'"','"'}, {'\'','\''}};

    private NotesOwnerIntent() { }

    public static final class Result {
        public final boolean supported;
        public final String body;
        public final int bodyStartUtf16;
        public final int bodyEndUtf16;
        public final String recognition;
        public final boolean saveAndReopenRequested;
        public final boolean draftOnly;
        public final boolean quotedBody;
        public final String reason;
        public final boolean grantsToolAuthority = false;
        private final String immutableOwner;

        private Result(String owner, boolean ok, String text, int start, int end,
                       String form, boolean draft, boolean quoted, String why) {
            immutableOwner = owner;
            supported = ok;
            body = text;
            bodyStartUtf16 = start;
            bodyEndUtf16 = end;
            recognition = form;
            saveAndReopenRequested = ok;
            draftOnly = draft;
            quotedBody = quoted;
            reason = why;
        }

        /** Older literal forms mask only their exact body span. The new unquoted
         * comma form must preserve the entire OWNER for every authority rule.
         * This choice is data flow, not a second copy of the authority grammar.
         */
        public boolean masksOwnerBodyForAuthority() {
            return supported && !"natural_note_comma_prefix.v1".equals(recognition);
        }

        /** Return authority text only for this parser's exact immutable OWNER.
         * A comma-form body remains fully visible to the original compiler.
         */
        public String maskedOwnerForAuthority(String owner) {
            if (!supported || immutableOwner == null || !immutableOwner.equals(owner)
                    || !body.equals(owner.substring(bodyStartUtf16, bodyEndUtf16))) {
                throw new IllegalArgumentException("EXACT_SUPPORTED_NOTES_OWNER_REQUIRED");
            }
            if (!masksOwnerBodyForAuthority()) return owner;
            char[] chars = owner.toCharArray();
            for (int i = bodyStartUtf16; i < bodyEndUtf16; i++) chars[i] = ' ';
            return new String(chars);
        }
    }

    public static Result parse(String immutableOwner) {
        if (!validOwner(immutableOwner)) return refused(immutableOwner, false, "unsupported_owner_text");
        String owner = immutableOwner;
        for (char[] quote : QUOTES) {
            String body = Pattern.quote(String.valueOf(quote[0])) + "([^"
                    + classEscape(quote[0]) + classEscape(quote[1]) + "\\r\\n]+)"
                    + Pattern.quote(String.valueOf(quote[1]));
            String[] expressions = {
                SPACE + POLITE + PREFIX + SPACE + body + END,
                SPACE + POLITE + QUOTED_NEW + body + END,
                SPACE + POLITE + "把" + body + DESTINATION + END,
                SPACE + body + "[，,]?记一下" + END
            };
            String[] forms = {"quoted_note_prefix.v1", "quoted_new_note.v1",
                    "quoted_note_destination.v1", "quoted_note_suffix.v1"};
            for (int i = 0; i < expressions.length; i++) {
                Matcher match = full(expressions[i]).matcher(owner);
                if (match.matches()) return candidate(owner, match, forms[i], true);
            }
        }
        Matcher commaPrefix = UNQUOTED_COMMA_PREFIX.matcher(owner);
        if (commaPrefix.matches()) {
            return candidate(owner, commaPrefix, "natural_note_comma_prefix.v1", false, true);
        }
        Pattern[] patterns = {UNQUOTED_PREFIX, UNQUOTED_DESTINATION, UNQUOTED_SUFFIX};
        String[] forms = {"natural_note_prefix.v1", "natural_note_destination.v1", "natural_note_suffix.v1"};
        for (int i = 0; i < patterns.length; i++) {
            Matcher match = patterns[i].matcher(owner);
            if (match.matches()) return candidate(owner, match, forms[i], false);
        }
        return refused(owner, DRAFT_ONLY.matcher(outsideQuotedText(owner)).find(),
                "no_complete_supported_natural_note_request");
    }

    private static Result candidate(String owner, Matcher match, String form, boolean quoted) {
        return candidate(owner, match, form, quoted, false);
    }

    private static Result candidate(String owner, Matcher match, String form, boolean quoted,
                                    boolean commaPrefix) {
        int start = match.start(1), end = match.end(1);
        String body = owner.substring(start, end); // Never trim/normalize/rewrite the source span.
        if (body.length() > MAX_BODY_UTF16) return refused(owner, false, "body_exceeds_complete_list_limit");
        try {
            FixedIntentTools.forAction("notes.create").validatePayload(body);
        } catch (IllegalArgumentException invalid) {
            return refused(owner, false, "unsupported_literal_body");
        }
        if (!quoted) {
            // Multiple unquoted clauses can also be authority or extra goals.
            // Require explicit quotation for such literal content instead of
            // swallowing it into an allegedly authorized body.
            Pattern ambiguity = commaPrefix ? AMBIGUOUS_COMMA_BODY : AMBIGUOUS_UNQUOTED;
            if (hasQuote(body) || ambiguity.matcher(body).find()
                    || body.indexOf('。') >= 0 && body.indexOf('。') != body.length() - 1
                    || body.endsWith("帮我")) {
                return refused(owner, DRAFT_ONLY.matcher(body).find(), "ambiguous_unquoted_body_or_additional_goal");
            }
            if (DRAFT_ONLY.matcher(body).find()) return refused(owner, true, "explicit_draft_or_no_save_request");
        }
        return new Result(owner, true, body, start, end, form, false, quoted,
                "exact_source_span_with_note_persistence_verification_policy");
    }

    private static Pattern full(String expression) {
        return Pattern.compile("\\A" + expression + "\\z");
    }

    private static String classEscape(char value) {
        return value == '\\' || value == ']' || value == '^' || value == '-'
                ? "\\" + value : String.valueOf(value);
    }

    private static boolean hasQuote(String text) {
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '“' || c == '”' || c == '‘' || c == '’' || c == '"' || c == '\'') return true;
        }
        return false;
    }

    private static String outsideQuotedText(String text) {
        StringBuilder out = new StringBuilder(text);
        char close = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (close == 0) {
                if (c == '“' || c == '‘' || c == '"' || c == '\'') {
                    close = c == '“' ? '”' : c == '‘' ? '’' : c;
                    out.setCharAt(i, ' ');
                }
            } else {
                out.setCharAt(i, ' ');
                if (c == close) close = 0;
            }
        }
        return out.toString();
    }

    private static boolean validOwner(String owner) {
        if (owner == null || owner.isEmpty() || owner.indexOf('\0') >= 0
                || owner.indexOf('\r') >= 0 || owner.indexOf('\n') >= 0
                || owner.contains("<|") || owner.contains("<__image__>")
                || owner.getBytes(StandardCharsets.UTF_8).length > 1600) return false;
        for (int i = 0; i < owner.length(); i++) {
            char c = owner.charAt(i);
            if (Character.isHighSurrogate(c)) {
                if (i + 1 >= owner.length() || !Character.isLowSurrogate(owner.charAt(++i))) return false;
            } else if (Character.isLowSurrogate(c) || Character.isISOControl(c) && c != '\t') return false;
        }
        return true;
    }

    private static Result refused(String owner, boolean draft, String reason) {
        return new Result(owner, false, null, -1, -1, "unsupported_natural_note_request", draft, false, reason);
    }
}

package org.trillionnium.hepta.local;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Collections;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/** Exact labels already supplied in one prompt; never resolves a label to a new ID. */
public final class ObservedTargetLabels {
    public static final String SCHEMA="hepta.observed-target-labels.v1";
    public static final String ACTION_SCHEMA="hepta.observed-action-gbnf.v3-label-first";
    public static final String ENCODING="utf8-length-prefixed-be32-sorted-node-id.v1";
    public static final int PROJECTION_UTF16_LIMIT=36;
    public final String observationId,packageName,sha256;
    public final Map<String,String> labels;

    private ObservedTargetLabels(String observationId,String packageName,Map<String,String> labels){
        this.observationId=observationId;this.packageName=packageName;
        this.labels=Collections.unmodifiableMap(new TreeMap<String,String>(labels));
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();
        field(bytes,SCHEMA);field(bytes,ENCODING);field(bytes,observationId);field(bytes,packageName);
        integer(bytes,this.labels.size());
        for(Map.Entry<String,String> pair:this.labels.entrySet()){field(bytes,pair.getKey());field(bytes,pair.getValue());}
        try{
            StringBuilder hex=new StringBuilder(64);
            for(byte value:MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()))hex.append(String.format(Locale.ROOT,"%02x",value&255));
            sha256=hex.toString();
        }catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
    public static ObservedTargetLabels create(String schema,String observationId,String packageName,Map<String,String> labels){
        if(!SCHEMA.equals(schema))throw new IllegalArgumentException("unknown observed-target label schema");
        if(observationId==null||!observationId.matches("[0-9a-f]{32}"))throw new IllegalArgumentException("invalid observed-target identity");
        if(packageName==null||packageName.length()>255||(!"android".equals(packageName)&&!packageName.matches("[A-Za-z][A-Za-z0-9_]*(?:\\.[A-Za-z][A-Za-z0-9_]*)+")))
            throw new IllegalArgumentException("invalid observed-target package");
        if(labels==null||labels.size()>200)throw new IllegalArgumentException("invalid observed-target projection");
        for(Map.Entry<String,String> pair:labels.entrySet()){
            if(pair.getKey()==null||!pair.getKey().matches("n[0-9]{1,5}"))throw new IllegalArgumentException("invalid observed-target node ID");
            requireProjectedLabel(pair.getValue());
        }
        return new ObservedTargetLabels(observationId,packageName,labels);
    }
    /** Preserves the pre-existing 36 UTF-16-unit projection and its ellipsis. */
    public static String project(String raw){
        validUnicode(raw);
        if(raw.length()<=PROJECTION_UTF16_LIMIT)return raw;
        int end=PROJECTION_UTF16_LIMIT;
        if(Character.isHighSurrogate(raw.charAt(end-1)))end--;
        return raw.substring(0,end)+"…";
    }
    public static void requireProjectedLabel(String label){
        validUnicode(label);
        if(label.length()>PROJECTION_UTF16_LIMIT+1)throw new IllegalArgumentException("node_label exceeds supplied projection bound");
    }
    public boolean matches(String observation,String packageValue,String nodeId,String nodeLabel){
        return observationId.equals(observation)&&packageName.equals(packageValue)&&nodeId!=null
                &&nodeLabel!=null&&labels.containsKey(nodeId)&&labels.get(nodeId).equals(nodeLabel);
    }
    private static void validUnicode(String value){
        if(value==null)throw new IllegalArgumentException("missing node label");
        for(int i=0;i<value.length();i++){
            char c=value.charAt(i);
            if(Character.isHighSurrogate(c)){
                if(i+1>=value.length()||!Character.isLowSurrogate(value.charAt(++i)))throw new IllegalArgumentException("invalid node-label surrogate");
            }else if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid node-label surrogate");
        }
    }
    private static void integer(ByteArrayOutputStream out,int value){
        out.write((value>>>24)&255);out.write((value>>>16)&255);out.write((value>>>8)&255);out.write(value&255);
    }
    private static void field(ByteArrayOutputStream out,String value){
        byte[] bytes=value.getBytes(StandardCharsets.UTF_8);integer(out,bytes.length);out.write(bytes,0,bytes.length);
    }
}

package org.trillionnium.hepta.local;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Collections;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/** Exact current prompt app pairs, keyed by original package; never resolves a label. */
public final class ObservedAppLabels {
    public static final String SCHEMA="hepta.observed-app-labels.v1";
    public static final String ACTION_SCHEMA="hepta.observed-action-gbnf.v4-app-label-first";
    public static final String ENCODING="utf8-length-prefixed-be32-sorted-package.v1";
    public static final int PROJECTION_UTF16_LIMIT=48;
    public final String observationId,currentPackage,sha256;
    public final Map<String,String> labels;

    private ObservedAppLabels(String observationId,String currentPackage,Map<String,String> labels){
        this.observationId=observationId;this.currentPackage=currentPackage;
        this.labels=Collections.unmodifiableMap(new TreeMap<String,String>(labels));
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();
        field(bytes,SCHEMA);field(bytes,ENCODING);field(bytes,observationId);field(bytes,currentPackage);
        integer(bytes,this.labels.size());
        for(Map.Entry<String,String> pair:this.labels.entrySet()){field(bytes,pair.getKey());field(bytes,pair.getValue());}
        try{
            StringBuilder hex=new StringBuilder(64);
            for(byte value:MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()))hex.append(String.format(Locale.ROOT,"%02x",value&255));
            sha256=hex.toString();
        }catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }

    public static ObservedAppLabels create(String schema,String observationId,String currentPackage,Map<String,String> labels){
        if(!SCHEMA.equals(schema))throw new IllegalArgumentException("unknown observed-app label schema");
        if(observationId==null||!observationId.matches("[0-9a-f]{32}"))throw new IllegalArgumentException("invalid observed-app identity");
        checkPackage(currentPackage,true);
        if(labels==null||labels.size()>40)throw new IllegalArgumentException("invalid observed-app projection");
        for(Map.Entry<String,String> pair:labels.entrySet()){
            checkPackage(pair.getKey(),false);
            if(currentPackage.equals(pair.getKey()))throw new IllegalArgumentException("current package cannot be opened");
            requireProjectedLabel(pair.getValue());
        }
        return new ObservedAppLabels(observationId,currentPackage,labels);
    }

    /** Preserve the existing prompt's 48 UTF-16-unit projection and ellipsis. */
    public static String project(String raw){
        validUnicode(raw);
        if(raw.length()<=PROJECTION_UTF16_LIMIT)return raw;
        int end=PROJECTION_UTF16_LIMIT;
        if(Character.isHighSurrogate(raw.charAt(end-1)))end--;
        return raw.substring(0,end)+"…";
    }

    public static void requireProjectedLabel(String label){
        validUnicode(label);
        if(label.length()>PROJECTION_UTF16_LIMIT+1)throw new IllegalArgumentException("app_label exceeds supplied projection bound");
    }

    public boolean matches(String observation,String current,String targetPackage,String appLabel){
        return observationId.equals(observation)&&currentPackage.equals(current)&&targetPackage!=null&&appLabel!=null
                &&labels.containsKey(targetPackage)&&labels.get(targetPackage).equals(appLabel);
    }

    private static void checkPackage(String value,boolean allowSystem){
        if(value==null||value.length()>255||(!(allowSystem&&"android".equals(value))
                &&!value.matches("[A-Za-z][A-Za-z0-9_]*(?:\\.[A-Za-z][A-Za-z0-9_]*)+")))
            throw new IllegalArgumentException("invalid observed-app package");
    }
    private static void validUnicode(String value){
        if(value==null||value.indexOf('\0')>=0)throw new IllegalArgumentException("missing or NUL app label");
        for(int i=0;i<value.length();i++){
            char c=value.charAt(i);
            if(Character.isHighSurrogate(c)){
                if(i+1>=value.length()||!Character.isLowSurrogate(value.charAt(++i)))throw new IllegalArgumentException("invalid app-label surrogate");
            }else if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid app-label surrogate");
        }
    }
    private static void integer(ByteArrayOutputStream out,int value){
        out.write((value>>>24)&255);out.write((value>>>16)&255);out.write((value>>>8)&255);out.write(value&255);
    }
    private static void field(ByteArrayOutputStream out,String value){
        byte[] bytes=value.getBytes(StandardCharsets.UTF_8);integer(out,bytes.length);out.write(bytes,0,bytes.length);
    }
}

package org.trillionnium.hepta.background;

/** Closed local tool contracts shared by the ordinary app and background broker.
 * No Android dispatch, authorization, URI, model-supplied component or extras map.
 */
public final class FixedIntentTools {
    public static final String NOTES_CREATE = "notes.create";
    public static final String WEB_SEARCH = "web.search";

    private static final Profile NOTES = new Profile(NOTES_CREATE,
            "com.motorola.stylus", "com.motorola.stylus.note.text.TextNoteActivity",
            "android.intent.action.SEND", "text/plain", "android.intent.extra.TEXT", "draft_opened");
    private static final Profile SEARCH = new Profile(WEB_SEARCH,
            "com.zui.browser", "com.lenovo.browser.BrowserActivity",
            "android.intent.action.WEB_SEARCH", null, "query", "search_opened");

    private FixedIntentTools() { }

    /** Exact identifiers only; unknown actions have no executable profile. */
    public static Profile forAction(String action) {
        if (NOTES_CREATE.equals(action)) return NOTES;
        if (WEB_SEARCH.equals(action)) return SEARCH;
        return null;
    }

    public static boolean isTool(String action) {
        return forAction(action) != null;
    }

    public static final class Profile {
        public final String action;
        public final String packageName;
        public final String className;
        public final String intentAction;
        public final String mimeType;
        public final String extraName;
        /** Requested observation label; a launch acceptance does not prove opened or saved. */
        public final String outcome;
        public final int maxUtf8Bytes = 4096;
        public final int maxCodePoints = 1024;

        private Profile(String action, String packageName, String className,
                        String intentAction, String mimeType, String extraName, String outcome) {
            this.action = action;
            this.packageName = packageName;
            this.className = className;
            this.intentAction = intentAction;
            this.mimeType = mimeType;
            this.extraName = extraName;
            this.outcome = outcome;
        }

        /** Validate without trimming, normalizing or rewriting the caller's text.
         * LF/CR/tab and Unicode text are retained. Errors never echo the payload.
         */
        public void validatePayload(String payload) {
            if (payload == null || payload.isEmpty())
                throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_REQUIRED");
            if (payload.length() > maxCodePoints * 2)
                throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_TOO_LONG");
            int scalars = 0;
            int utf8Bytes = 0;
            boolean hasContent = false;
            for (int offset = 0; offset < payload.length();) {
                char first = payload.charAt(offset++);
                int point;
                if (Character.isHighSurrogate(first)) {
                    if (offset == payload.length() || !Character.isLowSurrogate(payload.charAt(offset)))
                        throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_INVALID_UNICODE");
                    point = Character.toCodePoint(first, payload.charAt(offset++));
                } else {
                    if (Character.isLowSurrogate(first))
                        throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_INVALID_UNICODE");
                    point = first;
                }
                if (point == 0) throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_NUL");
                scalars++;
                utf8Bytes += point <= 0x7f ? 1 : point <= 0x7ff ? 2 : point <= 0xffff ? 3 : 4;
                if (scalars > maxCodePoints || utf8Bytes > maxUtf8Bytes)
                    throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_TOO_LONG");
                hasContent |= !Character.isWhitespace(point) && !Character.isSpaceChar(point);
            }
            if (!hasContent) throw new IllegalArgumentException("FIXED_TOOL_PAYLOAD_BLANK");
        }
    }
}

package org.trillionnium.hepta.background;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/** Installed facts supplied by trusted PackageManager inspection, never model fields. */
public final class FixedIntentTarget {
    public final String action, packageName, className, appLabel, permission;
    public final int uid;
    public FixedIntentTarget(String action,String label,int uid,String permission){
        FixedIntentTools.Profile profile=FixedIntentTools.forAction(action);
        if(profile==null||label==null||label.length()>512||label.indexOf('\0')>=0||uid<10000||uid>=90000)
            throw new IllegalArgumentException("fixed intent installed identity required");
        for(int i=0;i<label.length();i++){
            char c=label.charAt(i);
            if(Character.isHighSurrogate(c)){if(++i>=label.length()||!Character.isLowSurrogate(label.charAt(i)))throw new IllegalArgumentException("invalid app label");}
            else if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid app label");
        }
        this.action=action;this.packageName=profile.packageName;this.className=profile.className;
        this.appLabel=label;this.uid=uid;this.permission=permission==null||permission.isEmpty()?null:permission;
    }
    public boolean sameIdentity(FixedIntentTarget other){
        return other!=null&&action.equals(other.action)&&uid==other.uid&&packageName.equals(other.packageName)
                &&className.equals(other.className)&&appLabel.equals(other.appLabel)&&Objects.equals(permission,other.permission);
    }
    public static String payloadSha256(String value){
        if(value==null)throw new IllegalArgumentException("payload required");
        try{StringBuilder hex=new StringBuilder(64);for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)))hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return hex.toString();}
        catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
    public Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("source","installed_package_manager");out.put("action",action);out.put("package",packageName);
        out.put("component",packageName+"/"+className);out.put("target_uid",uid);out.put("app_label",appLabel);
        out.put("exported",true);out.put("activity_enabled",true);out.put("application_enabled",true);
        out.put("declared_intent_filter_matched",true);out.put("required_permission",permission);
        out.put("ordinary_caller_permission_checked",true);return out;
    }
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.trillionnium.hepta.local.web.WebFlightGoal;
import org.trillionnium.hepta.local.web.WebShoppingGoal;

/** A bounded OWNER compiler and task-local executor contract, never a model proposal.
 * This enforces documented tool/method clauses, not arbitrary business semantics. */
public final class TaskAuthorization {
    public static final String SCHEMA="hepta.owner-task-authorization.v1";
    public static final String PARSER="hepta.owner-tool-clauses.zh.v4-fixed-intents";
    public static final String NATURAL_FLIGHT_RULE="natural_public_flight_tool_ceiling.v1";
    public static final String NATURAL_SHOPPING_RULE="natural_public_product_tool_ceiling.v1";
    public static final String EXPLICIT_SHOPPING_RULE="explicit_public_product_tool_ceiling.v1";
    public static final Set<String> TOOLS=Collections.unmodifiableSet(new TreeSet<String>(Arrays.asList(
            "find_app","open","click","type","submit","scroll","back","home","wait","done","notes.create","web.search")));
    public static final class Violation extends IllegalStateException {
        private static final long serialVersionUID=1L;
        Violation(String message){super("task_authorization: "+message);}
    }
    static void require(boolean value,String message){if(!value)throw new Violation(message);}
    private static final Map<String,String> NAMES;
    static {
        Map<String,String> names=new LinkedHashMap<String,String>();
        String[][] rows={{"find_app","查找本机应用","查找应用","查找","find_app"},
                {"open","打开应用","打开","open"},{"click","点击","click"},{"type","输入","type"},
                {"submit","提交输入","提交","submit"},
                {"notes.create","创建笔记","新建笔记","写备忘录","notes.create"},
                {"web.search","网页搜索","网页查询","web.search"},
                {"scroll","滚动","scroll"},{"back","返回上一页","返回","back"},
                {"home","回到桌面","返回桌面","home"},{"wait","等待","wait"},
                {"done","结束任务","结束","done"}};
        for(String[] row:rows)for(int i=1;i<row.length;i++)names.put(row[i],row[0]);
        NAMES=Collections.unmodifiableMap(names);
    }
    private static final Pattern ONLY=Pattern.compile("^(?:请)?(?:本任务|这次任务)?(?:只|仅)(?:允许|可|能)?(?:使用|调用|执行)?(.+)$");
    private static final Pattern DENY=Pattern.compile("^(?:请)?(?:不要|不得|禁止|不允许|不能|不)(?:直接|自动|再次|随意)?(.+)$");
    private static final Pattern GRANT=Pattern.compile("^(?:但|但是)?(?:可以|允许)(.+)$");
    private static final Pattern EXCEPTION=Pattern.compile("(?:除非|除了|否则|但是|但可以|但允许|不过|如果|若|而是)");
    private static final Pattern SEQUENCE=Pattern.compile("先([^。；;\\n]*?)(?:再|然后)([^。；;\\n]*)");
    private static final Pattern QUOTED_QUERY=Pattern.compile("(?:搜索|查找)\\s*[‘“\"']([^‘’“”\"'\\r\\n]{1,64})[’”\"']");
    private static final Pattern NAMED_QUERY=Pattern.compile("(?:查找|搜索)(?:手机上|本机|手机中)?(?:已安装的|安装的)?([^，,。；;\\n]{1,64}?)(?:应用|APP|App)?[，,\\s]*$");
    // An app-discovery prerequisite needs an explicit application/tool domain.
    // "查找机票/商品，再打开详情" describes app content, not installed apps.
    // This pattern only sees quote-masked text; quoted payload is never authority.
    private static final Pattern APP_LOOKUP=Pattern.compile(
            "(?<![A-Za-z0-9_])find_app(?![A-Za-z0-9_])"
            +"|(?:查找|搜索)(?:手机上|本机|手机中)?(?:已安装的|安装的)"
            +"|(?:查找|搜索)[^，,。；;\\n]{0,96}?(?:应用|APP|App)(?=[，,。；;\\s]|$|并|再|然后)");
    public final String instructionSha256,sha256,findQuery;
    private final String parserVersion;
    public final Set<String> allowedTools;
    public final boolean requireFindAppBeforeOpen;
    private final List<String> rules;
    private final String immutableOwner;

    private TaskAuthorization(String owner,Set<String> allowed,boolean first,String query,List<String> rules){
        immutableOwner=owner;
        instructionSha256=hash(owner.getBytes(StandardCharsets.UTF_8));
        allowedTools=Collections.unmodifiableSet(new TreeSet<String>(allowed));
        requireFindAppBeforeOpen=first;findQuery=query;
        this.rules=Collections.unmodifiableList(new ArrayList<String>(rules));
        String parser=rules.contains("notes_literal_owner_span.v1")?PARSER+"+notes-literal-span.v1":PARSER;
        if(rules.contains(NATURAL_FLIGHT_RULE))parser+="+natural-flight-ceiling.v1";
        if(rules.contains(NATURAL_SHOPPING_RULE))parser+="+natural-product-ceiling.v1";
        if(rules.contains(EXPLICIT_SHOPPING_RULE))parser+="+explicit-product-ceiling.v1";
        parserVersion=parser;
        // Length-delimited fields bind exact UTF-8, including the optional query.
        StringBuilder identity=new StringBuilder();field(identity,SCHEMA);field(identity,parserVersion);field(identity,instructionSha256);
        for(String tool:allowedTools)field(identity,tool);field(identity,first?"true":"false");field(identity,query==null?"":query);
        sha256=hash(identity.toString().getBytes(StandardCharsets.UTF_8));
    }
    /** The service compiles its task phase from the same OWNER; never model or screen text. */
    String immutableOwner(){return immutableOwner;}
    public static TaskAuthorization parse(String owner){
        validOwner(owner);
        NotesOwnerIntent.Result note=NotesOwnerIntent.parse(owner);
        boolean maskBody=note.masksOwnerBodyForAuthority();
        String unquoted=withoutQuotedData(maskBody?note.maskedOwnerForAuthority(owner):owner);
        Set<String> allowed=new TreeSet<String>(TOOLS),denied=new TreeSet<String>(),granted=new TreeSet<String>();
        List<String> rules=new ArrayList<String>();boolean onlySeen=false;
        if(maskBody)rules.add("notes_literal_owner_span.v1");
        for(String original:unquoted.split("[，,。；;！!？?\\r\\n]")){
            String clause=original.trim();if(clause.isEmpty())continue;
            Matcher only=ONLY.matcher(clause),deny=DENY.matcher(clause),grant=GRANT.matcher(clause);
            if(only.matches()&&(startsTool(only.group(1))||clause.matches("^(?:请)?(?:本任务|这次任务)?(?:只|仅)(?:允许|可|能).*$"))){
                require(!EXCEPTION.matcher(clause).find(),"工具白名单含不支持的条件或例外");
                Set<String> listed=toolList(only.group(1),true);
                if(onlySeen)allowed.retainAll(listed);else{allowed.clear();allowed.addAll(listed);onlySeen=true;}
                rules.add("only_tools");
            }else if(deny.matches()){
                String body=deny.group(1).trim();
                if(startsNegation(body)&&containsTool(body))throw new Violation("工具限制含双重否定，不能推断授权");
                if(startsTool(body)){
                    require(!EXCEPTION.matcher(clause).find(),"工具禁止条款含不支持的条件或例外");
                    denied.addAll(toolList(body,false));rules.add("deny_tools");
                }
            }else if(grant.matches()&&startsTool(grant.group(1))){
                granted.addAll(toolList(grant.group(1),false));
            }
            // A limited explicit method clause. It forbids SET_TEXT, not key clicks.
            if(clause.matches(".*(?:使用|通过)[^。；;]{0,40}(?:按键|逐个按键|按按钮)(?:输入|计算|操作|完成).*$")){
                denied.add("type");rules.add("observed_keys_no_type");
            }
        }
        for(String tool:denied)require(!granted.contains(tool),"工具允许与禁止冲突");
        if(onlySeen)for(String tool:granted)require(allowed.contains(tool),"工具白名单后出现扩大授权的条款");
        allowed.removeAll(denied);
        boolean first=false;String query=null;
        // Masking preserves UTF-16 offsets. Recognize the method in unquoted
        // text, then recover its literal query from the same original span.
        Matcher sequence=SEQUENCE.matcher(unquoted);
        while(sequence.find()){
            String before=sequence.group(1),after=sequence.group(2);
            if(explicitAppLookup(before)&&(after.contains("打开")||after.contains("open"))){
                require(!first,"多个查找前置目标暂不支持");
                require(!EXCEPTION.matcher(before).find(),"查找前置条件有歧义");
                query=queryFrom(owner.substring(sequence.start(1),sequence.end(1)));first=true;rules.add("find_app_before_open");
            }
        }
        if(!first&&unquoted.contains("先")&&explicitAppLookup(unquoted)
                &&(unquoted.contains("打开")||unquoted.contains("open")))
            throw new Violation("查找与打开顺序不在已支持的明确先后语法内");
        // Every original OWNER clause, error and prerequisite above remains in force.
        // Recognized public-page purposes only narrow that result. They never mask,
        // expand or rewrite OWNER, and selected-helper admission is checked separately.
        WebFlightGoal flight=WebFlightGoal.parse(owner);
        WebShoppingGoal shopping=WebShoppingGoal.parse(owner);
        require(flight==null||shopping==null,"公开网页目标不能同时属于两个站点");
        if(flight!=null&&flight.naturalReadOnlyIntent){
            allowed.retainAll(flight.toolCeiling());rules.add(NATURAL_FLIGHT_RULE);
        }else if(shopping!=null){
            allowed.retainAll(shopping.toolCeiling());
            rules.add(shopping.naturalReadOnlyIntent?NATURAL_SHOPPING_RULE:EXPLICIT_SHOPPING_RULE);
        }
        if(first)require(allowed.contains("find_app")&&allowed.contains("open"),"查找前置与工具限制冲突");
        return new TaskAuthorization(owner,allowed,first,query,rules);
    }
    private static boolean explicitAppLookup(String text){return APP_LOOKUP.matcher(text.trim()).find();}
    private static String queryFrom(String before){
        Matcher quoted=QUOTED_QUERY.matcher(before);String query=null;
        if(quoted.find()){query=quoted.group(1);require(!quoted.find(),"查找前置含多个文字目标");}
        if(query==null){Matcher named=NAMED_QUERY.matcher(before);if(named.find())query=named.group(1).trim();}
        require(query!=null&&!query.isEmpty(),"查找前置需要明确的应用名称或搜索文字");
        require(!query.matches(".*(?:工具|find_app|先|再|然后|允许|禁止|不要|不得|或|或者|以及|和).*$"),"查找目标不在已支持的单一文字范围");
        AppCatalogueRanker.validateQuery(query);
        return query;
    }
    private static boolean startsNegation(String value){return value.startsWith("不")||value.startsWith("禁止")||value.startsWith("不得");}
    private static boolean containsTool(String value){for(String name:NAMES.keySet())if(value.contains(name))return true;return false;}
    private static boolean startsTool(String value){return toolPrefix(value.trim())!=null;}
    private static String toolPrefix(String value){
        String best=null;for(String name:NAMES.keySet())if(value.startsWith(name)&&(best==null||name.length()>best.length()))best=name;
        return best;
    }
    private static Set<String> toolList(String text,boolean exact){
        Set<String> result=new TreeSet<String>();
        for(String item:text.trim().split("(?:、|和|及|与|或)")){
            String value=item.trim();
            if(!exact){Matcher repeated=DENY.matcher(value);if(repeated.matches()){
                value=repeated.group(1).trim();require(!startsNegation(value),"工具列表含双重否定");
            }}
            String prefix=toolPrefix(value);
            require(prefix!=null,"工具列表包含未知项目");
            String suffix=value.substring(prefix.length()).trim();
            if(exact)require(suffix.isEmpty()||suffix.equals("工具")||suffix.equals("操作"),"只允许列表必须是完整工具名，不支持隐含例外或参数");
            else require(!startsNegation(suffix)&&!EXCEPTION.matcher(suffix).find(),"工具禁止条款尾部有歧义");
            result.add(NAMES.get(prefix));
        }
        require(!result.isEmpty(),"工具列表为空");return result;
    }
    private static String withoutQuotedData(String owner){
        StringBuilder out=new StringBuilder(owner);char close=0;int begin=-1;
        for(int i=0;i<owner.length();i++){
            char c=owner.charAt(i);
            if(close==0){
                if(c=='“'||c=='‘'||c=='\"'||c=='\''){close=c=='“'?'”':c=='‘'?'’':c;begin=i;out.setCharAt(i,' ');}
            }else{
                out.setCharAt(i,' ');
                if(c==close){
                    String quoted=owner.substring(begin+1,i);
                    require(!(containsTool(quoted)&&(quoted.contains("不")||quoted.contains("禁止")||quoted.contains("只允许")||quoted.contains("仅允许"))),"引用文字内含工具限制，无法确定是数据还是授权");
                    close=0;
                }
            }
        }
        require(close==0,"任务中的引号未闭合");return out.toString();
    }
    private static void validOwner(String owner){
        require(owner!=null&&!owner.trim().isEmpty(),"用户任务不能为空");
        require(owner.indexOf('\0')<0&&!owner.contains("<|")&&!owner.contains("<__image__>")&&owner.getBytes(StandardCharsets.UTF_8).length<=1600,"用户任务太长或包含不支持的字符");
        for(int i=0;i<owner.length();i++){
            char c=owner.charAt(i);
            if(Character.isHighSurrogate(c))require(i+1<owner.length()&&Character.isLowSurrogate(owner.charAt(++i)),"用户任务含无效字符");
            else require(!Character.isLowSurrogate(c),"用户任务含无效字符");
        }
    }
    public boolean allows(String tool){return allowedTools.contains(tool);}
    public void requireOwner(String owner){validOwner(owner);require(instructionSha256.equals(hash(owner.getBytes(StandardCharsets.UTF_8))),"用户任务与授权合同不一致");}
    public Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema",SCHEMA);out.put("parser",parserVersion);
        out.put("instruction_sha256",instructionSha256);out.put("authorization_sha256",sha256);
        out.put("allowed_tools",new ArrayList<String>(allowedTools));out.put("require_find_app_before_open",requireFindAppBeforeOpen);
        out.put("find_query",findQuery);out.put("recognized_rules",new ArrayList<String>(rules));
        out.put("arbitrary_semantic_constraints_verified",false);return out;
    }
    public String summary(){
        Map<String,String> display=new LinkedHashMap<String,String>();
        display.put("find_app","查找应用");display.put("open","打开应用");display.put("click","点击");display.put("type","输入文字");
        display.put("submit","提交已观察查询字段");
        display.put("notes.create","打开本地笔记草稿");display.put("web.search","打开网页查询");
        display.put("scroll","滚动");display.put("back","返回");display.put("home","回桌面");display.put("wait","等待");display.put("done","成功结束");
        List<String> names=new ArrayList<String>();for(String tool:display.keySet())if(allowedTools.contains(tool))names.add(display.get(tool));
        return "已识别的工具权限："+names+(requireFindAppBeforeOpen?"；须先查找“"+findQuery+"”并打开真实结果才能成功结束":"")
                +"。可随时停止或报告未完成；页面目标和其它语义条件仍需核对。";
    }
    public Gate bind(String taskId){return new Gate(this,taskId);}
    private static void field(StringBuilder out,String value){out.append(value.getBytes(StandardCharsets.UTF_8).length).append(':').append(value).append('\n');}
    private static String hash(byte[] value){
        try{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(value))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
        catch(Exception impossible){throw new IllegalStateException(impossible);}
    }

    /** Immutable grammar/policy view. Its contract can only be narrowed by task evidence. */
    public static final class Frame {
        public final TaskAuthorization authorization;
        public final String taskId,discoveryRunId,openedPackage;
        public final Set<String> foundPackages;
        private Frame(Gate gate){authorization=gate.authorization;taskId=gate.taskId;discoveryRunId=gate.discoveryRunId;
            openedPackage=gate.openedPackage;foundPackages=Collections.unmodifiableSet(new TreeSet<String>(gate.foundPackages));}
        public boolean allows(String tool){
            if("done".equals(tool))return true; // partial/failure are always safe termination controls.
            if(!authorization.allows(tool))return false;
            return !authorization.requireFindAppBeforeOpen||openedPackage!=null||"find_app".equals(tool)||"open".equals(tool)||"wait".equals(tool);
        }
        public boolean successAllowed(){return authorization.allows("done")&&(!authorization.requireFindAppBeforeOpen||openedPackage!=null);}
        public Set<String> openPackages(Set<String> projected){
            Set<String> out=new TreeSet<String>(projected);
            if(!allows("open"))out.clear();else if(authorization.requireFindAppBeforeOpen)out.retainAll(foundPackages);
            return out;
        }
        public void requireDecision(ActionDecision action){
            require(action!=null,"动作缺失");
            if("done".equals(action.action)){require(!"success".equals(action.status)||successAllowed(),"尚未满足用户要求的方法，不允许成功结束");return;}
            require(allows(action.action),"用户未授权此工具或前置查找/打开未完成："+action.action);
            if("find_app".equals(action.action)&&authorization.requireFindAppBeforeOpen)
                require(authorization.findQuery.equals(action.query),"查找文字必须等于用户指定的文字");
            if("open".equals(action.action)&&authorization.requireFindAppBeforeOpen)
                require(discoveryRunId!=null&&foundPackages.contains(action.packageName),"打开目标没有同任务真实查找证明");
        }
        public Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>(authorization.evidence());out.put("task_id",taskId);
            out.put("discovery_run_id",discoveryRunId);out.put("found_packages",new ArrayList<String>(foundPackages));
            out.put("opened_package",openedPackage);out.put("success_done_allowed",successAllowed());return out;
        }
    }
    /** Service-owned state. Only actual local catalogue reads and dispatched opens advance it. */
    public static final class Gate {
        public final TaskAuthorization authorization;public final String taskId;
        private final Set<String> foundPackages=new TreeSet<String>();
        private boolean retired;private String refusal,catalogueSha,discoveryRunId,discoveryObservationId;
        private String openRunId,pendingOpen,openedPackage,openedObservationId;
        private Map<String,Object> lastCheck=Collections.emptyMap();
        private Gate(TaskAuthorization authorization,String taskId){require(authorization!=null&&taskId!=null&&taskId.matches("[0-9a-f]{32}"),"任务授权绑定无效");this.authorization=authorization;this.taskId=taskId;}
        public synchronized Frame frame(){ready();return new Frame(this);}
        public synchronized void ready(){require(!retired,"任务授权已退休");require(refusal==null,refusal==null?"":refusal);}
        public synchronized void retire(){retired=true;}
        public synchronized void bindCatalogue(AppCatalogueRanker.Page page){
            ready();require(page!=null&&catalogueSha==null,"初始应用目录缺失或重复");catalogueSha=page.catalogueSha256;
            // Initial projection is deliberately not a successful model-issued lookup.
        }
        public synchronized void check(ActionDecision action,String modelRunId){
            Map<String,Object> proof=new LinkedHashMap<String,Object>();proof.put("schema","hepta.owner-action-check.v1");
            proof.put("task_id",taskId);proof.put("authorization_sha256",authorization.sha256);proof.put("model_run_id",modelRunId);
            proof.put("action",action==null?null:action.action);proof.put("target_package",action==null?null:action.packageName);
            if(action!=null&&action.toolChildOrigin!=null){proof.put("actor_kind","tool_child");proof.put("model_issued",false);
                proof.put("parent_model_run_id",modelRunId);}
            try{ready();require(modelRunId!=null&&modelRunId.matches("[0-9a-f]{32}"),"模型运行身份缺失");new Frame(this).requireDecision(action);proof.put("allowed",true);}
            catch(Violation error){refusal=error.getMessage();proof.put("allowed",false);proof.put("reason",refusal);throw error;}
            finally{lastCheck=Collections.unmodifiableMap(proof);}
        }
        synchronized void found(ActionDecision action,String modelRunId,AppCatalogueRanker.Page page){
            check(action,modelRunId);
            require("find_app".equals(action.action)&&page!=null&&catalogueSha!=null&&catalogueSha.equals(page.catalogueSha256)
                    &&action.query.equals(page.query)&&action.offset==page.offset,"实际查找回执不属于本次目录/查询");
            foundPackages.clear();for(AppCatalogueRanker.Entry app:page.apps)foundPackages.add(app.packageName);
            discoveryRunId=modelRunId;discoveryObservationId=action.observationId;
        }
        synchronized void opened(ActionDecision action,String modelRunId){
            check(action,modelRunId);require("open".equals(action.action),"非打开动作不能授予打开证明");
            pendingOpen=action.packageName;openRunId=modelRunId;
        }
        synchronized void observed(String packageName,String observationId){
            ready();require(observationId!=null&&observationId.matches("[0-9a-f]{32}"),"观察身份缺失");
            if(pendingOpen!=null&&pendingOpen.equals(packageName)){openedPackage=pendingOpen;openedObservationId=observationId;pendingOpen=null;}
        }
        public synchronized Map<String,Object> evidence(){
            Map<String,Object> out=new Frame(this).evidence();out.put("catalogue_sha256",catalogueSha);
            out.put("discovery_observation_id",discoveryObservationId);out.put("open_run_id",openRunId);
            out.put("opened_observation_id",openedObservationId);out.put("pending_open_package",pendingOpen);
            out.put("retired",retired);out.put("refused",refusal!=null);out.put("refusal",refusal);
            out.put("last_check",new LinkedHashMap<String,Object>(lastCheck));return out;
        }
    }
}

package org.trillionnium.hepta.local.web;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.DateTimeException;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Isolated candidate. A complete literal read-only flight goal, not tool authority.
 * The real phone TaskAuthorization must independently compile the identical OWNER.
 * This class neither opens a URL nor treats a query form as a flight result.
 */
public final class WebFlightGoal {
    public static final String SCHEMA = "hepta.web-flight-owner.csair.v1";
    public static final String NATURAL_SCHEMA = "hepta.web-flight-owner.csair.v2";
    public static final String NATURAL_RECOGNITION = "natural_explicit_date_single_adult_flight_query.v1";
    public static final String TAIL = "请核对实际出发日期、出发和到达机场、航班号、起降时间、公开显示的价格与币种，并注明价格包含或未注明的税费及条件。"
            + "只允许click、type、submit、scroll、back、wait、done。"
            + "输入和提交仅用于公开的城市、日期、人数及航班查询；不要登录、注册、同意授权、加购、预订、下单、支付或修改账号和权限。"
            + "遇到这些要求、访问阻断或资料不完整就停止并报告未完成。这是测试路线，不代表用户行程。";
    public static final String BACKGROUND_TAIL = TAIL.replace("只允许click、", "只允许open、click、");
    private static final Pattern OWNER = Pattern.compile(
            "网页查询测试：在南航官方网站查询([0-9]{4})年([0-9]{1,2})月([0-9]{1,2})日"
            + "([\\p{IsHan}]{2,12})到([\\p{IsHan}]{2,12})的单程航班，1名成人。" + Pattern.quote(TAIL));
    private static final Pattern BACKGROUND_OWNER = Pattern.compile(
            "网页查询测试：在南航官方网站查询([0-9]{4})年([0-9]{1,2})月([0-9]{1,2})日"
            + "([\\p{IsHan}]{2,12})到([\\p{IsHan}]{2,12})的单程航班，1名成人。" + Pattern.quote(BACKGROUND_TAIL));
    private static final String NATURAL_PREFIX = "(?:请)?(?:帮我)?(?:查一下|查询|查查)"
            + "(?:(?:南航|中国南方航空)(?:官网|官方网站)(?:上|的)?)?";
    private static final String NATURAL_ROUTE = "(?:从)?([\\p{IsHan}]{2,12}?)到([\\p{IsHan}]{2,12}?)"
            + "(?:的)?单程(?:机票|航班)[，,](?:1|一)(?:名|位)成人[。]?";
    private static final Pattern NATURAL_DATE = Pattern.compile(NATURAL_PREFIX
            + "([0-9]{4})年([0-9]{1,2})月([0-9]{1,2})日" + NATURAL_ROUTE);
    private static final Pattern NATURAL_ISO_DATE = Pattern.compile(NATURAL_PREFIX
            + "([0-9]{4})-([0-9]{2})-([0-9]{2})" + NATURAL_ROUTE);
    /** Recognition is not a grant; TaskAuthorization still compiles the original OWNER. */
    public final boolean naturalReadOnlyIntent;
    public final String contractSchema,recognition,providerSelection;
    /** Explicit OWNER token, not a grant and not proof that a background lease exists. */
    public final boolean ownerContainsOpen;
    public final String immutableOwner, ownerSha256, contractSha256, fromCity, toCity;
    public final LocalDate departureDate;
    public final int adults = 1, children = 0, infants = 0;
    public final int dateStartUtf16, dateEndUtf16, fromStartUtf16, fromEndUtf16, toStartUtf16, toEndUtf16;
    private WebFlightGoal(String owner, Matcher match, LocalDate date, boolean open) {
        this(owner,match,date,open,false,1);
    }
    private WebFlightGoal(String owner, Matcher match, LocalDate date, boolean open,boolean natural,int dateSuffix) {
        naturalReadOnlyIntent=natural;contractSchema=natural?NATURAL_SCHEMA:SCHEMA;
        recognition=natural?NATURAL_RECOGNITION:"literal_read_only_flight_test.v1";
        providerSelection=natural&&!owner.substring(0,match.start(1)).contains("南航")
                &&!owner.substring(0,match.start(1)).contains("中国南方航空")
                ?"compiled_official_csair_provider":"explicit_official_csair_owner";
        ownerContainsOpen = open;
        immutableOwner = owner;
        ownerSha256 = hash(owner);
        departureDate = date;
        fromCity = match.group(4); toCity = match.group(5);
        dateStartUtf16 = match.start(1); dateEndUtf16 = match.end(3) + dateSuffix;
        fromStartUtf16 = match.start(4); fromEndUtf16 = match.end(4);
        toStartUtf16 = match.start(5); toEndUtf16 = match.end(5);
        contractSha256 = hash(contractSchema + "\n" + ownerSha256 + "\n" + date.toString()
                + "\n" + fromCity + "\n" + toCity + "\n1\n0\n0\none_way");
    }
    /** Exact consumption only. Whitespace/suffixes, added goals or unknown syntax are unsupported. */
    public static WebFlightGoal parse(String owner) {
        if (owner == null || owner.getBytes(StandardCharsets.UTF_8).length > 1600) return null;
        Matcher match = OWNER.matcher(owner);
        boolean open = false;
        if (!match.matches()) {
            match = BACKGROUND_OWNER.matcher(owner);
            if (!match.matches()) return parseNatural(owner);
            open = true;
        }
        if (match.group(4).equals(match.group(5))) return null;
        try {
            LocalDate date = LocalDate.of(Integer.parseInt(match.group(1)),
                    Integer.parseInt(match.group(2)), Integer.parseInt(match.group(3)));
            return new WebFlightGoal(owner, match, date, open);
        } catch (DateTimeException | NumberFormatException invalid) {
            return null;
        }
    }
    private static WebFlightGoal parseNatural(String owner) {
        Matcher match=NATURAL_DATE.matcher(owner);int suffix=1;
        if(!match.matches()){match=NATURAL_ISO_DATE.matcher(owner);suffix=0;if(!match.matches())return null;}
        if(!singleCity(match.group(4))||!singleCity(match.group(5))||match.group(4).equals(match.group(5)))return null;
        try{
            LocalDate date=LocalDate.of(Integer.parseInt(match.group(1)),
                    Integer.parseInt(match.group(2)),Integer.parseInt(match.group(3)));
            return new WebFlightGoal(owner,match,date,false,true,suffix);
        }catch(DateTimeException|NumberFormatException invalid){return null;}
    }
    private static boolean singleCity(String city){
        return city.matches("[\\p{IsHan}]{2,12}")
                &&!city.matches(".*(?:或者|以及|然后|打开|查询|搜索|预订|下单|支付|删除|提醒|闹钟|成人|儿童|婴儿).*");
    }
    /** A recognized public-query purpose permits considering the compiled entry;
     * the real OWNER tool mask and selected background helper must also allow it.
     * No expanded or generated instruction is ever substituted for immutableOwner. */
    public boolean allowsInitialOfficialPage(){return ownerContainsOpen||naturalReadOnlyIntent;}
    /** Maximum purpose-compatible tools, never a grant. Intersect this with the
     * authorization compiled from the identical original OWNER and actual lease. */
    public Set<String> toolCeiling(){
        Set<String> ceiling=new TreeSet<String>(Arrays.asList("open","click","type","submit","scroll","back","wait","done"));
        if(!allowsInitialOfficialPage())ceiling.remove("open");
        return Collections.unmodifiableSet(ceiling);
    }
    /** Clock is supplied from the real task boundary, never inferred from page text. */
    public boolean departureNotBefore(LocalDate taskLocalDate) {
        return taskLocalDate != null && !departureDate.isBefore(taskLocalDate);
    }
    public Map<String,Object> evidence() {
        Map<String,Object> out = new LinkedHashMap<String,Object>();
        out.put("schema", contractSchema); out.put("owner_sha256", ownerSha256);
        out.put("contract_sha256", contractSha256); out.put("departure_date", departureDate.toString());
        out.put("from_city", fromCity); out.put("to_city", toCity); out.put("trip_type", "one_way");
        out.put("adults", adults); out.put("children", children); out.put("infants", infants);
        out.put("date_start_utf16", dateStartUtf16); out.put("date_end_utf16", dateEndUtf16);
        out.put("from_start_utf16", fromStartUtf16); out.put("from_end_utf16", fromEndUtf16);
        out.put("to_start_utf16", toStartUtf16); out.put("to_end_utf16", toEndUtf16);
        out.put("source", "complete_immutable_owner"); out.put("grants_tool_authority", false);
        out.put("airport_choice_inferred", false); out.put("query_executed", false);
        if(naturalReadOnlyIntent){
            out.put("recognition",recognition);out.put("provider_selection",providerSelection);
            out.put("owner_rewritten",false);out.put("year_explicit_in_owner",true);
            out.put("owner_contains_literal_open",ownerContainsOpen);out.put("initial_official_page_required",true);
        }
        return Collections.unmodifiableMap(out);
    }
    static String hash(String value) {
        try {
            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            char[] hex = "0123456789abcdef".toCharArray(); StringBuilder out = new StringBuilder(64);
            for (byte b : bytes) out.append(hex[(b >>> 4) & 15]).append(hex[b & 15]);
            return out.toString();
        } catch (Exception impossible) { throw new IllegalStateException(impossible); }
    }
}

package org.trillionnium.hepta.local;

/** Immutable app-tree identity plus separately observed input-method visibility. */
public final class ObservationState {
    public final String appTreeSha256;
    public final ImeVisibility imeVisibility;

    public ObservationState(String appTreeSha256,ImeVisibility imeVisibility){
        if(appTreeSha256==null||appTreeSha256.isEmpty()||imeVisibility==null)
            throw new IllegalArgumentException("complete observation state required");
        this.appTreeSha256=appTreeSha256;this.imeVisibility=imeVisibility;
    }

    /** For exact freshness checks, unknown is a distinct observed state. */
    public String fingerprintInput(){return appTreeSha256+"\nime_visible="+imeVisibility.fingerprintValue;}

    /** Null means IME progress is unknown, not that a keyboard appeared/disappeared. */
    public Boolean changedFrom(ObservationState before){
        if(before==null)throw new IllegalArgumentException("previous observation required");
        if(!appTreeSha256.equals(before.appTreeSha256))return Boolean.TRUE;
        if(imeVisibility==ImeVisibility.UNKNOWN||before.imeVisibility==ImeVisibility.UNKNOWN)return null;
        return Boolean.valueOf(imeVisibility!=before.imeVisibility);
    }
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;

/** Bounded facts about the active root and its own API window; no inferred page role. */
public final class ObservedWindowMetadata {
    public static final String SCHEMA="hepta.observed-window-metadata.v1";
    public static final String SCOPE="active_root_only";
    public static final int TITLE_LIMIT=96, CLASS_LIMIT=128;
    public static final int PROMPT_TITLE_LIMIT=16, PROMPT_CLASS_LIMIT=32;
    public final String status,rootClass,title;
    public final boolean rootClassTruncated,titleTruncated;
    public final Integer type,displayId;
    private final int[] rootBounds,windowBounds;
    private final String rootClassIdentity,titleIdentity;

    private ObservedWindowMetadata(int[] rootBounds,String rootClass,boolean observed,
            Integer type,Integer displayId,int[] windowBounds,String title){
        if(!validBounds(rootBounds))throw new IllegalArgumentException("observed root bounds required");
        this.rootBounds=rootBounds.clone();
        this.status=observed?"observed":"unknown";
        this.rootClass=bounded(rootClass,CLASS_LIMIT);
        this.rootClassTruncated=rootClass!=null&&rootClass.length()>CLASS_LIMIT;
        this.rootClassIdentity=identity(rootClass);
        this.type=observed?type:null;
        this.displayId=observed?displayId:null;
        this.windowBounds=observed&&validBounds(windowBounds)?windowBounds.clone():null;
        this.title=observed?bounded(title,TITLE_LIMIT):null;
        this.titleTruncated=observed&&title!=null&&title.length()>TITLE_LIMIT;
        this.titleIdentity=observed?identity(title):null;
    }

    public static ObservedWindowMetadata unknown(int[] rootBounds,String rootClass){
        return new ObservedWindowMetadata(rootBounds,rootClass,false,null,null,null,null);
    }

    /** Caller has matched getWindow().getId()/getDisplayId() to the selected root. */
    public static ObservedWindowMetadata observed(int[] rootBounds,String rootClass,
            int type,int displayId,int[] windowBounds,String title){
        return new ObservedWindowMetadata(rootBounds,rootClass,true,Integer.valueOf(type),
                Integer.valueOf(displayId),windowBounds,title);
    }

    public int[] rootBounds(){return rootBounds.clone();}
    public int[] windowBounds(){return windowBounds==null?null:windowBounds.clone();}
    public String promptTitle(){return bounded(title,PROMPT_TITLE_LIMIT);}
    public String promptRootClass(){return bounded(rootClass,PROMPT_CLASS_LIMIT);}
    public boolean promptTitleTruncated(){return titleTruncated||(title!=null&&title.length()>PROMPT_TITLE_LIMIT);}
    public boolean promptRootClassTruncated(){return rootClassTruncated||(rootClass!=null&&rootClass.length()>PROMPT_CLASS_LIMIT);}

    /** Exact freshness includes metadata, but unavailable/available metadata is not task progress. */
    public String bindFreshness(String stateFingerprint){
        if(stateFingerprint==null)throw new IllegalArgumentException("observed state required");
        return SCHEMA+atom(stateFingerprint)+atom(SCOPE)+atom(status)+atom(Arrays.toString(rootBounds))
                +atom(rootClassIdentity)+atom(type==null?null:type.toString())
                +atom(displayId==null?null:displayId.toString())
                +atom(windowBounds==null?null:Arrays.toString(windowBounds))+atom(titleIdentity);
    }

    private static boolean validBounds(int[] value){
        return value!=null&&value.length==4&&value[2]>value[0]&&value[3]>value[1];
    }
    private static String bounded(String value,int limit){
        if(value==null||value.length()<=limit)return value;
        int end=limit-1;
        if(end>0&&Character.isHighSurrogate(value.charAt(end-1)))end--;
        return value.substring(0,end)+"…";
    }
    private static String atom(String value){return value==null?"-1:":value.length()+":"+value;}
    private static String identity(String value){
        if(value==null)return null;
        try{
            byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder result=new StringBuilder(64);
            for(byte b:digest){result.append(Character.forDigit((b>>>4)&15,16));result.append(Character.forDigit(b&15,16));}
            return result.toString();
        }catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Bounded labels from a clickable node's actual non-interactive descendant subtree. */
public final class ObservedChildText {
    public static final String SOURCE="visible_noninteractive_descendants.v2";
    public static final int MAX_DESCENDANTS=16, MAX_DEPTH=4, MAX_PARTS=3, MAX_CHARACTERS=96;
    private ObservedChildText() {}
    public static final class Metadata {
        public final boolean visible,inScope,clickable,clickAction,inputLike,password,interactive;
        public Metadata(boolean visible,boolean inScope,boolean clickable,boolean clickAction,
                        boolean inputLike,boolean password,boolean interactive){
            this.visible=visible;this.inScope=inScope;this.clickable=clickable;this.clickAction=clickAction;
            this.inputLike=inputLike;this.password=password;this.interactive=interactive;
        }
    }
    /** Root is borrowed; each non-null child returned by child() is released once. */
    public interface Reader<T> {
        Metadata metadata(T node);
        String text(T node);
        String description(T node);
        String identity(T node);
        /** Exact observed resource ID; legacy readers have no such evidence. */
        default String viewId(T node){return "";}
        int childCount(T node);
        T child(T node,int index);
        void release(T node);
    }
    public static final class Source {
        public final String descendantPath,property,textSha256,nodeSignature,viewId;
        Source(String path,String property,String text,String identity){
            this(path,property,text,identity,"");
        }
        Source(String path,String property,String text,String identity,String viewId){
            descendantPath=path;this.property=property;textSha256=hash(text);nodeSignature=identity;this.viewId=string(viewId);
        }
        String fingerprint(){return field(descendantPath)+field(property)+field(textSha256)+field(nodeSignature)+field(viewId);}
    }
    public static final class Result {
        public final String text,status,fingerprint,rootSignature;
        public final boolean truncated,sourcesComplete;
        public final int visited;
        public final List<Source> sources;
        private final List<int[]> observedSpans;
        Result(String text,String status,boolean truncated,int visited,List<Source> sources){
            this(text,status,truncated,visited,sources,Collections.<int[]>emptyList(),"",false);
        }
        private Result(String text,String status,boolean truncated,int visited,List<Source> sources,List<int[]> spans,String rootSignature,boolean sourcesComplete){
            this.text=text;this.status=status;this.truncated=truncated;this.visited=visited;
            this.rootSignature=string(rootSignature);
            this.sourcesComplete=sourcesComplete;
            this.sources=Collections.unmodifiableList(new ArrayList<Source>(sources));
            observedSpans=new ArrayList<int[]>();int previous=0;
            for(int[] span:spans){
                if(span==null||span.length!=2||span[0]<previous||span[1]<span[0]||span[1]>text.length())
                    throw new IllegalArgumentException("invalid observed child text span");
                observedSpans.add(new int[]{span[0],span[1]});previous=span[1];
            }
            StringBuilder value=new StringBuilder(field(SOURCE)+field(status)+field(text)+field(Boolean.toString(truncated))+field(this.rootSignature)+field(Boolean.toString(sourcesComplete)));
            for(Source source:sources)value.append(source.fingerprint());fingerprint=hash(value.toString());
        }
        /** The original node signature remains part of target and whole-graph identity. */
        public String bind(String originalNodeSignature){return hash(field(originalNodeSignature)+field(fingerprint));}
        /** Only original descendant characters within the visible label prefix.
         * Separators and truncation ellipses inserted by this collector are not
         * observed text. No retained spans means that provenance is unavailable.
         * This does not change the label, source hashes or observation identity.
         */
        public String observedPrefix(int limit){
            if(limit<0)throw new IllegalArgumentException("negative child text prefix");
            int end=Math.min(limit,text.length());
            if(end>0&&end<text.length()&&Character.isHighSurrogate(text.charAt(end-1)))end--;
            StringBuilder value=new StringBuilder();
            for(int[] span:observedSpans){
                if(span[0]>=end)break;
                value.append(text,span[0],Math.min(span[1],end));
            }
            return value.toString();
        }
    }
    private static final class Pending<T> {
        final T node;final String path;final int depth;
        Pending(T node,String path,int depth){this.node=node;this.path=path;this.depth=depth;}
    }
    private static final class Budget {int acquired;boolean truncated,sourceOmitted;}
    private static Result none(String status){return new Result("",status,false,0,Collections.<Source>emptyList());}
    public static Result notApplicable(){return none("not_applicable");}
    public static String displayLabel(String text,String description,Result childText){
        if(!string(text).trim().isEmpty())return text;
        if(!string(description).trim().isEmpty())return description;
        return childText.text;
    }
    public static <T> Result collect(T root,Reader<T> reader){
        ArrayDeque<Pending<T>> pending=new ArrayDeque<Pending<T>>();
        List<Source> sources=new ArrayList<Source>();Set<String> seen=new HashSet<String>();
        StringBuilder label=new StringBuilder();List<int[]> observedSpans=new ArrayList<int[]>();Budget budget=new Budget();int visited=0;
        try{
            Metadata owner=reader.metadata(root);
            // Input/password bodies are not requested, even for a clickable root.
            if(owner==null||!owner.visible||!owner.inScope||!owner.clickable||!owner.clickAction||owner.inputLike||owner.password)
                return notApplicable();
            if(!string(reader.text(root)).trim().isEmpty()||!string(reader.description(root)).trim().isEmpty())return notApplicable();
            String rootSignature=string(reader.identity(root));
            enqueue(root,"",0,reader,pending,budget);
            while(!pending.isEmpty()){
                Pending<T> current=pending.removeFirst();visited++;
                try{
                    Metadata node=reader.metadata(current.node);
                    if(node==null)throw new IllegalStateException("descendant metadata unavailable");
                    // These are whole-subtree boundaries; do not borrow another control's label/body.
                    if(!node.visible||!node.inScope||node.inputLike||node.password||node.clickable||node.clickAction||node.interactive)continue;
                    String raw=string(reader.text(current.node)),property="text";
                    if(raw.trim().isEmpty()){raw=string(reader.description(current.node));property="description";}
                    String value=raw.trim();
                    if(!value.isEmpty()&&seen.add(value)){
                        String separator=label.length()==0?"":" · ";int available=MAX_CHARACTERS-label.length()-separator.length();
                        if(available<=0||sources.size()>=MAX_PARTS){budget.truncated=true;break;}
                        String part=limited(value,available);label.append(separator);
                        int start=label.length();label.append(part);
                        observedSpans.add(new int[]{start,start+part.length()-(part.length()<value.length()?1:0)});
                        sources.add(new Source(current.path,property,raw,reader.identity(current.node),reader.viewId(current.node)));
                        if(part.length()<value.length())budget.truncated=true;
                    }else if(!value.isEmpty())budget.sourceOmitted=true;
                    if(label.length()>=MAX_CHARACTERS||sources.size()>=MAX_PARTS){
                        if(!pending.isEmpty()||reader.childCount(current.node)>0)budget.truncated=true;
                        break;
                    }
                    enqueue(current.node,current.path,current.depth,reader,pending,budget);
                }finally{reader.release(current.node);}
            }
            return new Result(label.toString(),label.length()==0?"empty":"derived",budget.truncated,visited,sources,observedSpans,rootSignature,!budget.truncated&&!budget.sourceOmitted);
        }catch(RuntimeException unavailable){
            // Stale/inaccessible children do not produce a partially asserted label.
            return none("unavailable");
        }finally{while(!pending.isEmpty()){try{reader.release(pending.removeFirst().node);}catch(RuntimeException ignored){/* best-effort reference cleanup */}}}
    }
    private static <T> void enqueue(T parent,String path,int depth,Reader<T> reader,
                                   ArrayDeque<Pending<T>> pending,Budget budget){
        int children=reader.childCount(parent);if(children<0)throw new IllegalStateException("invalid child count");
        if(depth>=MAX_DEPTH){if(children>0)budget.truncated=true;return;}
        int admitted=Math.min(children,MAX_DESCENDANTS-budget.acquired);
        if(admitted<children)budget.truncated=true;
        for(int i=0;i<admitted;i++){
            T child=reader.child(parent,i);if(child==null)throw new IllegalStateException("descendant disappeared");
            budget.acquired++;pending.addLast(new Pending<T>(child,path.isEmpty()?Integer.toString(i):path+"/"+i,depth+1));
        }
    }
    private static String limited(String text,int maximum){
        if(text.length()<=maximum)return text;
        int end=Math.max(0,maximum-1);if(end>0&&Character.isHighSurrogate(text.charAt(end-1)))end--;
        return text.substring(0,end)+"…";
    }
    private static String string(String value){return value==null?"":value;}
    private static String field(String value){String safe=string(value);return safe.length()+":"+safe;}
    private static String hash(String value){
        try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder(64);
            for(byte b:digest)hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return hex.toString();
        }catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
}

package org.trillionnium.hepta.local;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Exact supported scroll action names from one successfully read action list. */
public final class ObservedScrollActions {
    public static final String SCHEMA="hepta.observed-scroll-actions.v1";
    private static final List<String> ORDER=Collections.unmodifiableList(Arrays.asList(
            "forward","backward","up","down","left","right"));
    public static final ObservedScrollActions UNKNOWN=new ObservedScrollActions(false,Collections.<String>emptyList());
    public final boolean observed;
    public final List<String> directions;

    private ObservedScrollActions(boolean observed,List<String> directions){
        this.observed=observed;this.directions=Collections.unmodifiableList(new ArrayList<String>(directions));
    }
    /** Null means unavailable, never an inferred set from isScrollable. */
    public static ObservedScrollActions observed(Collection<String> names){
        if(names==null)return UNKNOWN;
        Set<String> supplied=new HashSet<String>();
        for(String name:names){
            if(name==null||!ORDER.contains(name))throw new IllegalArgumentException("unknown observed scroll direction");
            supplied.add(name);
        }
        List<String> result=new ArrayList<String>();for(String name:ORDER)if(supplied.contains(name))result.add(name);
        return new ObservedScrollActions(true,result);
    }
    public boolean hasAny(){return observed&&!directions.isEmpty();}
    public boolean allows(String direction){return observed&&directions.contains(direction);}
    /** This binds freshness, not the controller's existing visible-progress predicate. */
    public String fingerprintInput(){
        StringBuilder out=new StringBuilder(SCHEMA).append(observed?"|observed":"|unknown");
        for(String direction:directions)out.append('|').append(direction);
        return out.toString();
    }
    public String bindFreshness(String original){
        if(original==null)throw new IllegalArgumentException("original node signature required");
        return original+"\nscroll_actions="+fingerprintInput();
    }
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.text.Normalizer;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;

/** Facts from one complete action list. Editability never invents an IME action. */
public final class ObservedImeEnter {
    public static final String SCHEMA="hepta.observed-ime-enter.v1";
    public static final ObservedImeEnter UNKNOWN=new ObservedImeEnter(false,false,null);
    public static final ObservedImeEnter ABSENT=new ObservedImeEnter(true,false,null);
    private static final Set<String> QUERY_LABELS=Collections.unmodifiableSet(new HashSet<String>(Arrays.asList(
            "搜索","搜尋","查询","查詢","查找","search","query","find")));
    public final boolean observed,present;
    public final String label,labelSha256;
    private ObservedImeEnter(boolean observed,boolean present,String label){
        this.observed=observed;this.present=present;this.label=label;
        this.labelSha256=label==null?null:hash(label);
    }
    public static ObservedImeEnter present(String label){
        if(label!=null){
            if(label.length()>256)return UNKNOWN;
            for(int i=0;i<label.length();i++){
                char c=label.charAt(i);
                if(c==0)return UNKNOWN;
                if(Character.isHighSurrogate(c)){
                    if(++i>=label.length()||!Character.isLowSurrogate(label.charAt(i)))return UNKNOWN;
                }else if(Character.isLowSurrogate(c))return UNKNOWN;
            }
        }
        return new ObservedImeEnter(true,true,label);
    }
    /** Generic Enter/Go/Done is not proof of query semantics or payment authority. */
    public boolean queryAllowed(){
        return observed&&present&&label!=null&&QUERY_LABELS.contains(
                Normalizer.normalize(label,Normalizer.Form.NFKC).trim().toLowerCase(Locale.ROOT));
    }
    public String reasonCode(){
        return !observed?"ime_action_not_observed":!present?"ime_action_unavailable":
                queryAllowed()?"observed_query_action":"ime_action_semantics_unverified";
    }
    public Map<String,Object> evidence(){
        Map<String,Object> value=new LinkedHashMap<String,Object>();
        value.put("schema",SCHEMA);value.put("observed",observed);value.put("present",present);
        value.put("action_label",label);value.put("action_label_sha256",labelSha256);
        value.put("query_allowed",queryAllowed());value.put("reason_code",reasonCode());return value;
    }
    public Map<String,Object> projection(String textSha256){
        if(!queryAllowed()||!isSha(textSha256))throw new IllegalArgumentException("query capability and full input hash required");
        Map<String,Object> value=new LinkedHashMap<String,Object>();value.put("schema",SCHEMA);
        value.put("action_name","ACTION_IME_ENTER");value.put("action_label",label);
        value.put("action_label_sha256",labelSha256);value.put("input_text_sha256",textSha256);return value;
    }
    public String fingerprintInput(){return SCHEMA+"|"+observed+"|"+present+"|"+(labelSha256==null?"null":labelSha256);}
    public String bindFreshness(String original,boolean focused,String textSha256){
        if(original==null)throw new IllegalArgumentException("node identity required");
        return original+"\nime_enter="+fingerprintInput()+"|focused="+focused+"|full_input="+textSha256;
    }
    public static boolean isSha(String value){return value!=null&&value.matches("[0-9a-f]{64}");}
    /** Unknown or ill-formed UTF-16 cannot acquire a full-input identity through replacement encoding. */
    public static String completeTextHash(String value){
        if(value==null)return null;
        for(int i=0;i<value.length();i++){
            char c=value.charAt(i);
            if(Character.isHighSurrogate(c)){
                if(++i>=value.length()||!Character.isLowSurrogate(value.charAt(i)))return null;
            }else if(Character.isLowSurrogate(c))return null;
        }
        return hash(value);
    }
    public static String hash(String value){
        if(value==null)throw new IllegalArgumentException("hash input required");
        try{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)))
            out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
        catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
}

package org.trillionnium.hepta.local;

/** Only input-method window visibility; no key, text, app or node inspection. */
public enum ImeVisibility {
    VISIBLE("true"), HIDDEN("false"), UNKNOWN("unknown");

    public final String fingerprintValue;
    ImeVisibility(String value){fingerprintValue=value;}
    public Boolean value(){return this==UNKNOWN?null:Boolean.valueOf(this==VISIBLE);}

    /** Absence proves hidden only in a complete window list containing the target. */
    public static ImeVisibility observed(boolean complete,boolean targetWindowPresent,boolean visibleImePresent){
        if(!complete||!targetWindowPresent)return UNKNOWN;
        return visibleImePresent?VISIBLE:HIDDEN;
    }
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;
import java.util.TreeSet;

/** Strict JSON: duplicates and bad Unicode are always rejected; only DOM geometry permits finite decimals. */
final class WebEvidenceJson {
    private WebEvidenceJson() { }
    static void need(boolean value,String reason){if(!value)throw new IllegalArgumentException(reason);}
    static JSONObject parse(String raw,int max)throws Exception{
        need(raw!=null&&raw.getBytes(StandardCharsets.UTF_8).length<=max,"JSON byte budget");
        return parseBounded(raw,16384,256,false);
    }
    /** Private, hash-bound evidence has a separate budget; incoming request limits stay unchanged. */
    static JSONObject parseEvidence(String raw,int max)throws Exception{
        need(max>0&&max<=org.trillionnium.hepta.webprotocol.WebEvidenceProtocol.MAX_EVIDENCE_BYTES,"evidence byte budget shape");
        need(raw!=null&&raw.getBytes(StandardCharsets.UTF_8).length<=max,"evidence JSON byte budget");
        return parseBounded(raw,Math.min(max,org.trillionnium.hepta.webprotocol.WebEvidenceProtocol.MAX_DOM_BYTES),2048,false);
    }
    /** Only the capture envelope contains native finite scale/transform samples.
     * Every identity, lease and request field is still checked by its strict
     * Integer/Long decoder; request and retirement parsers are unchanged. */
    static JSONObject parseCaptureEvidence(String raw,int max)throws Exception{
        need(max>0&&max<=org.trillionnium.hepta.webprotocol.WebEvidenceProtocol.MAX_EVIDENCE_BYTES,"capture evidence byte budget shape");
        need(raw!=null&&raw.getBytes(StandardCharsets.UTF_8).length<=max,"capture evidence JSON byte budget");
        return parseBounded(raw,Math.min(max,org.trillionnium.hepta.webprotocol.WebEvidenceProtocol.MAX_DOM_BYTES),2048,true);
    }
    static JSONObject parseDom(String raw)throws Exception{
        need(raw!=null&&raw.getBytes(StandardCharsets.UTF_8).length<=org.trillionnium.hepta.webprotocol.WebEvidenceProtocol.MAX_DOM_BYTES,"DOM byte budget");
        return parseBounded(raw,65536,2048,true);
    }
    private static JSONObject parseBounded(String raw,int stringBudget,int memberBudget,boolean decimal)throws Exception{
        Parser p=new Parser(raw,stringBudget,memberBudget,decimal);Object v=p.value(0);p.ws();need(p.at==raw.length()&&v instanceof JSONObject,"one JSON object required");return (JSONObject)v;
    }
    static void keys(JSONObject o,Set<String> expected)throws Exception{
        Set<String> actual=new TreeSet<String>();Iterator<String> it=o.keys();while(it.hasNext())actual.add(it.next());
        need(actual.equals(expected),"exact JSON keys required");
    }
    static String text(JSONObject o,String key)throws Exception{Object v=o.get(key);need(v instanceof String,"string required: "+key);return (String)v;}
    static long number(JSONObject o,String key)throws Exception{Object v=o.get(key);need(v instanceof Integer||v instanceof Long,"integer required: "+key);return ((Number)v).longValue();}
    static int integer(JSONObject o,String key)throws Exception{long n=number(o,key);need(n>=Integer.MIN_VALUE&&n<=Integer.MAX_VALUE,"integer range: "+key);return (int)n;}
    static String sha(byte[] raw)throws Exception{byte[] v=MessageDigest.getInstance("SHA-256").digest(raw);StringBuilder s=new StringBuilder(64);for(byte b:v)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
    static String sha(String value)throws Exception{return sha(value.getBytes(StandardCharsets.UTF_8));}
    static void unicode(String value){for(int i=0;i<value.length();i++){char c=value.charAt(i);need(c!=0,"NUL text refused");if(Character.isHighSurrogate(c))need(++i<value.length()&&Character.isLowSurrogate(value.charAt(i)),"unpaired surrogate");else need(!Character.isLowSurrogate(c),"unpaired surrogate");}}
    private static final class Parser {
        final String raw;final int stringBudget,memberBudget;final boolean decimal;int at;
        Parser(String raw,int stringBudget,int memberBudget,boolean decimal){this.raw=raw;this.stringBudget=stringBudget;this.memberBudget=memberBudget;this.decimal=decimal;}
        void ws(){while(at<raw.length()&&" \t\r\n".indexOf(raw.charAt(at))>=0)at++;}
        char take(){need(at<raw.length(),"unexpected JSON end");return raw.charAt(at++);}
        Object value(int depth)throws Exception{
            need(depth<=16,"JSON depth budget");ws();char c=take();
            if(c=='{'){
                JSONObject out=new JSONObject();Set<String> seen=new HashSet<String>();ws();if(at<raw.length()&&raw.charAt(at)=='}'){at++;return out;}
                for(int n=0;;n++){
                    need(n<memberBudget,"object member budget");ws();need(take()=='\"',"quoted object key required");String key=string();need(seen.add(key),"duplicate JSON key");ws();need(take()==':',"object colon required");out.put(key,value(depth+1));ws();char end=take();if(end=='}')return out;need(end==',',"object comma required");
                }
            }
            if(c=='['){JSONArray out=new JSONArray();ws();if(at<raw.length()&&raw.charAt(at)==']'){at++;return out;}for(int n=0;;n++){need(n<memberBudget,"array member budget");out.put(value(depth+1));ws();char end=take();if(end==']')return out;need(end==',',"array comma required");}}
            if(c=='\"')return string();
            if(c=='t'){literal("rue");return Boolean.TRUE;}if(c=='f'){literal("alse");return Boolean.FALSE;}if(c=='n'){literal("ull");return JSONObject.NULL;}
            int start=at-1;need(c=='-'||(c>='0'&&c<='9'),"JSON value invalid");while(at<raw.length()&&raw.charAt(at)>='0'&&raw.charAt(at)<='9')at++;
            if(decimal){while(at<raw.length()&&".eE+-0123456789".indexOf(raw.charAt(at))>=0)at++;}
            String number=raw.substring(start,at);
            if(number.matches("-?(?:0|[1-9][0-9]*)"))return Long.valueOf(number);
            need(decimal&&number.matches("-?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?(?:[eE][+-]?[0-9]+)?"),"JSON number invalid");
            double d=Double.parseDouble(number);need(!Double.isNaN(d)&&!Double.isInfinite(d),"nonfinite DOM number");return Double.valueOf(d);
        }
        void literal(String suffix){need(raw.startsWith(suffix,at),"JSON literal invalid");at+=suffix.length();}
        String string(){StringBuilder out=new StringBuilder();for(;;){char c=take();if(c=='\"')break;need(c>=0x20,"unescaped string control");if(c=='\\'){char e=take();switch(e){case '\"':case '\\':case '/':out.append(e);break;case 'b':out.append('\b');break;case 'f':out.append('\f');break;case 'n':out.append('\n');break;case 'r':out.append('\r');break;case 't':out.append('\t');break;case 'u':need(at+4<=raw.length(),"short Unicode escape");String h=raw.substring(at,at+4);need(h.matches("[0-9a-fA-F]{4}"),"invalid Unicode escape");out.append((char)Integer.parseInt(h,16));at+=4;break;default:throw new IllegalArgumentException("unknown string escape");}}else out.append(c);need(out.length()<=stringBudget,"string budget");}String s=out.toString();unicode(s);return s;}
    }
}

package org.trillionnium.hepta.webprotocol;

import org.json.JSONArray;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;

/** Shared immutable binding and exact canonical UTF-8 hash; no device effects. */
public final class WebEvidenceBinding {
    private WebEvidenceBinding() { }
    public static final String SCHEMA=WebEvidenceProtocol.BINDING_SCHEMA;
    private static final String[] FIELDS={"task_id","controller_session_nonce","owner","owner_sha256",
            "contract_sha256","authorization","background","controller_identity","helper_identity"};
    public static JSONObject fromAttach(JSONObject attach) throws Exception {
        WebTaskPurpose purpose=WebTaskPurpose.fromAttach(attach);
        JSONObject out=new JSONObject().put("schema",SCHEMA).put("initial_url",purpose.initialUrl)
                .put("goal_kind",purpose.kind).put("site_policy_id",purpose.sitePolicyId)
                .put("site_policy_sha256",purpose.sitePolicySha256);
        for(String key:FIELDS)out.put(key,attach.get(key));
        Object nonce=attach.get("controller_session_nonce");
        if(!(nonce instanceof String))throw new IllegalArgumentException("controller session nonce must be a string");
        out.put("storage_profile_name",WebStorageEvidence.profileFor((String)nonce));
        // The parse is a defensive deep copy. Per-request nonce/deadline are
        // deliberately not part of the stable lease identity.
        JSONObject copied=new JSONObject(canonical(out));WebTaskPurpose.requireBinding(copied);return copied;
    }
    public static String sha256(JSONObject binding) throws Exception {
        byte[] digest=MessageDigest.getInstance("SHA-256").digest(canonical(binding).getBytes(StandardCharsets.UTF_8));
        char[] hex="0123456789abcdef".toCharArray();StringBuilder out=new StringBuilder(64);
        for(byte b:digest)out.append(hex[(b>>>4)&15]).append(hex[b&15]);return out.toString();
    }
    /** Keys sorted by Java UTF-16 String.compareTo, arrays retain exact order. */
    public static String canonical(Object value) throws Exception {
        if(value==null||value==JSONObject.NULL)return "null";
        if(value instanceof String){
            String s=(String)value;StringBuilder out=new StringBuilder("\"");
            for(int i=0;i<s.length();i++){
                char c=s.charAt(i);
                if(Character.isHighSurrogate(c)){
                    if(i+1>=s.length()||!Character.isLowSurrogate(s.charAt(i+1)))throw new IllegalArgumentException("invalid Unicode");
                    out.append(c).append(s.charAt(++i));continue;
                }
                if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid Unicode");
                if(c=='\"'||c=='\\')out.append('\\').append(c);
                else if(c<0x20){String h=Integer.toHexString(c);out.append("\\u");for(int n=h.length();n<4;n++)out.append('0');out.append(h);}
                else out.append(c);
            }
            return out.append('\"').toString();
        }
        if(value instanceof Boolean)return value.toString();
        if(value instanceof Integer||value instanceof Long)return value.toString();
        if(value instanceof JSONArray){JSONArray a=(JSONArray)value;StringBuilder out=new StringBuilder("[");
            for(int i=0;i<a.length();i++){if(i>0)out.append(',');out.append(canonical(a.get(i)));}return out.append(']').toString();}
        if(value instanceof JSONObject){JSONObject o=(JSONObject)value;ArrayList<String> keys=new ArrayList<String>();
            Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);StringBuilder out=new StringBuilder("{");
            for(int i=0;i<keys.size();i++){if(i>0)out.append(',');String k=keys.get(i);out.append(canonical(k)).append(':').append(canonical(o.get(k)));}return out.append('}').toString();}
        throw new IllegalArgumentException("noncanonical binding type");
    }
}

package org.trillionnium.hepta.webprotocol;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.json.JSONArray;
import org.json.JSONObject;

/** Pure, bounded replay of the helper's recorded platform/profile clear callbacks. */
public final class WebStorageEvidence {
    private WebStorageEvidence() { }
    public static final String ISOLATION_SCHEMA="hepta.web-helper.storage-isolation.v1";
    public static final String RETIREMENT_SCHEMA="hepta.web-helper.recovery-storage.v1";
    public static final String LIBRARY="androidx.webkit:webkit:1.13.0";
    public static final int MAX_PROFILES=128;
    public static final long CLEAR_BUDGET_MS=3000;

    public static String profileFor(String controllerSessionNonce){
        need(controllerSessionNonce!=null&&controllerSessionNonce.matches("[0-9a-f]{64}"),"controller session nonce shape");
        return "hepta_v2_"+controllerSessionNonce;
    }

    public static void requireCapture(JSONObject binding,JSONObject facts,long captureStarted,long captureEnded)throws Exception{
        exact(facts,"schema","library","runtime_multi_profile","runtime_delete_browsing_data","profile_name",
                "profile_names_before","profile_was_present_before","profile_assigned_elapsed_ms",
                "webview_provider_package","webview_provider_version","webview_provider_version_code",
                "preload_clear","first_load_dispatch_begin_elapsed_ms","retirement_clear",
                "all_os_sockets_observed_closed","whole_device_storage_erased","business_verified","first_url");
        String profile=profileFor(text(binding,"controller_session_nonce"));
        need(profile.equals(text(binding,"storage_profile_name"))&&profile.equals(text(facts,"profile_name")),"profile is not bound to this lease");
        need(ISOLATION_SCHEMA.equals(text(facts,"schema"))&&LIBRARY.equals(text(facts,"library"))
                &&yes(facts,"runtime_multi_profile")&&yes(facts,"runtime_delete_browsing_data"),"storage API/feature provenance differs");
        need(no(facts,"profile_was_present_before")&&no(facts,"all_os_sockets_observed_closed")
                &&no(facts,"whole_device_storage_erased")&&no(facts,"business_verified"),"storage facts overclaim scope");
        need(!names(facts.getJSONArray("profile_names_before")).contains(profile),"profile was reused");
        need(text(facts,"webview_provider_package").length()>0&&text(facts,"webview_provider_package").length()<=200
                &&text(facts,"webview_provider_version").length()>0&&text(facts,"webview_provider_version").length()<=200
                &&number(facts,"webview_provider_version_code")>0,"provider identity missing");
        JSONObject clear=facts.getJSONObject("preload_clear");
        exact(clear,"started_elapsed_ms","deadline_elapsed_ms","initial_url","callback_elapsed_ms",
                "callback_observed","deadline_met","cookies_present_after","api");
        need("WebStorageCompat.deleteBrowsingData".equals(text(clear,"api"))&&yes(clear,"callback_observed")
                &&yes(clear,"deadline_met")&&no(clear,"cookies_present_after"),"actual clear callback facts incomplete");
        Object url=clear.get("initial_url");
        need(url==JSONObject.NULL||"".equals(url)||"about:blank".equals(url),"network page preceded storage isolation");
        JSONObject bg=binding.getJSONObject("background");
        long created=number(bg,"created_elapsed_ms"),expires=number(bg,"expires_elapsed_ms");
        long assigned=number(facts,"profile_assigned_elapsed_ms"),start=number(clear,"started_elapsed_ms"),
                deadline=number(clear,"deadline_elapsed_ms"),callback=number(clear,"callback_elapsed_ms"),
                load=number(facts,"first_load_dispatch_begin_elapsed_ms");
        need(created>=0&&created<=assigned&&assigned<=start&&start<=callback&&callback<=load
                &&load<=deadline&&deadline-start<=CLEAR_BUDGET_MS&&deadline>start
                &&load<=captureStarted&&captureStarted<=captureEnded&&captureEnded<=expires,
                "profile/clear/load/capture/lease order differs");
        WebTaskPurpose purpose=WebTaskPurpose.requireBinding(binding);
        need(purpose.initialUrl.equals(text(facts,"first_url"))
                &&facts.get("retirement_clear")==JSONObject.NULL,"capture occurred after retirement or on a different first URL");
    }

    public static void requireRetirement(JSONObject binding,JSONObject facts)throws Exception{
        exact(facts,"schema","profile_name","runtime_multi_profile","runtime_delete_browsing_data","kind",
                "profile_names_before","profile_names_after","started_elapsed_ms","deadline_elapsed_ms",
                "callback_elapsed_ms","ended_elapsed_ms","callback_observed","deadline_met","cookies_present_after",
                "api","other_profiles_deleted","all_os_sockets_observed_closed","business_verified");
        String profile=profileFor(text(binding,"controller_session_nonce"));
        need(profile.equals(text(binding,"storage_profile_name"))&&profile.equals(text(facts,"profile_name"))
                &&RETIREMENT_SCHEMA.equals(text(facts,"schema")),"retirement profile/schema differs");
        need(yes(facts,"runtime_multi_profile")&&yes(facts,"runtime_delete_browsing_data")
                &&no(facts,"other_profiles_deleted")&&no(facts,"all_os_sockets_observed_closed")
                &&no(facts,"business_verified"),"retirement feature/scope differs");
        Set<String> before=names(facts.getJSONArray("profile_names_before"));
        Set<String> after=names(facts.getJSONArray("profile_names_after"));
        long start=number(facts,"started_elapsed_ms"),deadline=number(facts,"deadline_elapsed_ms"),end=number(facts,"ended_elapsed_ms");
        need(start>0&&deadline>start&&deadline-start<=CLEAR_BUDGET_MS&&end>=start&&end<=deadline
                &&yes(facts,"deadline_met"),"retirement storage time bracket invalid");
        String kind=text(facts,"kind");
        if("recorded_profile_absent".equals(kind)){
            need(!before.contains(profile)&&!after.contains(profile)&&no(facts,"callback_observed")
                    &&facts.get("callback_elapsed_ms")==JSONObject.NULL&&facts.get("cookies_present_after")==JSONObject.NULL
                    &&"ProfileStore.getAllProfileNames".equals(text(facts,"api")),"profile absence facts inconsistent");
        }else{
            need("recorded_profile_clear_completed".equals(kind)&&before.contains(profile)&&after.contains(profile)
                    &&yes(facts,"callback_observed")&&no(facts,"cookies_present_after")
                    &&"WebStorageCompat.deleteBrowsingData".equals(text(facts,"api")),"profile clear facts incomplete");
            long callback=number(facts,"callback_elapsed_ms");
            need(start<=callback&&callback<=end,"profile clear callback outside native bracket");
        }
    }

    private static Set<String> names(JSONArray values)throws Exception{
        need(values.length()>0&&values.length()<=MAX_PROFILES,"profile name enumeration unavailable or over budget");
        Set<String> answer=new HashSet<String>();
        for(int i=0;i<values.length();i++){Object value=values.get(i);need(value instanceof String
                &&((String)value).length()<=128&&answer.add((String)value),"invalid/duplicate profile name");}
        return answer;
    }
    private static boolean yes(JSONObject object,String key)throws Exception{return Boolean.TRUE.equals(object.get(key));}
    private static boolean no(JSONObject object,String key)throws Exception{return Boolean.FALSE.equals(object.get(key));}
    private static String text(JSONObject object,String key)throws Exception{Object value=object.get(key);need(value instanceof String,"string required:"+key);return (String)value;}
    private static long number(JSONObject object,String key)throws Exception{Object value=object.get(key);need(value instanceof Integer||value instanceof Long,"integer required:"+key);return ((Number)value).longValue();}
    private static void exact(JSONObject object,String... keys)throws Exception{
        Set<String> expected=new HashSet<String>(Arrays.asList(keys));need(object.length()==expected.size(),"unexpected storage fields");
        java.util.Iterator<String> actual=object.keys();while(actual.hasNext())need(expected.contains(actual.next()),"unknown storage field");
    }
    private static void need(boolean condition,String reason){if(!condition)throw new IllegalArgumentException(reason);}
}

package org.trillionnium.hepta.webprotocol;

import java.util.Arrays;
import java.util.Collections;
import java.util.Set;
import java.util.TreeSet;
import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.local.TaskAuthorization;
import org.trillionnium.hepta.local.web.WebFlightGoal;
import org.trillionnium.hepta.local.web.WebShoppingGoal;

/**
 * One complete original OWNER selects one compiled public-page purpose.
 * The actual TaskAuthorization compiler runs on that same original text.
 * This supplies a maximum page scope, never a replacement instruction or URL parameter.
 */
public final class WebTaskPurpose {
    public static final String FLIGHT_KIND="csair_public_flight";
    public static final String FLIGHT_POLICY_ID="csair_public_flight_v1";
    public static final String FLIGHT_INITIAL_URL="https://m.csair.com/";
    public static final String ORIGINAL_CSAIR_POLICY_SHA256="7a127a62aa8918be1224b886f90f939bf31146a6522dd2f8a0af0244a57749eb";
    public static final Set<String> BINDING_KEYS=Collections.unmodifiableSet(new TreeSet<String>(Arrays.asList(
            "schema","initial_url","goal_kind","site_policy_id","site_policy_sha256","task_id",
            "controller_session_nonce","owner","owner_sha256","contract_sha256","authorization",
            "background","controller_identity","helper_identity","storage_profile_name")));
    public final String owner,ownerSha256,contractSha256,kind,sitePolicyId,sitePolicySha256,initialUrl;
    public final boolean naturalReadOnlyIntent;
    public final WebFlightGoal flight;
    public final WebShoppingGoal shopping;
    public final TaskAuthorization authorization;
    private final JSONObject policy;

    private WebTaskPurpose(String original,WebFlightGoal flight,WebShoppingGoal shopping)throws Exception{
        this.owner=original;this.flight=flight;this.shopping=shopping;
        authorization=TaskAuthorization.parse(original);
        authorization.requireOwner(original);
        require(authorization.allows("open")&&!authorization.requireFindAppBeforeOpen,
                "original OWNER does not allow the selected helper bootstrap");
        if(shopping!=null){
            require(shopping.allowsInitialOfficialPage(),"shopping initial page not supported");
            ownerSha256=shopping.ownerSha256;contractSha256=shopping.contractSha256;
            kind=WebShoppingGoal.KIND;sitePolicyId=WebShoppingGoal.SITE_POLICY_ID;
            initialUrl=WebSitePolicy.INITIAL_URL;naturalReadOnlyIntent=shopping.naturalReadOnlyIntent;
            policy=WebSitePolicy.forShopping(shopping).evidence();
            require(shopping.toolCeiling().containsAll(authorization.allowedTools),"shopping tool ceiling differs");
        }else{
            require(flight!=null&&flight.allowsInitialOfficialPage(),"background flight initial page not supported");
            ownerSha256=flight.ownerSha256;contractSha256=flight.contractSha256;
            kind=FLIGHT_KIND;sitePolicyId=FLIGHT_POLICY_ID;initialUrl=FLIGHT_INITIAL_URL;
            naturalReadOnlyIntent=flight.naturalReadOnlyIntent;
            require(flight.toolCeiling().containsAll(authorization.allowedTools),"flight tool ceiling differs");
            policy=flightPolicyEvidence();
        }
        require(ownerSha256.equals(authorization.instructionSha256),"original OWNER/compiler hash differs");
        sitePolicySha256=WebEvidenceBinding.sha256(policy);
    }
    /** Compiled policy data; this neither constructs an OWNER nor grants a task. */
    public static JSONObject flightPolicyEvidence()throws Exception{
        return new JSONObject().put("schema","hepta.web-site-policy.v1").put("site_policy_id",FLIGHT_POLICY_ID)
                .put("goal_kind",FLIGHT_KIND).put("initial_url",FLIGHT_INITIAL_URL)
                .put("main_frame_origins",new JSONArray(Arrays.asList("https://b2c.csair.com","https://m.csair.com")))
                .put("navigation_policy","existing_csair_official_origin_only")
                .put("original_origin_source_sha256",ORIGINAL_CSAIR_POLICY_SHA256)
                .put("arbitrary_url_input",false).put("arbitrary_javascript_input",false)
                .put("grants_page_action",false).put("business_verified",false);
    }
    public static WebTaskPurpose fromOwner(String original)throws Exception{
        WebFlightGoal flight=WebFlightGoal.parse(original);
        WebShoppingGoal shopping=WebShoppingGoal.parse(original);
        require((flight==null)!=(shopping==null),"exactly one supported original public-page goal required");
        return new WebTaskPurpose(original,flight,shopping);
    }
    public static WebTaskPurpose fromAttach(JSONObject attach)throws Exception{
        WebTaskPurpose purpose=fromOwner(text(attach,"owner"));
        require(purpose.ownerSha256.equals(text(attach,"owner_sha256"))
                &&purpose.contractSha256.equals(text(attach,"contract_sha256")),"original goal hash differs");
        JSONObject actualAuthorization=new JSONObject(purpose.authorization.evidence());
        require(WebEvidenceBinding.canonical(actualAuthorization).equals(
                WebEvidenceBinding.canonical(attach.getJSONObject("authorization"))),
                "actual original OWNER compiler evidence differs");
        return purpose;
    }
    public static WebTaskPurpose requireBinding(JSONObject binding)throws Exception{
        Set<String> keys=new TreeSet<String>();java.util.Iterator<String> it=binding.keys();while(it.hasNext())keys.add(it.next());
        require(keys.equals(BINDING_KEYS)&&WebEvidenceProtocol.BINDING_SCHEMA.equals(text(binding,"schema")),
                "current immutable binding shape differs");
        WebTaskPurpose purpose=fromAttach(binding);
        require(purpose.kind.equals(text(binding,"goal_kind"))
                &&purpose.sitePolicyId.equals(text(binding,"site_policy_id"))
                &&purpose.sitePolicySha256.equals(text(binding,"site_policy_sha256"))
                &&purpose.initialUrl.equals(text(binding,"initial_url")),"compiled single-site purpose differs");
        require(WebStorageEvidence.profileFor(text(binding,"controller_session_nonce"))
                .equals(text(binding,"storage_profile_name")),"lease storage profile differs");
        return purpose;
    }
    public JSONObject policyEvidence()throws Exception{return new JSONObject(WebEvidenceBinding.canonical(policy));}
    private static String text(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);require(raw instanceof String,"string "+key+" required");return (String)raw;
    }
    private static void require(boolean yes,String reason){if(!yes)throw new IllegalArgumentException(reason);}
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.webprotocol.WebEvidenceBinding;
import org.trillionnium.hepta.webprotocol.WebEvidenceProtocol;
import org.trillionnium.hepta.webprotocol.WebRecoveryPolicy;
import org.trillionnium.hepta.webprotocol.WebStorageEvidence;
import org.trillionnium.hepta.webprotocol.WebTaskPurpose;
import org.trillionnium.hepta.webprotocol.WebSitePolicy;
import org.trillionnium.hepta.webprotocol.WebDomCanonical;
import org.trillionnium.hepta.webprotocol.WebDomStability;
import org.trillionnium.hepta.webprotocol.WebObservedNavigation;
import java.net.URI;
import java.nio.ByteBuffer;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/** Pure replay of the authenticated helper reply. No reply is a business success. */
final class WebEvidenceReceipt {
    static final String OBSERVER_SHA="05bb7c1e4e1929b961c42af1e5c0e01918bf6ff64f153132ca11c7d85873e705";
    final String status,bindingSha,instance,url,domSha;
    final long epoch,started,ended;
    final int displayId,windowId;
    final boolean cleanupKnown,recovered,unstarted;
    private final String replyRaw,evidenceRaw,captureRaw,domRaw,armRaw;
    private final WebDomStability.Result checkedStability;
    private WebEvidenceReceipt(JSONObject callback,String raw,String capture,String dom,boolean closed,boolean recovered)throws Exception{
        this(callback,raw,capture,dom,closed,recovered,null,null);
    }
    private WebEvidenceReceipt(JSONObject callback,String raw,String capture,String dom,boolean closed,boolean recovered,
                               WebDomStability.Result stability,JSONObject arm)throws Exception{
        checkedStability=stability;armRaw=arm==null?null:WebDomCanonical.canonical(arm);
        status=WebEvidenceJson.text(callback,"status");bindingSha=nullableText(callback,"binding_sha256");
        instance=nullableText(callback,"webview_instance");epoch=callback.isNull("navigation_epoch")?-1:WebEvidenceJson.number(callback,"navigation_epoch");
        displayId=WebEvidenceJson.integer(callback,"actual_display_id");windowId=WebEvidenceJson.integer(callback,"actual_window_id");
        replyRaw=callback.toString();evidenceRaw=raw;captureRaw=capture;domRaw=dom;cleanupKnown=closed;this.recovered=recovered;
        unstarted=closed&&"unstarted_retired".equals(status);
        JSONObject c=capture==null?null:WebEvidenceJson.parseCaptureEvidence(capture,WebEvidenceProtocol.MAX_EVIDENCE_BYTES);
        url=c==null?null:WebEvidenceJson.text(c,"current_native_url");
        domSha=c==null?null:WebEvidenceJson.text(c,"dom_sha256");
        started=c==null?-1:WebEvidenceJson.number(c,"started_elapsed_ms");ended=c==null?-1:WebEvidenceJson.number(c,"ended_elapsed_ms");
    }
    JSONObject callback()throws Exception{return WebEvidenceJson.parse(replyRaw,WebEvidenceProtocol.MAX_CALLBACK_BYTES);}
    JSONObject capture()throws Exception{return captureRaw==null?null:WebEvidenceJson.parseCaptureEvidence(captureRaw,WebEvidenceProtocol.MAX_EVIDENCE_BYTES);}
    JSONObject dom()throws Exception{return domRaw==null?null:WebEvidenceJson.parseDom(domRaw);}
    String evidenceRaw(){return evidenceRaw;}
    String domRaw(){return domRaw;}
    String beforeDomRaw()throws Exception{return captureRaw==null?null:text(capture(),"before_dom_raw_utf8");}
    WebDomStability.Result stability(){return checkedStability;}
    JSONObject arm()throws Exception{return armRaw==null?null:WebEvidenceJson.parseEvidence(armRaw,WebEvidenceProtocol.MAX_EVIDENCE_BYTES);}

    static WebEvidenceReceipt verify(int code,String requestRaw,JSONObject binding,String callbackRaw,byte[] raw,
                                      int authenticatedHelperUid,long sentElapsed,long receivedElapsed)throws Exception{
        return verify(code,requestRaw,binding,callbackRaw,raw,authenticatedHelperUid,sentElapsed,receivedElapsed,null);
    }
    static WebEvidenceReceipt verify(int code,String requestRaw,JSONObject binding,String callbackRaw,byte[] raw,
                                      int authenticatedHelperUid,long sentElapsed,long receivedElapsed,JSONObject sourceCapture)throws Exception{
        need((code==WebEvidenceProtocol.ARM_OBSERVED_LINK)==(sourceCapture!=null),
                "ARM alone requires the client's exact private successful source capture");
        WebTaskPurpose purpose=WebTaskPurpose.requireBinding(binding);
        JSONObject request=WebEvidenceJson.parse(requestRaw,WebEvidenceProtocol.MAX_REQUEST_BYTES);
        WebEvidenceJson.keys(request,WebEvidenceProtocol.requestKeys(code));
        need(WebEvidenceProtocol.requestSchema(code).equals(text(request,"schema")),"request schema differs");
        need(WebEvidenceProtocol.hex32(text(request,"task_id"))&&WebEvidenceProtocol.hex64(text(request,"controller_session_nonce"))
                &&WebEvidenceProtocol.hex64(text(request,"request_nonce")),"request identity shape differs");
        long deadline=number(request,"deadline_elapsed_ms");
        need(sentElapsed>=0&&receivedElapsed>=sentElapsed&&receivedElapsed<=deadline
                &&deadline>sentElapsed&&deadline-sentElapsed<=WebEvidenceProtocol.MAX_RPC_FUTURE_MS,"reply outside original RPC budget");
        need(text(binding,"task_id").equals(text(request,"task_id"))&&text(binding,"controller_session_nonce").equals(text(request,"controller_session_nonce"))
                &&WebEvidenceProtocol.BINDING_SCHEMA.equals(text(binding,"schema")),"immutable request binding differs");
        need(number(binding.getJSONObject("helper_identity"),"version_code")==WebEvidenceProtocol.HELPER_VERSION_CODE,
                "exact formal helper code is required; observer is not a task peer");
        JSONObject callback=WebEvidenceJson.parse(callbackRaw,WebEvidenceProtocol.MAX_CALLBACK_BYTES);
        WebEvidenceJson.keys(callback,WebEvidenceProtocol.CALLBACK_KEYS);
        need(WebEvidenceProtocol.CALLBACK_SCHEMA.equals(text(callback,"schema"))&&WebEvidenceProtocol.method(code).equals(text(callback,"method"))
                &&text(request,"request_nonce").equals(text(callback,"request_nonce"))
                &&text(request,"task_id").equals(text(callback,"task_id"))
                &&text(request,"controller_session_nonce").equals(text(callback,"controller_session_nonce")),"reply request identity differs");
        need(authenticatedHelperUid>=10000&&authenticatedHelperUid==WebEvidenceJson.integer(callback,"actual_helper_uid")
                &&authenticatedHelperUid==WebEvidenceJson.integer(binding.getJSONObject("helper_identity"),"uid"),"reply actual helper UID differs");
        Object reason=callback.get("reason");need(reason==JSONObject.NULL||reason instanceof String&&((String)reason).length()<=512,"reply reason shape");
        long length=number(callback,"raw_length");need(length>=0&&length<=WebEvidenceProtocol.MAX_EVIDENCE_BYTES,"raw evidence size");
        if(raw==null)need(length==0&&callback.get("raw_sha256")==JSONObject.NULL,"unexpected raw reference without FD");
        else need(length==raw.length&&length>0&&WebEvidenceProtocol.hex64(text(callback,"raw_sha256"))
                &&WebEvidenceJson.sha(raw).equals(text(callback,"raw_sha256")),"exact raw FD bytes/hash differ");
        String status=text(callback,"status"),bindingSha=WebEvidenceBinding.sha256(binding);
        boolean reject="rejected".equals(status);
        if(reject){
            need(raw==null&&callback.get("recovery")==JSONObject.NULL,"rejected reply contains evidence");
            throw new IllegalStateException("网页证据暂不可用："+(reason==JSONObject.NULL?status:reason));
        }
        need(bindingSha.equals(text(callback,"binding_sha256")),"reply binding SHA differs");
        if("unavailable".equals(status)){
            need(code==WebEvidenceProtocol.CAPTURE&&raw==null&&Boolean.FALSE.equals(callback.get("retired"))
                    &&callback.get("cleanup")==JSONObject.NULL&&callback.get("recovery")==JSONObject.NULL,
                    "only a live capture may report metadata-only unavailable");
            domain(callback,binding);
            Object expected=request.get("expected_webview_instance"),expectedEpoch=request.get("expected_navigation_epoch");
            need(expected==JSONObject.NULL&&expectedEpoch==JSONObject.NULL
                    ||expected instanceof String&&expected.equals(callback.get("webview_instance"))
                    &&(expectedEpoch instanceof Integer||expectedEpoch instanceof Long)
                    &&((Number)expectedEpoch).longValue()==number(callback,"navigation_epoch"),
                    "unavailable capture changed its exact expected page");
            return new WebEvidenceReceipt(callback,null,null,null,false,false);
        }
        if(code==WebEvidenceProtocol.CLOSE){
            need(Boolean.TRUE.equals(callback.get("retired")),"closed reply is not retired");
            if("closed".equals(status)){
                need(raw==null&&callback.get("recovery")==JSONObject.NULL,"ordinary close must not contain recovered proof");
                JSONObject cleanup=callback.getJSONObject("cleanup");WebEvidenceJson.keys(cleanup,WebEvidenceProtocol.CLEANUP_KEYS);
                for(String key:WebEvidenceProtocol.CLEANUP_KEYS)need(Boolean.TRUE.equals(cleanup.get(key)),"actual helper cleanup incomplete: "+key);
                domain(callback,binding);return new WebEvidenceReceipt(callback,null,null,null,true,false);
            }
            need(("recovered_retired".equals(status)||"unstarted_retired".equals(status))&&raw!=null,"unknown close evidence type");
            need(WebEvidenceJson.integer(callback,"actual_display_id")==-1&&WebEvidenceJson.integer(callback,"actual_window_id")==-1
                    &&callback.get("webview_instance")==JSONObject.NULL&&callback.get("navigation_epoch")==JSONObject.NULL,
                    "recovery must not represent an old view as live");
            String original=decode(raw);JSONObject evidence=WebEvidenceJson.parseEvidence(original,WebEvidenceProtocol.MAX_EVIDENCE_BYTES);
            if("unstarted_retired".equals(status)){
                JSONObject initial;String schema=text(evidence,"schema");
                if(WebEvidenceProtocol.UNSTARTED_SCHEMA.equals(schema)){
                    need(raw.length<=WebEvidenceProtocol.MAX_UNSTARTED_RECORD_BYTES,"initial unstarted FD budget");
                    requireRequestAndBinding(evidence,requestRaw,binding);initial=evidence;
                }else{
                    need(WebEvidenceProtocol.UNSTARTED_CONFIRMATION_SCHEMA.equals(schema),"exact unstarted retirement type");
                    requireOriginalRequest(evidence,requestRaw);
                    need(bindingSha.equals(text(evidence,"binding_sha256")),"confirmation binding hash differs");
                    initial=WebEvidenceJson.parseEvidence(text(evidence,"initial_record_utf8"),WebEvidenceProtocol.MAX_UNSTARTED_RECORD_BYTES);
                    need(WebEvidenceProtocol.UNSTARTED_SCHEMA.equals(text(initial,"schema")),"confirmation must preserve an initial proof");
                    requireRequestAndBinding(initial,text(initial,"request_json_utf8"),binding);
                }
                // Independently reject duplicate keys/types inside every preserved raw JSON.
                WebEvidenceJson.parse(text(initial,"request_json_utf8"),WebEvidenceProtocol.MAX_REQUEST_BYTES);
                WebEvidenceJson.parse(text(initial,"attach_request_json_utf8"),WebEvidenceProtocol.MAX_REQUEST_BYTES);
                WebEvidenceJson.parseEvidence(text(initial,"prior_journal_utf8"),65536);
                JSONObject verdict=WebRecoveryPolicy.evaluateUnstartedRecord(evidence);
                need(Boolean.TRUE.equals(verdict.get("retirement_verified"))
                        &&Boolean.TRUE.equals(verdict.get("owned_resources_never_started"))
                        &&Boolean.FALSE.equals(verdict.get("old_cleanup_methods_verified"))
                        &&Boolean.FALSE.equals(verdict.get("storage_cleanup_called"))
                        &&text(request,"request_nonce").equals(text(verdict,"request_nonce"))
                        &&same(verdict,callback.getJSONObject("recovery"))
                        &&same(initial.get("original_cleanup"),callback.get("cleanup")),
                        "unstarted retirement replay failed or changed old facts");
                return new WebEvidenceReceipt(callback,original,null,null,true,false);
            }
            requireRequestAndBinding(evidence,requestRaw,binding);
            // Parse embedded records strictly before the shared semantic replay, which uses org.json.
            WebEvidenceJson.parseEvidence(text(evidence,"prior_journal_utf8"),65536);
            WebEvidenceJson.parse(text(evidence,"request_json_utf8"),WebEvidenceProtocol.MAX_REQUEST_BYTES);
            JSONObject verdict=WebRecoveryPolicy.evaluateRecord(evidence);
            need(Boolean.TRUE.equals(verdict.get("retirement_verified"))
                    &&Boolean.TRUE.equals(verdict.get("recorded_profile_retirement_verified"))
                    &&Boolean.FALSE.equals(verdict.get("old_cleanup_methods_verified"))
                    &&same(verdict,callback.getJSONObject("recovery"))
                    &&same(evidence.get("original_cleanup"),callback.get("cleanup")),"recovered retirement replay failed or changed old facts");
            return new WebEvidenceReceipt(callback,original,null,null,true,true);
        }
        need(Boolean.FALSE.equals(callback.get("retired"))&&callback.get("cleanup")==JSONObject.NULL
                &&callback.get("recovery")==JSONObject.NULL,"active reply overclaims cleanup");
        domain(callback,binding);
        if(code==WebEvidenceProtocol.ATTACH){
            need("attached".equals(status)&&raw==null,"attach response differs");
            return new WebEvidenceReceipt(callback,null,null,null,false,false);
        }
        if(code==WebEvidenceProtocol.ARM_OBSERVED_LINK){
            need("armed".equals(status)&&raw!=null,"observed link ARM requires its exact read-only FD");
            String original=decode(raw);JSONObject evidence=WebEvidenceJson.parseEvidence(original,WebEvidenceProtocol.MAX_EVIDENCE_BYTES);
            exact(evidence,"schema","request_json_utf8","request_sha256","binding","binding_sha256","controller_identity","helper_identity",
                    "actual_window_id","arm","storage_isolation","actor","diagnostic_unbound","business_verified");
            need(WebEvidenceProtocol.RAW_SCHEMA.equals(text(evidence,"schema"))
                    &&"controller_observed_link_arm".equals(text(evidence,"actor"))
                    &&Boolean.FALSE.equals(evidence.get("diagnostic_unbound"))&&Boolean.FALSE.equals(evidence.get("business_verified")),
                    "formal observed-link ARM provenance required");
            requireRequestAndBinding(evidence,requestRaw,binding);
            need(same(evidence.getJSONObject("controller_identity"),binding.getJSONObject("controller_identity"))
                    &&same(evidence.getJSONObject("helper_identity"),binding.getJSONObject("helper_identity"))
                    &&number(evidence,"actual_window_id")==number(callback,"actual_window_id"),
                    "ARM installed/window identity differs");
            JSONObject arm=WebObservedNavigation.verifyArm(request,binding,sourceCapture,evidence.getJSONObject("arm"));
            long armed=number(arm,"armed_elapsed_ms"),expires=number(arm,"expires_elapsed_ms");
            need(sentElapsed<=armed&&armed<=receivedElapsed&&receivedElapsed<=expires
                    &&number(sourceCapture,"ended_elapsed_ms")<=sentElapsed
                    &&text(arm,"webview_instance").equals(text(callback,"webview_instance"))
                    &&number(arm,"navigation_epoch")==number(callback,"navigation_epoch")
                    &&number(arm,"actual_window_id")==number(callback,"actual_window_id")
                    &&number(arm,"display_id")==number(callback,"actual_display_id"),
                    "ARM reply is stale or belongs to another actual source window");
            WebStorageEvidence.requireCapture(binding,evidence.getJSONObject("storage_isolation"),armed,armed);
            return new WebEvidenceReceipt(callback,original,null,null,false,false,null,arm);
        }
        need(code==WebEvidenceProtocol.CAPTURE,"unknown method");
        if("state_changed".equals(status)){
            need(raw==null,"state change is metadata only");
            Object expectedInstance=request.get("expected_webview_instance"),expectedEpoch=request.get("expected_navigation_epoch");
            need(expectedInstance==JSONObject.NULL&&expectedEpoch==JSONObject.NULL
                    ||expectedInstance instanceof String&&expectedInstance.equals(callback.get("webview_instance"))
                    &&expectedEpoch instanceof Number&&number(callback,"navigation_epoch")>((Number)expectedEpoch).longValue(),
                    "state change must advance the same expected instance");
            return new WebEvidenceReceipt(callback,null,null,null,false,false);
        }
        need("captured".equals(status)&&raw!=null,"capture response differs");
        String original=decode(raw);JSONObject evidence=WebEvidenceJson.parseCaptureEvidence(original,WebEvidenceProtocol.MAX_EVIDENCE_BYTES);
        exact(evidence,"schema","request_json_utf8","request_sha256","binding","binding_sha256","controller_identity","helper_identity",
                "actual_window_id","capture","storage_isolation","actor","diagnostic_unbound","business_verified");
        need(WebEvidenceProtocol.RAW_SCHEMA.equals(text(evidence,"schema"))&&"controller_evidence_capture".equals(text(evidence,"actor"))
                &&Boolean.FALSE.equals(evidence.get("diagnostic_unbound"))&&Boolean.FALSE.equals(evidence.get("business_verified")),
                "bound controller capture required; diagnostics are not task evidence");
        requireRequestAndBinding(evidence,requestRaw,binding);
        need(same(evidence.getJSONObject("controller_identity"),binding.getJSONObject("controller_identity"))
                &&same(evidence.getJSONObject("helper_identity"),binding.getJSONObject("helper_identity"))
                &&number(evidence,"actual_window_id")==number(callback,"actual_window_id"),"raw installed/window identity differs");
        JSONObject capture=evidence.getJSONObject("capture");
        exact(capture,"schema","challenge","binding","helper_package","helper_uid","helper_pid","display_id","webview_instance",
                "actual_window_id","webview_bounds_screen_pixels","navigation_epoch","committed_main_frame_url","commit_elapsed_ms",
                "current_native_url","native_url_source","commit_source","visual_request_id","dom_raw_utf8","dom_sha256",
                "observer_script_sha256","started_elapsed_ms","ended_elapsed_ms","business_verified","pixel_equality_claimed",
                "all_visible_semantics_verified","truncated","capture_geometry","before_dom_raw_utf8","before_dom_sha256",
                "dom_stability","dom_stability_sha256","raw_dom_equal","comparison_scope","observed_link_navigation");
        need(WebObservedNavigation.CAPTURE_SCHEMA.equals(text(capture,"schema"))
                &&text(request,"request_nonce").equals(text(capture,"challenge"))&&same(binding,capture.getJSONObject("binding"))
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(capture,"helper_package"))
                &&number(capture,"helper_uid")==authenticatedHelperUid&&number(capture,"helper_pid")>0
                &&number(capture,"display_id")==number(callback,"actual_display_id")
                &&number(capture,"actual_window_id")==number(callback,"actual_window_id")
                &&text(capture,"webview_instance").equals(text(callback,"webview_instance"))
                &&number(capture,"navigation_epoch")==number(callback,"navigation_epoch"),"native capture identity differs");
        Object expected=request.get("expected_webview_instance"),epoch=request.get("expected_navigation_epoch");
        need((expected==JSONObject.NULL)==(epoch==JSONObject.NULL),"capture expectation pair");
        if(expected!=JSONObject.NULL)need(expected.equals(capture.get("webview_instance"))
                &&epoch instanceof Number&&((Number)epoch).longValue()==number(capture,"navigation_epoch"),"capture ignored exact instance/epoch");
        long started=number(capture,"started_elapsed_ms"),ended=number(capture,"ended_elapsed_ms"),committed=number(capture,"commit_elapsed_ms");
        JSONObject bg=binding.getJSONObject("background");
        need(number(bg,"created_elapsed_ms")<=committed&&committed<=started&&sentElapsed<=started
                &&started<=ended&&ended<=receivedElapsed&&ended-started<=WebEvidenceProtocol.CAPTURE_MS
                &&receivedElapsed<number(bg,"expires_elapsed_ms"),"capture/commit/RPC/lease time bracket differs");
        need("android.webkit.WebView.getUrl".equals(text(capture,"native_url_source"))
                &&"android.webkit.WebViewClient.onPageCommitVisible".equals(text(capture,"commit_source"))
                &&OBSERVER_SHA.equals(text(capture,"observer_script_sha256")),"native URL/fixed observer provenance differs");
        String url=text(capture,"current_native_url");String origin=purposeOrigin(purpose,url);
        need(origin.equals(purposeOrigin(purpose,text(capture,"committed_main_frame_url"))),"current and committed per-lease origins differ");
        for(String key:Arrays.asList("business_verified","pixel_equality_claimed","all_visible_semantics_verified","truncated"))
            need(Boolean.FALSE.equals(capture.get(key)),"capture scope/truncation differs: "+key);
        JSONArray box=capture.getJSONArray("webview_bounds_screen_pixels");
        need(box.length()==4,"native WebView bounds shape");
        long[] r=new long[4];for(int i=0;i<4;i++){Object v=box.get(i);need(v instanceof Integer||v instanceof Long,"integer native bounds");r[i]=((Number)v).longValue();}
        need(0<=r[0]&&0<=r[1]&&r[0]<r[2]&&r[1]<r[3]&&r[2]<=32768&&r[3]<=32768,"native WebView bounds invalid");
        String beforeRaw=text(capture,"before_dom_raw_utf8"),domRaw=text(capture,"dom_raw_utf8");
        need(WebEvidenceJson.sha(beforeRaw).equals(text(capture,"before_dom_sha256"))
                &&WebEvidenceJson.sha(domRaw).equals(text(capture,"dom_sha256")),"both exact DOM byte hashes required");
        JSONObject beforeDom=WebEvidenceJson.parseDom(beforeRaw),dom=WebEvidenceJson.parseDom(domRaw);
        for(JSONObject observed:Arrays.asList(beforeDom,dom)){
            need(WebDomStability.DOM_SCHEMA.equals(text(observed,"schema"))&&url.equals(text(observed,"href"))
                    &&origin.equals(text(observed,"origin"))&&"complete".equals(text(observed,"ready_state"))
                    &&Boolean.FALSE.equals(observed.get("truncated")),"DOM/current native origin/ready/truncation differs");
            need(observed.getJSONArray("nodes").length()<=1536&&number(observed,"visited")==observed.getJSONArray("nodes").length(),
                    "complete wire-v4 DOM node budget");
        }
        WebDomStability.Result stability=WebDomStability.verify(beforeRaw,domRaw,purpose.sitePolicyId,capture.getJSONObject("dom_stability"));
        need(stability.beforeRawSha256.equals(text(capture,"before_dom_sha256"))
                &&stability.afterRawSha256.equals(text(capture,"dom_sha256"))
                &&WebDomCanonical.sha256(stability.evidence()).equals(text(capture,"dom_stability_sha256"))
                &&Boolean.valueOf(stability.rawEqual).equals(capture.get("raw_dom_equal"))
                &&stability.comparisonScope.equals(text(capture,"comparison_scope")),
                "complete independent raw-pair/scope replay differs");
        if(purpose.flight!=null)need(stability.rawEqual&&WebDomStability.FULL_SCOPE.equals(stability.comparisonScope),
                "flight still requires the complete original raw equality predicate");
        Object navigation=capture.get("observed_link_navigation");
        if(navigation!=JSONObject.NULL){
            need(purpose.shopping!=null&&navigation instanceof JSONObject,"only a typed product-link navigation record is supported");
            JSONObject observed=(JSONObject)navigation;
            WebObservedNavigation.requireNavigationRecordShape(observed);
            JSONObject arm=observed.getJSONObject("arm");
            need(WebEvidenceBinding.sha256(binding).equals(text(arm,"binding_sha256"))
                    &&text(binding,"task_id").equals(text(arm,"task_id"))
                    &&text(binding,"controller_session_nonce").equals(text(arm,"controller_session_nonce"))
                    &&text(binding,"storage_profile_name").equals(text(arm,"storage_profile_name"))
                    &&text(capture,"webview_instance").equals(text(arm,"webview_instance"))
                    &&number(capture,"actual_window_id")==number(arm,"actual_window_id")
                    &&number(capture,"display_id")==number(arm,"display_id")
                    &&number(arm,"navigation_epoch")<=number(capture,"navigation_epoch")
                    &&number(arm,"armed_elapsed_ms")<=started,
                    "observed navigation record belongs to another lease/window/instance or future ARM");
            // This preserves partial/cancelled producer facts. It grants no
            // navigation success: the private expected ARM and original native
            // ActionOutcome/time bracket are replayed separately by the domain.
        }
        need(WebNativeGeometry.read(capture,dom,WebEvidenceJson.integer(callback,"actual_display_id"),
                WebEvidenceJson.integer(callback,"actual_window_id"),stability)!=null,"formal capture requires actual native geometry");
        WebStorageEvidence.requireCapture(binding,evidence.getJSONObject("storage_isolation"),started,ended);
        return new WebEvidenceReceipt(callback,original,capture.toString(),domRaw,false,false,stability,null);
    }

    private static String purposeOrigin(WebTaskPurpose purpose,String value)throws Exception{
        need(purpose!=null,"original recognized page purpose required");
        if(purpose.flight!=null)return officialOrigin(value);
        WebSitePolicy policy=WebSitePolicy.forShopping(purpose.shopping);
        need(policy.sha256.equals(purpose.sitePolicySha256)&&policy.allowsMainFrame(value),
                "URL is outside this lease's compiled public-product route");
        return policy.origin;
    }
    static String officialOrigin(String value)throws Exception{
        need(value!=null&&value.length()<=4096,"URL budget");URI uri=new URI(value);
        need("https".equals(uri.getScheme())&&"m.csair.com".equals(uri.getHost())&&uri.getRawUserInfo()==null
                &&(uri.getPort()==-1||uri.getPort()==443)&&!uri.isOpaque(),"only the fixed official HTTPS origin is covered");
        return "https://m.csair.com";
    }
    private static void domain(JSONObject callback,JSONObject binding)throws Exception{
        need(number(callback,"actual_display_id")==number(binding.getJSONObject("background"),"display_id")
                &&number(callback,"actual_display_id")>0&&number(callback,"actual_window_id")>=0
                &&WebEvidenceProtocol.uuid(text(callback,"webview_instance"))&&number(callback,"navigation_epoch")>=0,"actual bound view identity required");
    }
    private static void requireOriginalRequest(JSONObject evidence,String raw)throws Exception{
        need(raw.equals(text(evidence,"request_json_utf8"))&&WebEvidenceJson.sha(raw).equals(text(evidence,"request_sha256")),
                "raw original request differs");
    }
    private static void requireRequestAndBinding(JSONObject evidence,String raw,JSONObject binding)throws Exception{
        need(raw.equals(text(evidence,"request_json_utf8"))&&WebEvidenceJson.sha(raw).equals(text(evidence,"request_sha256"))
                &&same(binding,evidence.getJSONObject("binding"))&&WebEvidenceBinding.sha256(binding).equals(text(evidence,"binding_sha256")),
                "raw request/immutable binding differs");
    }
    static boolean same(Object a,Object b)throws Exception{return WebEvidenceBinding.canonical(a).equals(WebEvidenceBinding.canonical(b));}
    static String decode(byte[] bytes)throws Exception{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
            .onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}
    static void exact(JSONObject o,String...keys)throws Exception{WebEvidenceJson.keys(o,new HashSet<String>(Arrays.asList(keys)));}
    static String text(JSONObject o,String k)throws Exception{return WebEvidenceJson.text(o,k);}
    static long number(JSONObject o,String k)throws Exception{return WebEvidenceJson.number(o,k);}
    static String nullableText(JSONObject o,String k)throws Exception{return o.get(k)==JSONObject.NULL?null:text(o,k);}
    static void need(boolean ok,String why){WebEvidenceJson.need(ok,why);}
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.webprotocol.WebDomCanonical;
import org.trillionnium.hepta.webprotocol.WebDomStability;
import org.trillionnium.hepta.webprotocol.WebTaskPurpose;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;

/**
 * Replays the owned WebView's four real native samples. This establishes a
 * stable native rectangle only; it never converts CSS geometry into a click.
 */
final class WebNativeGeometry {
    static final String SCHEMA="hepta.webview-geometry-bracket.v2";
    private static final String[] PHASES={"before_js1","after_js1","before_js2","after_js2"};
    final int displayId,windowId;
    final int[] bounds;
    final long firstSample,lastSample;
    final String fingerprint;
    private final String actualRaw;

    private WebNativeGeometry(JSONObject original,int display,int window,int[] bounds,
                              long first,long last,String stable)throws Exception{
        displayId=display;windowId=window;this.bounds=bounds.clone();
        firstSample=first;lastSample=last;fingerprint=sha(stable);actualRaw=original.toString();
    }

    /** Missing legacy geometry is not an action capability. Malformed new evidence is rejected. */
    static WebNativeGeometry read(JSONObject capture,JSONObject dom,int display,int window)throws Exception{
        if(!capture.has("capture_geometry"))return null;
        WebTaskPurpose purpose=WebTaskPurpose.requireBinding(capture.getJSONObject("binding"));
        String beforeRaw=string(capture,"before_dom_raw_utf8"),afterRaw=string(capture,"dom_raw_utf8");
        // Reject duplicate keys and invalid Unicode before the shared semantic replay.
        WebEvidenceJson.parseDom(beforeRaw);JSONObject after=WebEvidenceJson.parseDom(afterRaw);
        need(WebDomCanonical.same(dom,after),"geometry DOM differs from the exact captured after-DOM");
        WebDomStability.Result checked=WebDomStability.verify(beforeRaw,afterRaw,purpose.sitePolicyId,
                capture.getJSONObject("dom_stability"));
        return read(capture,dom,display,window,checked);
    }
    /** The checked result can only be created by the shared complete two-raw replay. */
    static WebNativeGeometry read(JSONObject capture,JSONObject dom,int display,int window,
                                  WebDomStability.Result checked)throws Exception{
        if(!capture.has("capture_geometry"))return null;
        need(checked!=null&&checked.beforeRawSha256.equals(string(capture,"before_dom_sha256"))
                &&checked.afterRawSha256.equals(string(capture,"dom_sha256"))
                &&WebDomCanonical.sha256(checked.evidence()).equals(string(capture,"dom_stability_sha256"))
                &&checked.comparisonScope.equals(string(capture,"comparison_scope"))
                &&Boolean.valueOf(checked.rawEqual).equals(capture.get("raw_dom_equal")),
                "actual independent DOM stability replay is required");
        JSONObject geometry=capture.getJSONObject("capture_geometry");
        keys(geometry,"schema","samples","native_samples_equal","dom_equal_across_visual_callback",
                "dom_comparison_scope","dom_stability_sha256","ui_thread_bracket",
                "get_scale_is_deprecated_racy_observation","css_to_screen_mapping_verified");
        need(SCHEMA.equals(string(geometry,"schema"))
                &&Boolean.valueOf(checked.rawEqual).equals(geometry.get("dom_equal_across_visual_callback"))
                &&checked.comparisonScope.equals(string(geometry,"dom_comparison_scope"))
                &&string(capture,"dom_stability_sha256").equals(string(geometry,"dom_stability_sha256")),
                "native geometry must carry the exact independently checked DOM scope");
        for(String key:new String[]{"native_samples_equal","ui_thread_bracket",
                "get_scale_is_deprecated_racy_observation"})need(Boolean.TRUE.equals(geometry.get(key)),"native geometry fact: "+key);
        need(Boolean.FALSE.equals(geometry.get("css_to_screen_mapping_verified")),"CSS mapping is not verified");
        need(display>0&&window>=0&&integer(capture,"display_id")==display
                &&integer(capture,"actual_window_id")==window,"actual geometry display/window");
        long started=integer(capture,"started_elapsed_ms"),ended=integer(capture,"ended_elapsed_ms");
        need(started>=0&&ended>=started&&ended-started<=3000,"bounded actual capture interval");
        int[] expected=rect(capture.getJSONArray("webview_bounds_screen_pixels"),true);
        JSONArray samples=geometry.getJSONArray("samples");need(samples.length()==4,"four ordered native samples");
        String firstStable=null;long first=-1,last=-1;
        for(int i=0;i<4;i++){
            JSONObject sample=samples.getJSONObject(i);keys(sample,"phase","native");
            need(PHASES[i].equals(string(sample,"phase")),"native geometry phase order");
            JSONObject nativeState=sample.getJSONObject("native");
            keys(nativeState,"sampled_elapsed_ms","display_id","actual_window_id","bounds_screen_pixels",
                    "global_visible_rect_pixels","global_visible_rect_source","scroll_pixels","padding_pixels",
                    "view_transform","webview_get_scale","scale_change_sequence","scale_changed_elapsed_ms",
                    "scale_callback_old","scale_callback_new","use_wide_viewport","load_with_overview_mode");
            long now=integer(nativeState,"sampled_elapsed_ms");
            need(now>=started&&now<=ended&&(last<0||now>=last),"native sample outside capture interval");
            if(i==0)first=now;last=now;
            need(integer(nativeState,"display_id")==display&&integer(nativeState,"actual_window_id")==window,
                    "native sample belongs to another window");
            int[] bounds=rect(nativeState.getJSONArray("bounds_screen_pixels"),true);
            need(Arrays.equals(expected,bounds),"native view rectangle changed");
            int[] visible=rect(nativeState.getJSONArray("global_visible_rect_pixels"),false);
            need("View.getGlobalVisibleRect; root-view coordinates".equals(string(nativeState,"global_visible_rect_source")),
                    "global visible rectangle provenance");
            // These coordinates have another origin. Only their dimensions are
            // compared; they are never treated as screen positions.
            need(visible[2]-visible[0]==bounds[2]-bounds[0]&&visible[3]-visible[1]==bounds[3]-bounds[1],
                    "native WebView is partly clipped");
            long[] scroll=integerArray(nativeState.getJSONArray("scroll_pixels"),2);
            long[] padding=integerArray(nativeState.getJSONArray("padding_pixels"),4);
            for(long value:padding)need(value==0,"unreviewed WebView padding");
            double[] transform=numberArray(nativeState.getJSONArray("view_transform"),5);
            need(transform[0]==1.0&&transform[1]==1.0&&transform[2]==0.0&&transform[3]==0.0&&transform[4]==0.0,
                    "unreviewed native transform");
            double scale=number(nativeState.get("webview_get_scale"));
            need(scale>0&&scale<=64,"actual native scale range");
            long sequence=integer(nativeState,"scale_change_sequence"),changed=integer(nativeState,"scale_changed_elapsed_ms");
            need(sequence>=0&&changed>=0&&changed<=now,"actual scale callback history");
            Object oldScale=nativeState.get("scale_callback_old"),newScale=nativeState.get("scale_callback_new");
            need((oldScale==JSONObject.NULL)==(newScale==JSONObject.NULL),"scale callback pair");
            if(oldScale==JSONObject.NULL)need(sequence==0&&changed==0,"missing actual scale callback values");
            else need(sequence>0&&changed>0&&number(oldScale)>0&&number(newScale)>0,"actual scale callback values");
            need(Boolean.TRUE.equals(nativeState.get("use_wide_viewport"))
                    &&Boolean.TRUE.equals(nativeState.get("load_with_overview_mode")),"actual viewport settings");
            JSONObject stable=new JSONObject();
            // A fixed key order and normalized finite numeric values allow an
            // exact cross-capture comparison without using binding's integer-only codec.
            stable.put("display",display).put("window",window).put("bounds",new JSONArray(bounds))
                    .put("visible_dimensions",new JSONArray(new int[]{visible[2]-visible[0],visible[3]-visible[1]}))
                    .put("visible_root_rectangle",new JSONArray(visible)).put("scroll",new JSONArray(scroll))
                    .put("padding",new JSONArray(padding)).put("transform",new JSONArray(transform))
                    .put("scale",scale).put("scale_sequence",sequence).put("scale_changed",changed)
                    .put("scale_old",oldScale==JSONObject.NULL?JSONObject.NULL:number(oldScale))
                    .put("scale_new",newScale==JSONObject.NULL?JSONObject.NULL:number(newScale));
            String current=stable.toString();
            if(firstStable==null)firstStable=current;else need(firstStable.equals(current),"native geometry changed across JS samples");
        }
        need(WebDomStability.DOM_SCHEMA.equals(string(dom,"schema"))
                &&Boolean.FALSE.equals(dom.get("geometry_semantics_verified")),"actual wire-v4 viewport observer schema");
        JSONObject vv=dom.getJSONObject("visual_viewport");
        keys(vv,"width","height","offset_left","offset_top","page_left","page_top","scale");
        need(number(vv.get("width"))>0&&number(vv.get("height"))>0
                &&number(vv.get("scale"))>0&&number(vv.get("scale"))<=64,"actual visual viewport dimensions");
        for(String key:new String[]{"offset_left","offset_top","page_left","page_top"})number(vv.get(key));
        numberArray(dom.getJSONArray("viewport_css_pixels"),2);
        numberArray(dom.getJSONArray("layout_viewport_css_pixels"),2);
        numberArray(dom.getJSONArray("document_scroll_css_pixels"),2);
        numberArray(dom.getJSONArray("document_extent_css_pixels"),2);
        // DOM geometry is retained as an independent state guard. It is not a
        // formula for translating CSS positions or DPR into Android coordinates.
        JSONObject stable=new JSONObject().put("native",new JSONObject(firstStable))
                .put("visual_viewport",vv).put("viewport",dom.getJSONArray("viewport_css_pixels"))
                .put("layout_viewport",dom.getJSONArray("layout_viewport_css_pixels"))
                .put("document_scroll",dom.getJSONArray("document_scroll_css_pixels"))
                .put("document_extent",dom.getJSONArray("document_extent_css_pixels"));
        return new WebNativeGeometry(geometry,display,window,expected,first,last,stable.toString());
    }
    JSONObject evidence()throws Exception{
        return new JSONObject().put("schema","hepta.native-webview-geometry-replay.v1")
                .put("native_geometry_sha256",fingerprint).put("display_id",displayId).put("window_id",windowId)
                .put("native_bounds_screen_pixels",new JSONArray(bounds)).put("first_sample_elapsed_ms",firstSample)
                .put("last_sample_elapsed_ms",lastSample).put("source_geometry",new JSONObject(actualRaw))
                .put("css_to_screen_mapping_used",false).put("proves_action_or_occlusion",false);
    }
    boolean same(WebNativeGeometry other){return other!=null&&fingerprint.equals(other.fingerprint);}
    boolean contains(int left,int top,int right,int bottom){
        return left<right&&top<bottom&&bounds[0]<=left&&bounds[1]<=top&&right<=bounds[2]&&bottom<=bounds[3];
    }
    static int[] rect(JSONArray value,boolean screen)throws Exception{
        long[] raw=integerArray(value,4);int[] out=new int[4];
        for(int i=0;i<4;i++){need(raw[i]>=-32768&&raw[i]<=32768,"bounded native rectangle");out[i]=(int)raw[i];}
        need(out[0]<out[2]&&out[1]<out[3]&&(!screen||out[0]>=0&&out[1]>=0),"nonempty native rectangle");
        return out;
    }
    private static long[] integerArray(JSONArray values,int length)throws Exception{
        need(values.length()==length,"integer array shape");long[] out=new long[length];
        for(int i=0;i<length;i++){Object value=values.get(i);need(value instanceof Integer||value instanceof Long,"actual integer array value");out[i]=((Number)value).longValue();}
        return out;
    }
    private static double[] numberArray(JSONArray values,int length)throws Exception{
        need(values.length()==length,"numeric array shape");double[] out=new double[length];
        for(int i=0;i<length;i++)out[i]=number(values.get(i));return out;
    }
    private static double number(Object value){need(value instanceof Number,"actual numeric value");double n=((Number)value).doubleValue();
        need(!Double.isNaN(n)&&!Double.isInfinite(n),"finite numeric value");return n;}
    private static long integer(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof Integer||raw instanceof Long,"actual integer: "+key);return ((Number)raw).longValue();
    }
    private static String string(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof String,"actual string: "+key);return (String)raw;
    }
    private static void keys(JSONObject value,String...expected){
        Set<String> found=new HashSet<String>();Iterator<String> it=value.keys();while(it.hasNext())found.add(it.next());
        need(found.equals(new HashSet<String>(Arrays.asList(expected))),"exact geometry fields");
    }
    private static String sha(String value)throws Exception{
        byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();
    }
    private static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
}

package org.trillionnium.hepta.local;

import android.graphics.Rect;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable description of one observed active window and original-size screenshot. */
public final class PhoneObservation {
    /** Counters from the real bounded traversal, never inferred from a flat
     * archived node list. Legacy observations have no counters. These describe
     * collection limits; they do not supply node actions or business evidence. */
    public static final class CollectionStats {
        public static final String SCHEMA="hepta.observation-collection.v1";
        public final int visitLimit,nodeLimit,textLimit,visited,retained,textUtf16,pending,
                nodeBudgetOmissions,textBudgetOmissions;
        public final long childSlotsOmitted,elapsedMs;
        public final List<String> limitReasons;
        CollectionStats(int visitLimit,int nodeLimit,int textLimit,int visited,int retained,int textUtf16,
                        int pending,int nodeBudgetOmissions,int textBudgetOmissions,long childSlotsOmitted,long elapsedMs){
            if(visitLimit<=0||nodeLimit<=0||textLimit<=0||visited<0||visited>visitLimit
                    ||retained<0||retained>nodeLimit||textUtf16<0||textUtf16>=textLimit
                    ||pending<0||pending>visitLimit||nodeBudgetOmissions<0||textBudgetOmissions<0
                    ||childSlotsOmitted<0||elapsedMs<0)throw new IllegalArgumentException("invalid actual collection counters");
            this.visitLimit=visitLimit;this.nodeLimit=nodeLimit;this.textLimit=textLimit;
            this.visited=visited;this.retained=retained;this.textUtf16=textUtf16;this.pending=pending;
            this.nodeBudgetOmissions=nodeBudgetOmissions;this.textBudgetOmissions=textBudgetOmissions;
            this.childSlotsOmitted=childSlotsOmitted;this.elapsedMs=elapsedMs;
            List<String> reasons=new ArrayList<String>();
            if(childSlotsOmitted>0||pending>0)reasons.add("traversal_limit");
            if(nodeBudgetOmissions>0)reasons.add("node_limit");
            if(textBudgetOmissions>0)reasons.add("text_limit");
            limitReasons=Collections.unmodifiableList(reasons);
        }
        public boolean truncated(){return !limitReasons.isEmpty();}
        JSONObject json()throws JSONException{
            return new JSONObject().put("schema",SCHEMA).put("source","same_observed_accessibility_traversal")
                    .put("visit_limit",visitLimit).put("node_limit",nodeLimit).put("text_utf16_exclusive_limit",textLimit)
                    .put("visited_nodes",visited).put("retained_nodes",retained).put("retained_text_utf16",textUtf16)
                    .put("pending_nodes_at_stop",pending).put("child_slots_omitted_by_traversal_limit",childSlotsOmitted)
                    .put("nodes_omitted_by_node_limit",nodeBudgetOmissions).put("nodes_omitted_by_text_limit",textBudgetOmissions)
                    .put("truncation_reasons",new JSONArray(limitReasons)).put("elapsed_ms",elapsedMs)
                    .put("unvisited_descendant_count_known",false).put("grants_action_capability",false);
        }
    }
    public static final class Node {
        public final String id, packageName, className, viewId, text, description;
        public final ObservedChildText.Result childText;
        public final ObservedScrollActions scrollActions;
        public final ObservedImeEnter imeEnter;
        public final String inputTextSha256;
        /** Actual NodeRef signature, never reconstructed from serialized labels. */
        public final String observedAppTreeSignature;
        /** Position recorded by the same native traversal; legacy/omitted positions remain null. */
        public final String nativeTreePath,nativeParentClass;
        public final boolean submitAvailable;
        public final Rect bounds;
        public final boolean clickable, editable, scrollable, enabled, focused, password;
        Node(String id, String packageName, String className, String viewId, String text,
             String description, Rect bounds, boolean clickable, boolean editable,
             boolean scrollable, boolean enabled, boolean focused, boolean password,ObservedChildText.Result childText,
             ObservedScrollActions scrollActions) {
            this(id,packageName,className,viewId,text,description,bounds,clickable,editable,scrollable,enabled,focused,password,
                    childText,scrollActions,ObservedImeEnter.UNKNOWN,null,false);
        }
        Node(String id, String packageName, String className, String viewId, String text,
             String description, Rect bounds, boolean clickable, boolean editable,
             boolean scrollable, boolean enabled, boolean focused, boolean password,ObservedChildText.Result childText,
             ObservedScrollActions scrollActions,ObservedImeEnter imeEnter,String inputTextSha256,boolean submitAvailable) {
            this(id,packageName,className,viewId,text,description,bounds,clickable,editable,scrollable,enabled,focused,password,
