            scope=REGION_SCOPE;
        }
        JSONArray differences=new JSONArray();diff(before,after,"",differences,0);
        need(rawEqual||differences.length()>0,"nonidentical raw serialization alone is not a region proof");
        String beforeHash=WebDomCanonical.sha256Utf8(beforeRaw),afterHash=WebDomCanonical.sha256Utf8(afterRaw);
        JSONArray eligiblePaths=new JSONArray();
        if(shopping){if(last!=null)eligiblePaths.put(last.anchorPath);}
        else if(rawEqual){for(String path:an.keySet())eligiblePaths.put(path);}
        String targetPredicate=shopping?"selected_region_anchor_only":"actual_dom_membership_for_full_raw";
        JSONObject proof=new JSONObject().put("schema",PROOF_SCHEMA).put("dom_schema",DOM_SCHEMA)
                .put("site_policy_id",sitePolicyId).put("comparison_scope",scope).put("raw_dom_equal",rawEqual)
                .put("before_dom_sha256",beforeHash).put("after_dom_sha256",afterHash)
                .put("before_dom_utf8_bytes",bytes(beforeRaw)).put("after_dom_utf8_bytes",bytes(afterRaw))
                .put("both_complete_raw_dom_values_retained",true).put("all_json_differences",differences)
                .put("all_difference_count",differences.length()).put("outside_changed_rectangles",outsideRectangles)
                .put("region",last==null?JSONObject.NULL:last.evidence())
                .put("region_unavailable_reason",unavailable==null?JSONObject.NULL:unavailable)
                .put("target_predicate",targetPredicate).put("eligible_action_dom_paths",eligiblePaths)
                .put("eligible_paths_are_not_independent_action_authority",true)
                .put("scope_selected_by_compiled_task_policy",true).put("caller_supplied_selector_allowed",false)
                .put("whole_page_raw_equal",rawEqual).put("outside_visibility_inferred",false)
                .put("closed_shadow_contents_inspected",false).put("whole_page_pixel_visibility_verified",false)
                .put("grants_action_authority",false).put("business_verified",false);
        need(bytes(WebDomCanonical.canonical(proof))<=256*1024,"bounded complete stability proof");
        return new Result(rawEqual,scope,beforeHash,afterHash,proof,an.keySet(),shopping,last);
    }
    public static Result verify(String before,String after,String policy,JSONObject claimed)throws Exception{
        Result result=evaluate(before,after,policy);
        need(claimed!=null&&WebDomCanonical.same(result.evidence(),claimed),"claimed scope differs from both original DOMs");
        return result;
    }
    public static Map<String,JSONObject> index(JSONObject dom)throws Exception{
        need(DOM_SCHEMA.equals(text(dom,"schema"))&&"complete".equals(text(dom,"ready_state"))
                &&Boolean.FALSE.equals(dom.get("truncated"))&&dom.getJSONArray("truncation_reasons").length()==0,
                "complete untruncated DOM-v4 required; legacy raw pairs cannot prove new region semantics");
        JSONArray rows=dom.getJSONArray("nodes");need(rows.length()>0&&rows.length()<=MAX_NODES,"bounded complete DOM");
        Map<String,JSONObject> nodes=new LinkedHashMap<String,JSONObject>();
        for(int i=0;i<rows.length();i++){
            JSONObject node=rows.getJSONObject(i);String path=text(node,"path");
            need(path.matches("0(?:/[0-9]{1,5}){0,32}")&&!nodes.containsKey(path),"unique bounded actual DOM path");
            String expected=parent(path);Object actual=node.get("parent_path");
            need(expected==null?actual==JSONObject.NULL:expected.equals(actual),"real DOM parent path required");
            for(String key:new String[]{"tag","id","name","role","aria_label","aria_hidden","aria_modal","aria_selected","aria_checked","aria_pressed","text","item_type","item_prop"})
                text(node,key);
            for(String key:new String[]{"visible_in_viewport","disabled","hidden_attr","inert_attr","item_scope","iframe_contents_read"})
                need(node.get(key) instanceof Boolean,"typed raw DOM boolean: "+key);
            need(Boolean.FALSE.equals(node.get("iframe_contents_read")),"independent frame content is outside this observer scope");
            for(String key:new String[]{"href_raw","href_resolved","link_target","value","aria_disabled"}){
                Object value=node.get(key);need(value==JSONObject.NULL||value instanceof String&&((String)value).length()<=4096,"bounded raw node scalar: "+key);
            }
            rect(node.getJSONArray("rect_css_pixels"));nodes.put(path,node);
        }
        for(String path:nodes.keySet())if(!"0".equals(path))need(nodes.containsKey(parent(path)),"complete DOM ancestry required");
        Object visited=dom.get("visited");need((visited instanceof Integer||visited instanceof Long)&&((Number)visited).longValue()==rows.length(),"visited/record counts differ");
        return Collections.unmodifiableMap(nodes);
    }
    private static JSONObject metadata(JSONObject dom)throws Exception{
        JSONObject value=new JSONObject(WebDomCanonical.canonical(dom));
        value.remove("nodes");value.remove("action_region_observations");value.remove("clipping_context_observations");return value;
    }
    private static JSONObject without(JSONObject value,String key)throws Exception{
        JSONObject copy=new JSONObject(WebDomCanonical.canonical(value));copy.remove(key);return copy;
    }
    /** Clip observations are retained as raw data; they grant no hidden-content exemption. */
    private static void checkClipObservationCrossReferences(JSONObject dom)throws Exception{
        JSONObject clip=dom.getJSONObject("clipping_context_observations");
        need("hepta.raw-clip-context-observations.v1".equals(text(clip,"schema"))
                &&Boolean.FALSE.equals(clip.get("fully_clipped_inferred"))
                &&Boolean.FALSE.equals(clip.get("closed_shadow_contents_inspected"))
                &&Boolean.FALSE.equals(clip.get("grants_action_authority"))&&clip.get("complete") instanceof Boolean,
                "raw clip observations must not assert invisible content or authority");
        JSONArray contexts=clip.getJSONArray("style_contexts"),region=dom.getJSONObject("action_region_observations").getJSONArray("style_contexts");
        need(contexts.length()<=128,"bounded raw clip observations");Map<String,JSONObject> originals=new LinkedHashMap<String,JSONObject>();
        for(int i=0;i<region.length();i++){JSONObject row=region.getJSONObject(i);originals.put(text(row,"path"),row);}
        Set<String> seen=new LinkedHashSet<String>();
        for(int i=0;i<contexts.length();i++){
            JSONObject row=contexts.getJSONObject(i);String path=text(row,"path");need(seen.add(path),"unique raw clip style path");
            if(originals.containsKey(path))need(WebDomCanonical.same(row,originals.get(path)),"shared ancestor CSS changed within the fixed observation");
        }
    }
    private static void diff(Object before,Object after,String pointer,JSONArray out,int depth)throws Exception{
        need(depth<=64,"bounded difference depth");if(WebDomCanonical.same(before,after))return;
        if(before instanceof JSONObject&&after instanceof JSONObject){
            JSONObject a=(JSONObject)before,b=(JSONObject)after;Set<String> keys=new java.util.TreeSet<String>();
            Iterator<String> it=a.keys();while(it.hasNext())keys.add(it.next());it=b.keys();while(it.hasNext())keys.add(it.next());
            for(String key:keys){
                String path=pointer+"/"+key.replace("~","~0").replace("/","~1");
                if(!a.has(key)||!b.has(key))addDifference(out,path,a.has(key)?a.get(key):JSONObject.NULL,b.has(key)?b.get(key):JSONObject.NULL,
                        !a.has(key)?"add":"remove");
                else diff(a.get(key),b.get(key),path,out,depth+1);
            }return;
        }
        if(before instanceof JSONArray&&after instanceof JSONArray){
            JSONArray a=(JSONArray)before,b=(JSONArray)after;int length=Math.max(a.length(),b.length());
            for(int i=0;i<length;i++){
                if(i>=a.length()||i>=b.length())addDifference(out,pointer+"/"+i,i<a.length()?a.get(i):JSONObject.NULL,i<b.length()?b.get(i):JSONObject.NULL,
                        i>=a.length()?"add":"remove");
                else diff(a.get(i),b.get(i),pointer+"/"+i,out,depth+1);
            }return;
        }
        addDifference(out,pointer,before,after,"replace");
    }
    private static void addDifference(JSONArray out,String pointer,Object before,Object after,String operation)throws Exception{
        need(out.length()<MAX_DIFFERENCES,"complete JSON difference list exceeds bounded policy");
        need(bytes(WebDomCanonical.canonical(before))<=16384&&bytes(WebDomCanonical.canonical(after))<=16384,"individual raw difference exceeds bounded policy");
        out.put(new JSONObject().put("json_pointer",pointer).put("operation",operation)
                .put("before",before==null?JSONObject.NULL:before).put("after",after==null?JSONObject.NULL:after));
    }
    public static double[] rect(JSONArray array)throws Exception{
        need(array.length()==4,"four observed rectangle coordinates");double[] out=new double[4];
        for(int i=0;i<4;i++){Object value=array.get(i);need(value instanceof Number,"numeric observed rectangle");
            out[i]=((Number)value).doubleValue();need(Double.isFinite(out[i])&&Math.abs(out[i])<=100000000,"finite bounded rectangle");}
        need(out[2]>=out[0]&&out[3]>=out[1],"ordered observed rectangle");return out;
    }
    private static String text(JSONObject object,String key)throws Exception{
        Object value=object.get(key);need(value instanceof String&&((String)value).length()<=4096,"bounded raw string: "+key);return (String)value;
    }
    private static String parent(String path){int i=path.lastIndexOf('/');return i<0?null:path.substring(0,i);}
    private static int bytes(String raw){return raw.getBytes(StandardCharsets.UTF_8).length;}
    private static void need(boolean value,String message){if(!value)throw new IllegalArgumentException(message);}
}

package org.trillionnium.hepta.webprotocol;

import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.local.web.WebShoppingGoal;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Arrays;
import java.util.regex.Pattern;

/**
 * One immutable mainland-Mi policy, selected only from a recognized shopping
 * contract. It is not appended to the existing Csair origin predicate.
 * It classifies public main-frame routes; DOM/native-action and product-result
 * proof are separate and cannot be obtained by matching a numeric URL.
 */
public final class WebSitePolicy {
    public static final String SCHEMA="hepta.web-site-policy.v2";
    public static final String ID="mi_cn_ax3000t_read_v2";
    public static final String ORIGIN="https://www.mi.com";
    public static final String INITIAL_URL=ORIGIN+"/shop/search?keyword=AX3000T";
    private static final Pattern DETAIL_QUERY=Pattern.compile("product_id=([1-9][0-9]{0,19})&cfrom=search");
    public enum Route { INITIAL_PUBLIC_SEARCH, PUBLIC_DETAIL_CANDIDATE, DENIED }
    public final String id=ID,goalKind=WebShoppingGoal.KIND,initialUrl=INITIAL_URL,origin=ORIGIN,sha256;
    private final String immutableEvidence;
    private WebSitePolicy()throws Exception {
        JSONObject value=new JSONObject().put("schema",SCHEMA).put("site_policy_id",ID)
                .put("goal_kind",WebShoppingGoal.KIND).put("origin",ORIGIN).put("initial_url",INITIAL_URL)
                .put("route_policy","actual_search_card_observed_shop_buy_v2")
                .put("controlled_blank_requires_exact_one_shot_armed_link",true)
                .put("new_visible_window_or_external_navigation_allowed",false)
                .put("auxiliary_network_blocked_url_interceptor_allowed",true)
                .put("main_frame_only",true).put("regional_redirect_allowed",false)
                .put("external_app_launch_allowed",false).put("model_supplied_url_allowed",false)
                .put("model_supplied_javascript_allowed",false)
                .put("denied_navigation_categories",new JSONArray(Arrays.asList(
                    "account","login","cart","order","payment","coupon_claim","foreign_origin","regional_store")));
        immutableEvidence=WebEvidenceBinding.canonical(value);sha256=WebEvidenceBinding.sha256(value);
    }
    public static WebSitePolicy forShopping(WebShoppingGoal goal)throws Exception {
        if(goal==null)throw new IllegalArgumentException("recognized compiled shopping contract required");
        java.util.Map<String,Object> contract=goal.contract();
        if(!ID.equals(contract.get("site_policy_id"))||!WebShoppingGoal.KIND.equals(contract.get("kind"))
                ||!"AX3000T".equals(contract.get("model_term"))
                ||!WebShoppingGoal.contractHash(contract).equals(goal.contractSha256))
            throw new IllegalArgumentException("immutable shopping contract changed");
        return new WebSitePolicy();
    }
    /** Fixed display-0 manual diagnostic policy only; no OWNER or lease is fabricated. */
    public static WebSitePolicy forExplicitDiagnostic()throws Exception{return new WebSitePolicy();}
    public JSONObject evidence()throws Exception{return new JSONObject(immutableEvidence);}
    public boolean allowsMainFrame(String raw){return classify(raw)!=Route.DENIED;}
    public Route classify(String raw) {
        if(raw==null||raw.length()==0||raw.length()>4096)return Route.DENIED;
        try{
            URI uri=new URI(raw);
            if(uri.isOpaque()||!"https".equals(uri.getScheme())||!"www.mi.com".equals(uri.getRawAuthority())
                    ||!"www.mi.com".equals(uri.getHost())||uri.getRawUserInfo()!=null||uri.getPort()!=-1
                    ||uri.getRawFragment()!=null)return Route.DENIED;
            if(INITIAL_URL.equals(raw))return Route.INITIAL_PUBLIC_SEARCH;
            String query=uri.getRawQuery();
            if("/shop/buy".equals(uri.getRawPath())&&query!=null&&DETAIL_QUERY.matcher(query).matches())
                return Route.PUBLIC_DETAIL_CANDIDATE;
        }catch(URISyntaxException invalid){return Route.DENIED;}
        return Route.DENIED;
    }
    /** Checks both recorded raw and browser-resolved href; it does not navigate. */
    public String observedProductLink(String committed,String hrefRaw,String hrefResolved,String target) {
        if(classify(committed)!=Route.INITIAL_PUBLIC_SEARCH||hrefRaw==null||hrefResolved==null
                ||hrefRaw.length()==0||hrefRaw.length()>4096
                ||!(target==null||target.length()==0||"_self".equals(target)||"_blank".equals(target)))return null;
        try{
            URI raw=new URI(hrefRaw);String resolved=new URI(committed).resolve(raw).toString();
            if(!resolved.equals(hrefResolved)||classify(resolved)!=Route.PUBLIC_DETAIL_CANDIDATE)return null;
            return resolved;
        }catch(URISyntaxException invalid){return null;}
    }
    public String candidateProductId(String raw) {
        if(classify(raw)!=Route.PUBLIC_DETAIL_CANDIDATE)return null;
        try{java.util.regex.Matcher m=DETAIL_QUERY.matcher(new URI(raw).getRawQuery());return m.matches()?m.group(1):null;}
        catch(URISyntaxException invalid){return null;}
    }
}

package org.trillionnium.hepta.local.web;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure-Java bounded original-user intent for one official public product lookup.
 * No JSON, Android or Binder dependency is introduced into TaskAuthorization.
 * Recognition derives an immutable data contract, never rewrites OWNER and never
 * grants a tool. Original authority and current single-helper selection are
 * separate, mandatory controller/helper gates.
 */
public final class WebShoppingGoal {
    public static final String SCHEMA="hepta.web-shopping-goal.v2";
    public static final String KIND="mi_public_product";
    public static final String SITE_POLICY_ID="mi_cn_ax3000t_read_v2";
    public static final String MODEL_TERM="AX3000T";
    public static final String DISPLAY_MODEL="Xiaomi 路由器 AX3000T";
    public static final String LEGACY_EXPLICIT_OWNER=
            "在小米中国官方商城只读查询 Xiaomi 路由器 AX3000T 的单件配置，核对 Wi-Fi 6、3000M级、4个自适应WAN/LAN口，告诉我该配置当前公开的人民币价格，以及是否为起价、划线对比价、券后价或附带条件。不登录、不领券、不加购物车、不下单、不付款。";
    public static final Set<String> TOOL_CEILING=Collections.unmodifiableSet(
            new TreeSet<String>(Arrays.asList("open","click","back","scroll","wait","done")));
    private static final Pattern MODEL_FIRST=Pattern.compile(
            "^(?:请)?(?:帮我)?(?:查一下|查下|查询|查查|查看)(?:小米|Xiaomi)[ ]?(?:路由器[ ]?)?"
            +"(AX3000T)(?:的)?(?:官网|官方商城|中国官方商城)(?:售价|价格)[。？?]?$",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern STORE_FIRST=Pattern.compile(
            "^(?:请)?(?:帮我)?(?:查一下|查下|查询|查查|查看)(?:小米|Xiaomi)(?:中国)?(?:官网|官方商城)"
            +"[ ]?(?:路由器[ ]?)?(AX3000T)(?:的)?(?:售价|价格)[。？?]?$",
            Pattern.CASE_INSENSITIVE);
    private static final Set<String> FORBIDDEN=Collections.unmodifiableSet(new TreeSet<String>(
            Arrays.asList("login","register","consent_grant","coupon_claim","cart","order","payment",
                    "account_change","permission_change","arbitrary_app","arbitrary_url","arbitrary_js")));
    public final String owner,ownerSha256,contractSha256;
    public final String contractSchema=SCHEMA,providerSelection=KIND,recognition;
    public final int productStartUtf16,productEndUtf16;
    public final boolean naturalReadOnlyIntent,specificationsRequested,singleUnitRequested;
    private final Map<String,Object> immutableContract;
    private final String canonicalContract;

    private WebShoppingGoal(String raw,int start,int end,boolean natural) {
        owner=raw;ownerSha256=hash(raw);productStartUtf16=start;productEndUtf16=end;
        naturalReadOnlyIntent=natural;specificationsRequested=!natural;singleUnitRequested=!natural;
        recognition=natural?"bounded_natural_official_product_price.v1":"legacy_complete_explicit_product_read.v1";
        Map<String,Object> c=new LinkedHashMap<String,Object>();
        c.put("schema",SCHEMA);c.put("kind",KIND);c.put("owner_sha256",ownerSha256);
        c.put("owner_span_utf16",list(Integer.valueOf(0),Integer.valueOf(raw.length())));
        c.put("model_span_utf16",list(Integer.valueOf(start),Integer.valueOf(end)));c.put("model_term",MODEL_TERM);
        c.put("site_policy_id",SITE_POLICY_ID);c.put("market","mainland_china");
        c.put("purpose","public_product_price_information");c.put("natural_language_intent",Boolean.valueOf(natural));
        c.put("single_unit_requested",Boolean.valueOf(singleUnitRequested));
        c.put("specifications_requested",Boolean.valueOf(specificationsRequested));
        c.put("required_specifications",specificationsRequested?list("Wi-Fi 6","3000M级","4个自适应WAN/LAN口"):list());
        c.put("tool_ceiling",Collections.unmodifiableList(new ArrayList<String>(TOOL_CEILING)));
        c.put("forbidden_operations",Collections.unmodifiableList(new ArrayList<String>(FORBIDDEN)));
        c.put("preserve_price_conditions",Boolean.TRUE);c.put("visible_currency_required",Boolean.TRUE);
        c.put("same_product_context_required",Boolean.TRUE);c.put("navigation_from_observed_link_required",Boolean.TRUE);
        c.put("exact_variant_not_inferred",Boolean.TRUE);c.put("search_card_is_not_detail_result",Boolean.TRUE);
        immutableContract=Collections.unmodifiableMap(c);canonicalContract=canonical(c);contractSha256=hash(canonicalContract);
    }
    public static WebShoppingGoal parse(String raw) {
        if(!valid(raw))return null;
        if(LEGACY_EXPLICIT_OWNER.equals(raw)){
            int start=raw.indexOf(MODEL_TERM);return new WebShoppingGoal(raw,start,start+MODEL_TERM.length(),false);
        }
        Matcher match=MODEL_FIRST.matcher(raw);
        if(!match.matches()){match=STORE_FIRST.matcher(raw);if(!match.matches())return null;}
        return new WebShoppingGoal(raw,match.start(1),match.end(1),true);
    }
    /**
     * Lets the UI refuse/clarify an unsupported shopping-like OWNER instead of
     * silently falling back to generic application operation.
     * A true result is never authority and is not a successful parse.
     */
    public static boolean resemblesSupportedIntent(String raw) {
        if(!valid(raw))return false;
        return Pattern.compile("AX3000T",Pattern.CASE_INSENSITIVE).matcher(raw).find()
                &&(raw.contains("小米")||Pattern.compile("Xiaomi",Pattern.CASE_INSENSITIVE).matcher(raw).find())
                &&(raw.contains("官网")||raw.contains("官方商城"))
                &&(raw.contains("价")||raw.contains("购买")||raw.contains("下单"));
    }
    /** Intent only; original authority, current UI selection and lease are still required. */
    public boolean allowsInitialOfficialPage(){return true;}
    public Set<String> toolCeiling(){return TOOL_CEILING;}
    public Map<String,Object> contract(){return immutableContract;}
    public String canonicalContract(){return canonicalContract;}
    public static String contractHash(Map<String,Object> value){return hash(canonical(value));}
    public Map<String,Object> evidence() {
        Map<String,Object> observed=new LinkedHashMap<String,Object>();
        for(String key:Arrays.asList("product_id","selected_variant","quantity","price_raw","amount_decimal","currency","price_kind","committed_url"))
            observed.put(key,null);
        observed.put("product_result_verified",Boolean.FALSE);
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("schema",SCHEMA);out.put("kind",KIND);out.put("original_owner",owner);
        out.put("owner_sha256",ownerSha256);out.put("contract_sha256",contractSha256);out.put("contract",immutableContract);
        out.put("recognition",recognition);out.put("observed",Collections.unmodifiableMap(observed));
        out.put("original_owner_rewritten",Boolean.FALSE);out.put("task_authorization_compiled",Boolean.FALSE);
        out.put("grants_tool_authority",Boolean.FALSE);out.put("query_executed",Boolean.FALSE);out.put("business_verified",Boolean.FALSE);
        return Collections.unmodifiableMap(out);
    }
    private static List<Object> list(Object... values){return Collections.unmodifiableList(Arrays.asList(values));}
    private static boolean valid(String raw) {
        if(raw==null||raw.length()==0||raw.getBytes(StandardCharsets.UTF_8).length>1600)return false;
        for(int i=0;i<raw.length();i++){
            char c=raw.charAt(i);
            if(Character.isHighSurrogate(c)){if(++i>=raw.length()||!Character.isLowSurrogate(raw.charAt(i)))return false;}
            else if(Character.isLowSurrogate(c)||Character.isISOControl(c))return false;
        }
        return true;
    }
    /** Canonical JSON data encoding: UTF16-sorted object keys, ordered arrays, no floats. */
    private static String canonical(Object value) {
        if(value==null)return "null";
        if(value instanceof Boolean||value instanceof Integer||value instanceof Long)return value.toString();
        if(value instanceof String){
            String s=(String)value;StringBuilder out=new StringBuilder("\"");
            for(int i=0;i<s.length();i++){
                char c=s.charAt(i);
                if(Character.isHighSurrogate(c)){
                    if(i+1>=s.length()||!Character.isLowSurrogate(s.charAt(i+1)))throw new IllegalArgumentException("invalid Unicode");
                    out.append(c).append(s.charAt(++i));continue;
                }
                if(Character.isLowSurrogate(c))throw new IllegalArgumentException("invalid Unicode");
                if(c=='\"'||c=='\\')out.append('\\').append(c);
                else if(c<0x20){String h=Integer.toHexString(c);out.append("\\u");for(int n=h.length();n<4;n++)out.append('0');out.append(h);}
                else out.append(c);
            }
            return out.append('\"').toString();
        }
        if(value instanceof List){
            StringBuilder out=new StringBuilder("[");List<?> a=(List<?>)value;
            for(int i=0;i<a.size();i++){if(i>0)out.append(',');out.append(canonical(a.get(i)));}return out.append(']').toString();
        }
        if(value instanceof Map){
            Map<?,?> map=(Map<?,?>)value;TreeSet<String> keys=new TreeSet<String>();
            for(Object key:map.keySet()){if(!(key instanceof String))throw new IllegalArgumentException("string map key required");keys.add((String)key);}
            StringBuilder out=new StringBuilder("{");int index=0;
            for(String key:keys){if(index++>0)out.append(',');out.append(canonical(key)).append(':').append(canonical(map.get(key)));}
            return out.append('}').toString();
        }
        throw new IllegalArgumentException("noncanonical contract type");
    }
    private static String hash(String raw) {
        try{
            byte[] bytes=MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder out=new StringBuilder(64);char[] hex="0123456789abcdef".toCharArray();
            for(byte b:bytes)out.append(hex[(b>>>4)&15]).append(hex[b&15]);return out.toString();
        }catch(NoSuchAlgorithmException impossible){throw new IllegalStateException("SHA-256 unavailable",impossible);}
    }
}

package org.trillionnium.hepta.webprotocol;

import org.json.JSONObject;

/**
 * Typed one-shot link arm derived from the helper's last successful fresh capture.
 * A request supplies identities/hashes/path, never a URL or page script.
 * An ARM receipt is not a click, navigation completion, or business result.
 */
public final class WebObservedNavigation {
    public static final String ARM_SCHEMA="hepta.web-helper.observed-link-arm.v1";
    public static final String NAV_SCHEMA="hepta.web-helper.observed-link-navigation.v1";
    public static final String CAPTURE_SCHEMA="hepta.owned-webview-origin-dom.v2";
    public static final long SOURCE_MAX_AGE_MS=2500,ARM_BUDGET_MS=1500;
    private WebObservedNavigation(){}
    public static void requireRequest(JSONObject request)throws Exception{
        java.util.Set<String> keys=new java.util.TreeSet<String>();
        java.util.Iterator<String> it=request.keys();while(it.hasNext())keys.add(it.next());
        need(keys.equals(WebEvidenceProtocol.requestKeys(WebEvidenceProtocol.ARM_OBSERVED_LINK))
                &&WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.ARM_OBSERVED_LINK).equals(text(request,"schema")),
                "exact observed-link request required");
        need(WebEvidenceProtocol.hex32(text(request,"task_id"))
                &&WebEvidenceProtocol.hex64(text(request,"controller_session_nonce"))
                &&WebEvidenceProtocol.hex64(text(request,"request_nonce"))
                &&WebEvidenceProtocol.uuid(text(request,"expected_webview_instance"))
                &&integer(request,"expected_navigation_epoch")>=0
                &&WebEvidenceProtocol.hex64(text(request,"source_capture_challenge"))
                &&WebEvidenceProtocol.hex64(text(request,"source_dom_sha256"))
                &&WebEvidenceProtocol.hex64(text(request,"source_stability_sha256"))
                &&text(request,"anchor_dom_path").matches("0(?:/[0-9]{1,5}){0,32}")
                &&WebEvidenceProtocol.hex32(text(request,"model_run_id")),
                "observed-link request identity/hash/path shape");
        need(integer(request,"deadline_elapsed_ms")>0,"positive observed-link request deadline");
    }
    public static JSONObject arm(JSONObject request,JSONObject binding,JSONObject capture,long now)throws Exception{
        requireRequest(request);WebTaskPurpose purpose=WebTaskPurpose.requireBinding(binding);
        need(purpose.shopping!=null&&WebMiActionRegion.POLICY.equals(purpose.sitePolicyId),
                "only the compiled public shopping purpose can arm a product link");
        need(text(binding,"task_id").equals(text(request,"task_id"))
                &&text(binding,"controller_session_nonce").equals(text(request,"controller_session_nonce"))
                &&WebEvidenceBinding.canonical(binding).equals(WebEvidenceBinding.canonical(capture.getJSONObject("binding"))),
                "last successful capture belongs to another lease");
        need(CAPTURE_SCHEMA.equals(text(capture,"schema"))
                &&Boolean.FALSE.equals(capture.get("business_verified"))
                &&Boolean.FALSE.equals(capture.get("truncated"))
                &&integer(capture,"display_id")>0&&integer(capture,"actual_window_id")>=0
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(capture,"helper_package")),
                "current formal wire-v4 capture required");
        need(text(request,"source_capture_challenge").equals(text(capture,"challenge"))
                &&text(request,"expected_webview_instance").equals(text(capture,"webview_instance"))
                &&integer(request,"expected_navigation_epoch")==integer(capture,"navigation_epoch")
                &&text(request,"source_dom_sha256").equals(text(capture,"dom_sha256")),
                "fresh capture identity changed");
        String before=text(capture,"before_dom_raw_utf8"),after=text(capture,"dom_raw_utf8");
        WebDomStability.Result stability=WebDomStability.verify(before,after,purpose.sitePolicyId,capture.getJSONObject("dom_stability"));
        need(stability.region!=null&&stability.permitsActionTargetPath(text(request,"anchor_dom_path"))
                &&stability.afterRawSha256.equals(text(request,"source_dom_sha256"))
                &&stability.beforeRawSha256.equals(text(capture,"before_dom_sha256"))
                &&WebDomCanonical.sha256(stability.evidence()).equals(text(request,"source_stability_sha256"))
                &&WebDomCanonical.sha256(stability.evidence()).equals(text(capture,"dom_stability_sha256")),
                "only the actual stable region anchor can be armed");
        WebMiActionRegion region=stability.region;
        need("_blank".equals(region.linkTarget),"this observed-link arm handles the actual new-window card link only");
        JSONObject geometry=capture.getJSONObject("capture_geometry");
        need("hepta.webview-geometry-bracket.v2".equals(text(geometry,"schema"))
                &&geometry.getJSONArray("samples").length()==4
                &&Boolean.TRUE.equals(geometry.get("native_samples_equal"))
                &&Boolean.TRUE.equals(geometry.get("ui_thread_bracket"))
                &&stability.comparisonScope.equals(text(geometry,"dom_comparison_scope"))
                &&Boolean.valueOf(stability.rawEqual).equals(geometry.get("dom_equal_across_visual_callback")),
                "complete actual native geometry bracket is required");
        long ended=integer(capture,"ended_elapsed_ms"),started=integer(capture,"started_elapsed_ms");
        JSONObject bg=binding.getJSONObject("background");long expires=integer(bg,"expires_elapsed_ms");
        long requestDeadline=integer(request,"deadline_elapsed_ms");
        need(now>=0&&now<=Long.MAX_VALUE-ARM_BUDGET_MS&&started<=ended&&ended<=now&&now-ended<=SOURCE_MAX_AGE_MS
                &&requestDeadline>now&&requestDeadline-now<=WebEvidenceProtocol.MAX_RPC_FUTURE_MS&&requestDeadline<=expires,
                "fresh capture/arm/lease deadline invalid");
