        if(!m.matches())throw new IllegalArgumentException("original XML bounds syntax");
        return new Rect(Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)),Integer.parseInt(m.group(3)),Integer.parseInt(m.group(4)));
