    static void xmlNode(Element e,String path,String parent,List<PhoneObservation.Node> out)throws Exception{
        xmlNodes++;Rect r=bounds(e.getAttribute("bounds"));String text=e.getAttribute("text"),desc=e.getAttribute("content-desc");
        boolean useful=r.left<r.right&&r.top<r.bottom&&(flag(e,"clickable")||flag(e,"scrollable")||!text.isEmpty()||!desc.isEmpty());
        if(useful){
            String sig=sha("SYNTHETIC-NATIVE-SIGNATURE\n"+path+"\n"+e.getAttribute("class")+"\n"+text+"\n"+desc+"\n"+e.getAttribute("bounds"));
            out.add(new PhoneObservation.Node("n"+out.size(),e.getAttribute("package"),e.getAttribute("class"),e.getAttribute("resource-id"),
                    text,desc,r,flag(e,"clickable"),false,flag(e,"scrollable"),flag(e,"enabled"),flag(e,"focused"),flag(e,"password"),
                    ObservedChildText.notApplicable(),ObservedScrollActions.observed(Collections.<String>emptyList()),
                    ObservedImeEnter.UNKNOWN,null,false,sig,path,parent));
        }
        int child=0;NodeList kids=e.getChildNodes();for(int i=0;i<kids.getLength();i++)if(kids.item(i) instanceof Element){
            Element next=(Element)kids.item(i);if(!"node".equals(next.getTagName()))throw new IllegalArgumentException("unknown AX element");
            xmlNode(next,path+"/"+child++,e.getAttribute("class"),out);
        }
    }
    static void loadAx(String path)throws Exception{
        byte[] raw=Files.readAllBytes(Paths.get(path));need(raw.length==211683&&AX_SHA.equals(WebEvidenceJson.sha(raw)),"exact original AX bytes/hash");
        DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true);
        f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);
        f.setFeature("http://xml.org/sax/features/external-general-entities",false);
        f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);
        f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");
        f.setXIncludeAware(false);f.setExpandEntityReferences(false);
        Document doc=f.newDocumentBuilder().parse(new ByteArrayInputStream(raw));Element hierarchy=doc.getDocumentElement();
        need("hierarchy".equals(hierarchy.getTagName()),"actual hierarchy root");ArrayList<PhoneObservation.Node> out=new ArrayList<PhoneObservation.Node>();
        int root=0;NodeList kids=hierarchy.getChildNodes();for(int i=0;i<kids.getLength();i++)if(kids.item(i) instanceof Element)
            xmlNode((Element)kids.item(i),Integer.toString(root++),"",out);
        need(root==1&&xmlNodes==566&&out.size()==391,"full archived tree and explicit positive/useful synthetic projection");
        originalNodes=Collections.unmodifiableList(out);
    }
