package org.trillionnium.hepta.local;
import android.os.SystemClock;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;
import org.json.JSONObject;
import org.trillionnium.hepta.webprotocol.*;
/** Exact main Client methods. Only the Binder/clock boundary below is a test double. */
final class WebEvidenceClientArmProjection {
    interface Guard {void requireCurrent(boolean cleanup)throws Exception;boolean cancelled();}
    static final class TestGuard implements Guard {
        boolean cancel;
        public void requireCurrent(boolean cleanup){if(cancel)throw new IllegalStateException("synthetic cancelled guard");}
        public boolean cancelled(){return cancel;}
    }
    private final String bindingRaw,bindingSha;
    private final TestGuard guard=new TestGuard();
    private final Set<String> armedTargets=new HashSet<String>(),armedModelRuns=new HashSet<String>();
    private WebEvidenceReceipt lastCaptured;
    private String instance;
    private long epoch;
    private boolean firstCapture=false;
    int armCalls,captureCalls;
    boolean failArm,expireArmOnReturn;
    JSONObject lastArmRequest;
    WebEvidenceClientArmProjection(JSONObject binding,WebEvidenceReceipt source)throws Exception{
        bindingRaw=WebEvidenceBinding.canonical(binding);bindingSha=WebEvidenceBinding.sha256(binding);
        lastCaptured=source;instance=source.instance;epoch=source.epoch;
    }
    void cancel(){guard.cancel=true;}
    int attemptedTargetCount(){return armedTargets.size();}
    int attemptedRunCount(){return armedModelRuns.size();}
    synchronized WebEvidenceReceipt capture(long callerDeadline)throws Exception{
        guard.requireCurrent(false);
        JSONObject request=common(WebEvidenceProtocol.CAPTURE,Math.min(callerDeadline,expiry()));
        request.put("expected_webview_instance",firstCapture?JSONObject.NULL:instance)
                .put("expected_navigation_epoch",firstCapture?JSONObject.NULL:epoch);
        // A dispatched failed read is never retried under the same nonce or null-first-capture capability.
        firstCapture=false;
        lastCaptured=null;
        WebEvidenceReceipt result=call(WebEvidenceProtocol.CAPTURE,request);
        need(instance!=null&&instance.equals(result.instance),"helper WebView instance changed");
        need(result.epoch>=epoch,"navigation epoch went backwards");
        epoch=result.epoch;if("captured".equals(result.status))lastCaptured=result;return result;
    }
    synchronized WebEvidenceReceipt armObservedLink(WebEvidenceReceipt source,String anchorPath,String modelRun,long callerDeadline)throws Exception{
        guard.requireCurrent(false);need(!guard.cancelled(),"task cancelled before observed-link ARM");
        need(source!=null&&source==lastCaptured&&"captured".equals(source.status)&&source.stability()!=null
                &&bindingSha.equals(source.bindingSha)&&instance!=null&&instance.equals(source.instance)&&epoch==source.epoch,
                "only this client's last exact successful fresh capture may arm a link");
        need(WebEvidenceProtocol.hex32(modelRun)&&source.stability().region!=null
                &&source.stability().permitsActionTargetPath(anchorPath)
                &&"_blank".equals(source.stability().region.linkTarget),
                "actual selected new-window anchor and model run required");
        long now=SystemClock.elapsedRealtime();
        need(source.ended<=now&&now-source.ended<=WebObservedNavigation.SOURCE_MAX_AGE_MS,
                "source capture expired before ARM");
        JSONObject request=common(WebEvidenceProtocol.ARM_OBSERVED_LINK,Math.min(callerDeadline,expiry()));
        request.put("expected_webview_instance",instance).put("expected_navigation_epoch",epoch)
                .put("source_capture_challenge",source.callback().getString("request_nonce"))
                .put("source_dom_sha256",source.domSha)
                .put("source_stability_sha256",WebDomCanonical.sha256(source.stability().evidence()))
                .put("anchor_dom_path",anchorPath).put("model_run_id",modelRun);
        WebObservedNavigation.requireRequest(request);
        String target=instance+"\n"+epoch+"\n"+anchorPath;
        // The same lease/instance/epoch/anchor and model run are never re-armed,
        // including after a failed callback, timeout or a later fresh capture.
        need(armedTargets.size()<WebEvidenceProtocol.MAX_REQUESTS_PER_SESSION
                &&armedModelRuns.size()<WebEvidenceProtocol.MAX_REQUESTS_PER_SESSION
                &&armedTargets.add(target)&&armedModelRuns.add(modelRun),
                "observed-link target or model run already attempted");
        WebEvidenceReceipt result=call(WebEvidenceProtocol.ARM_OBSERVED_LINK,request,source);
        need("armed".equals(result.status)&&result.arm()!=null&&instance.equals(result.instance)&&epoch==result.epoch
                &&SystemClock.elapsedRealtime()<=WebEvidenceJson.number(result.arm(),"expires_elapsed_ms"),
                "observed-link ARM expired or changed its page");
        return result;
    }
    private long expiry()throws Exception{return WebEvidenceJson.number(WebEvidenceJson.parseEvidence(bindingRaw,WebEvidenceProtocol.MAX_REQUEST_BYTES).getJSONObject("background"),"expires_elapsed_ms");}
    private JSONObject common(int code,long deadline)throws Exception{
        JSONObject binding=WebEvidenceJson.parseEvidence(bindingRaw,WebEvidenceProtocol.MAX_REQUEST_BYTES);
        long now=SystemClock.elapsedRealtime(),limit=Math.min(deadline,now+WebEvidenceProtocol.MAX_RPC_FUTURE_MS);
        need(limit>now,"RPC deadline exhausted");
        String nonce=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");
        return new JSONObject().put("schema",WebEvidenceProtocol.requestSchema(code)).put("request_nonce",nonce)
                .put("task_id",binding.getString("task_id")).put("controller_session_nonce",binding.getString("controller_session_nonce"))
                .put("deadline_elapsed_ms",limit);
    }

    private WebEvidenceReceipt call(int code,JSONObject request)throws Exception{
        if(code!=WebEvidenceProtocol.CAPTURE)throw new AssertionError("unexpected transport boundary");
        captureCalls++;long sent=SystemClock.elapsedRealtime();
        WebWire4ConsumerHostTest.CaptureFixture f=new WebWire4ConsumerHostTest.CaptureFixture(sent-1100L);
        f.capture.put("challenge",request.get("request_nonce"));
        JSONObject evidence=WebWire4ConsumerHostTest.envelope(f.binding,request,"controller_evidence_capture").put("capture",f.capture);
        byte[] raw=evidence.toString().getBytes(StandardCharsets.UTF_8);long received=f.capture.getLong("ended_elapsed_ms")+10;
        JSONObject cb=WebWire4ConsumerHostTest.callback(code,"captured",request,f.binding,raw);
        WebEvidenceReceipt out=WebEvidenceReceipt.verify(code,request.toString(),f.binding,cb.toString(),raw,10123,sent,received);
        SystemClock.setForTest(received);return out;
    }
    private WebEvidenceReceipt call(int code,JSONObject request,WebEvidenceReceipt exactSource)throws Exception{
        if(code!=WebEvidenceProtocol.ARM_OBSERVED_LINK)throw new AssertionError("unexpected ARM transport code");
        armCalls++;lastArmRequest=new JSONObject(request.toString());
        if(failArm)throw new IOException("synthetic unknown transport outcome; no retry permitted");
        long sent=SystemClock.elapsedRealtime();JSONObject binding=new JSONObject(bindingRaw),source=exactSource.capture();
        JSONObject arm=WebObservedNavigation.arm(request,binding,source,sent+1);
        JSONObject evidence=WebWire4ConsumerHostTest.envelope(binding,request,"controller_observed_link_arm").put("arm",arm);
        byte[] raw=evidence.toString().getBytes(StandardCharsets.UTF_8);
        JSONObject cb=WebWire4ConsumerHostTest.callback(code,"armed",request,binding,raw);
        WebEvidenceReceipt out=WebEvidenceReceipt.verify(code,request.toString(),binding,cb.toString(),raw,10123,sent,sent+2,source);
        SystemClock.setForTest(expireArmOnReturn?arm.getLong("expires_elapsed_ms")+1:sent+2);return out;
    }
    private static void need(boolean ok,String why){WebEvidenceJson.need(ok,why);}
}

