/**
 * Exercises byte-identical production Client/Session method projections.
 * Binder, provider, journal, clock and native-token creation are explicit doubles.
 * This proves neither Android AccessibilityNodeInfo.refresh nor a real click.
 */
public final class WebArmDispatchHostTest {
    interface Checked{void run()throws Exception;}
    static int cases,assertions;
    static final ArrayList<String> names=new ArrayList<String>();
    static final String RUN=WebWire4ConsumerHostTest.rep('9',32);
    static void need(boolean value,String why){assertions++;if(!value)throw new AssertionError(why);}
    static void rejects(Checked action)throws Exception{
        boolean rejected=false;try{action.run();}catch(Exception expected){rejected=true;}need(rejected,"expected fail-closed action");
    }
    static void run(String name,Checked action)throws Exception{action.run();cases++;names.add(name);}
    static ActionDecision click(PhoneObservation frame,WebRegionNativeBridge bridge)throws Exception{
        // The actual parser requires label before ID. JSONObject's key ordering
        // is deliberately not used as a substitute for that model-output grammar.
        String raw="{\"action\":\"click\",\"observation_id\":"+JSONObject.quote(frame.id)
                +",\"package\":"+JSONObject.quote(frame.packageName)
                +",\"node_label\":"+JSONObject.quote(ObservedTargetLabels.project(bridge.anchor.label()))
                +",\"node_id\":"+JSONObject.quote(bridge.anchor.id)+"}";
        return ActionDecision.parse(raw);
    }
    static final class Fixture{
        final WebWire4ConsumerHostTest.CaptureFixture capture;
        final WebEvidenceReceipt source;
        final PhoneObservation frame;
        final WebRegionNativeBridge bridge;
        final JSONObject arm;
        final ActionDecision action;
        final WebFlightSessionArmProjection session;
        Fixture()throws Exception{
            capture=new WebWire4ConsumerHostTest.CaptureFixture(0);source=capture.receipt();
            frame=WebWire4ConsumerHostTest.frame(WebWire4ConsumerHostTest.originalNodes,capture.binding,
                    WebWire4ConsumerHostTest.selection(capture.binding),capture.binding.getString("owner_sha256"),
                    WebWire4ConsumerHostTest.rep('3',32),1160,false,false);
            bridge=WebRegionNativeBridge.bind(frame,source);need(bridge!=null,"actual-AX synthetic identity source bridge");
            action=click(frame,bridge);JSONObject req=WebWire4SyntheticFactory.request(source.capture());
            arm=WebObservedNavigation.arm(req,capture.binding,source.capture(),1170L);
            SystemClock.setForTest(1180L);
            session=new WebFlightSessionArmProjection(capture.binding,frame,bridge,action,RUN,arm,source);
        }
        void nativeToken(long at)throws Exception{session.injectSyntheticNativeToken(action,RUN,frame,bridge,at);}
        void enter()throws Exception{nativeToken(1180);SystemClock.setForTest(1185);session.beforeNativeClickInvocation(action,RUN);}
        WebEvidenceClientArmProjection client()throws Exception{return new WebEvidenceClientArmProjection(capture.binding,source);}
