        run("session_final_native_entry_is_cas_once",()->{
            Fixture f=new Fixture();need(f.session.nativeRegionForDispatch(f.action,RUN,f.frame)==f.bridge,"exact frame yields exact bridge");
            f.enter();need(f.session.consumed(),"original final hook consumed once");
