            Fixture f=new Fixture();rejects(()->f.session.beforeNativeClickInvocation(f.action,RUN));need(!f.session.consumed(),"ARM alone is no native entry");
            rejects(()->f.session.acceptNativeRegionCheck(f.action,RUN,null));
        });
        run("native_token_frame_identity_and_duplicate_check_are_rejected",()->{
            Fixture f=new Fixture();PhoneObservation other=WebWire4ConsumerHostTest.frame(WebWire4ConsumerHostTest.originalNodes,
                    f.capture.binding,WebWire4ConsumerHostTest.selection(f.capture.binding),f.capture.binding.getString("owner_sha256"),
                    f.frame.id,1160,false,false);
            rejects(()->f.session.injectSyntheticNativeToken(f.action,RUN,other,f.bridge,1180));
            f.nativeToken(1180);rejects(()->f.nativeToken(1180));
            rejects(()->f.session.nativeRegionForDispatch(f.action,RUN,other));
