        run("native_token_250ms_limit_and_future_timestamp_are_enforced",()->{
            Fixture stale=new Fixture();stale.nativeToken(1180);SystemClock.setForTest(1431);
            rejects(()->stale.session.beforeNativeClickInvocation(stale.action,RUN));need(!stale.session.consumed(),"251ms native check rejected");
            Fixture future=new Fixture();future.nativeToken(1181);SystemClock.setForTest(1180);
