        });
        run("expired_arm_cancelled_task_missing_source_or_wrong_run_cannot_enter",()->{
            Fixture expired=new Fixture();expired.nativeToken(1180);SystemClock.setForTest(expired.arm.getLong("expires_elapsed_ms"));
            rejects(()->expired.session.beforeNativeClickInvocation(expired.action,RUN));
            Fixture cancelled=new Fixture();cancelled.nativeToken(1180);cancelled.session.cancel();
            rejects(()->cancelled.session.beforeNativeClickInvocation(cancelled.action,RUN));
            Fixture missing=new Fixture();missing.nativeToken(1180);missing.session.removeSource();
            rejects(()->missing.session.beforeNativeClickInvocation(missing.action,RUN));
            Fixture wrong=new Fixture();wrong.nativeToken(1180);
