package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import java.net.URI;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads the real public city-picker structure. Labels and DOM paths are data,
 * never coordinates, Android node identities, selected-city proof or authority.
 */
final class CsairCityPicker {
    static final String SCHEMA="hepta.csair-observed-city-picker.v1";
    static final class City {
        final String text,path;
        final boolean disabled;
        City(JSONObject node)throws Exception{
            text=string(node,"text");path=string(node,"path");
            disabled=flag(node,"disabled")||"true".equals(node.get("aria_disabled"));
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();
            out.put("text",text);out.put("dom_path",path);out.put("dom_tag","li");out.put("dom_id","");
            out.put("dom_disabled",disabled);out.put("dom_visibility_is_native_visibility",false);
            return out;
        }
    }
    final String kind,title,titlePath,pickerPath,queryBoxPath,hotListPath;
    final List<City> cities;
    private CsairCityPicker(String title,String titlePath,String pickerPath,String queryBoxPath,
                            String hotListPath,List<City> cities){
        this.title=title;this.titlePath=titlePath;this.pickerPath=pickerPath;this.queryBoxPath=queryBoxPath;
        this.hotListPath=hotListPath;kind="选择出发地".equals(title)?"departure":"arrival";
        this.cities=Collections.unmodifiableList(new ArrayList<City>(cities));
    }
    /** No known picker returns null; a recognized but ambiguous picker is refused. */
    static CsairCityPicker read(JSONObject dom)throws Exception{
        URI url=new URI(string(dom,"href"));
        need("https".equals(url.getScheme())&&"m.csair.com".equals(url.getHost())
                &&url.getRawUserInfo()==null&&(url.getPort()==-1||url.getPort()==443)
                &&"/booking_new/".equals(url.getPath())&&"https://m.csair.com".equals(string(dom,"origin"))
                &&"complete".equals(string(dom,"ready_state")),"actual ready official booking document required");
        Index index=new Index(dom);
        List<JSONObject> titles=new ArrayList<JSONObject>();
        for(JSONObject n:index.nodes.values())if("div".equals(string(n,"tag"))&&index.visible(n)
                &&("选择出发地".equals(string(n,"text"))||"选择目的地".equals(string(n,"text"))))titles.add(n);
        if(titles.isEmpty())return null;
        need(titles.size()==1,"one visible city-picker title required");
        JSONObject title=titles.get(0),header=index.parent(title),picker=index.parent(header),box=index.parent(picker);
        plainDiv(title);plainDiv(header);plainDiv(picker);
        need("div".equals(string(box,"tag"))&&"queryBox".equals(string(box,"id"))
                &&index.visible(box),"city picker must be a direct child of the visible query box");
        List<JSONObject> forms=index.visibleId("div","flightQuery");
        need(forms.size()==1&&index.descendant(box,forms.get(0))&&index.visibleId("div","queryBox").size()==1,
                "same unique visible official form and query box required");
        List<JSONObject> hotLabels=new ArrayList<JSONObject>();
        for(JSONObject n:index.nodes.values())if(index.descendant(n,picker)&&index.visible(n)
                &&"div".equals(string(n,"tag"))&&"热门城市".equals(string(n,"text")))hotLabels.add(n);
        need(hotLabels.size()==1,"one actual hot-city section label required");
        JSONObject hot=hotLabels.get(0),section=index.parent(hot),content=index.parent(section);
        plainDiv(hot);plainDiv(section);plainDiv(content);
        need(index.parent(content)==picker&&content!=header,"hot-city section belongs to the current picker");
        List<JSONObject> lists=index.children(section,"ul");
        need(lists.size()==1&&index.visible(lists.get(0)),"one direct visible hot-city list required");
        JSONObject list=lists.get(0);
        need(string(list,"id").isEmpty()&&string(list,"text").isEmpty(),"plain actual hot-city list required");
        List<City> cities=new ArrayList<City>();
        for(JSONObject n:index.children(list,null)){
            need("li".equals(string(n,"tag")),"unreviewed hot-city list child");
            if(!index.visible(n))continue;
            need(string(n,"id").isEmpty()&&string(n,"role").isEmpty()
                    &&string(n,"name").isEmpty()&&string(n,"aria_label").isEmpty()
                    &&string(n,"text").matches("[\\p{IsHan}]{2,12}")
                    &&index.children(n,null).isEmpty(),"one plain full city label per actual list item");
            cities.add(new City(n));
        }
        need(!cities.isEmpty()&&cities.size()<=64,"bounded complete visible hot-city list required");
        return new CsairCityPicker(string(title,"text"),string(title,"path"),string(picker,"path"),
                string(box,"path"),string(list,"path"),cities);
    }
    /** Count before disabled filtering; a second matching label is not silently discarded. */
    City city(String exactOwnerCity){
        City found=null;
        for(City city:cities)if(city.text.equals(exactOwnerCity)){
            need(found==null,"duplicate visible requested city");found=city;
        }
        return found==null||found.disabled?null:found;
    }
    Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("schema",SCHEMA);out.put("kind",kind);out.put("title",title);
        out.put("title_dom_path",titlePath);out.put("picker_dom_path",pickerPath);
        out.put("query_box_dom_path",queryBoxPath);out.put("hot_city_list_dom_path",hotListPath);
        List<Map<String,Object>> values=new ArrayList<Map<String,Object>>();
        for(City city:cities)values.add(city.evidence());out.put("visible_hot_cities",values);
        out.put("city_selection_verified",false);out.put("airport_choice_inferred",false);
        out.put("query_executed",false);out.put("grants_tool_authority",false);
        out.put("css_to_screen_mapping_used",false);return out;
    }
    private static void plainDiv(JSONObject node)throws Exception{
        need(node!=null&&"div".equals(string(node,"tag"))&&string(node,"id").isEmpty(),"actual plain picker div required");
    }
    private static final class Index {
        final Map<String,JSONObject> nodes=new LinkedHashMap<String,JSONObject>();
        Index(JSONObject dom)throws Exception{
            String schema=string(dom,"schema");
            need(("hepta.fixed-top-document-dom.v2".equals(schema)||"hepta.fixed-top-document-dom.v3".equals(schema)||"hepta.fixed-top-document-dom.v4".equals(schema)),"actual geometry-aware fixed DOM required");
            need(Boolean.FALSE.equals(dom.get("truncated"))&&dom.getJSONArray("truncation_reasons").length()==0,
                    "complete bounded DOM required");
            JSONArray rows=dom.getJSONArray("nodes");need(rows.length()>0&&rows.length()<=1024,"bounded DOM nodes");
            for(int i=0;i<rows.length();i++){
                JSONObject n=rows.getJSONObject(i);String path=string(n,"path");
                need(path.matches("0(?:/[0-9]{1,5}){0,32}")&&!nodes.containsKey(path),"unique exact DOM path");
                need(string(n,"tag").matches("[a-z][a-z0-9:-]{0,63}"),"actual tag");
                for(String k:new String[]{"id","role","name","aria_label","text"})string(n,k);
                flag(n,"visible_in_viewport");flag(n,"disabled");
                Object aria=n.get("aria_disabled");need(aria==JSONObject.NULL||aria instanceof String,"aria disabled type");
                nodes.put(path,n);
            }
            need(nodes.containsKey("0"),"actual document root required");
            for(JSONObject n:nodes.values()){
                String path=string(n,"path");Object parent=n.get("parent_path");
                if("0".equals(path))need(parent==JSONObject.NULL,"document root parent");
                else need(parent instanceof String&&nodes.containsKey(parent)
                        &&path.substring(0,path.lastIndexOf('/')).equals(parent),"complete direct DOM ancestry");
            }
        }
        JSONObject parent(JSONObject n)throws Exception{
            need(n!=null&&n.get("parent_path") instanceof String,"actual parent required");
            JSONObject parent=nodes.get(n.getString("parent_path"));need(parent!=null,"parent missing");return parent;
        }
        boolean descendant(JSONObject n,JSONObject ancestor)throws Exception{
            return string(n,"path").startsWith(string(ancestor,"path")+"/");
        }
        boolean visible(JSONObject n)throws Exception{
            while(true){
                if(!flag(n,"visible_in_viewport"))return false;
                if("0".equals(string(n,"path")))return true;
                n=parent(n);
            }
        }
        List<JSONObject> children(JSONObject parent,String tag)throws Exception{
            List<JSONObject> result=new ArrayList<JSONObject>();String path=string(parent,"path");
            for(JSONObject n:nodes.values())if(path.equals(n.get("parent_path"))&&(tag==null||tag.equals(string(n,"tag"))))result.add(n);
            return result;
        }
        List<JSONObject> visibleId(String tag,String id)throws Exception{
            List<JSONObject> result=new ArrayList<JSONObject>();
            for(JSONObject n:nodes.values())if(tag.equals(string(n,"tag"))&&id.equals(string(n,"id"))&&visible(n))result.add(n);
            return result;
        }
    }
    private static String string(JSONObject object,String key)throws Exception{
        need(object!=null,"actual object required");Object value=object.get(key);
        need(value instanceof String&&((String)value).length()<=4096,"bounded actual string: "+key);return (String)value;
    }
    private static boolean flag(JSONObject object,String key)throws Exception{
        Object value=object.get(key);need(value instanceof Boolean,"actual boolean: "+key);return Boolean.TRUE.equals(value);
    }
    private static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Data-only reading of the actual official booking form.
 * DOM visibility is not screen visibility and no result grants an Android action.
 * The initial real capture has placeholders and no displayed year; those are
 * preserved as unknown query values rather than filled from the requested goal.
 */
final class CsairFlightForm {
    static final String SCHEMA="hepta.csair-observed-query-form.v1";
    private static final Pattern PATH=Pattern.compile("0(?:/[0-9]{1,5}){0,32}");
    private static final Pattern MONTH_DAY=Pattern.compile("([0-9]{1,2})月([0-9]{1,2})日");

    static final class Control {
        final String id,path,tag,requiredLabel;
        final List<String> visibleTexts;
        final boolean disabled;
        Control(JSONObject node,String label,List<String> texts)throws Exception{
            id=text(node,"id");path=text(node,"path");tag=text(node,"tag");
            requiredLabel=label;visibleTexts=Collections.unmodifiableList(new ArrayList<String>(texts));
            disabled=flag(node,"disabled")||"true".equals(node.get("aria_disabled"));
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();
            out.put("dom_path",path);out.put("dom_id",id);out.put("dom_tag",tag);
            out.put("required_label",requiredLabel);out.put("observed_visible_texts",visibleTexts);
            out.put("dom_disabled",disabled);out.put("dom_visibility_is_native_visibility",false);
            return out;
        }
    }
    final String formPath,queryBoxPath,tabContentPath,singlePanelPath,singleTabPath;
    final Control departure,arrival,departureDate,query;
    final boolean departurePlaceholder,arrivalPlaceholder,returnDateHidden,multiPanelHidden;
    final String departureCityLiteral,arrivalCityLiteral;
    final Integer displayedMonth,displayedDay;
    final String displayedWeekday;
    final int adults,children,infants;
    private CsairFlightForm(Index index,JSONObject form,JSONObject box,JSONObject tabs,JSONObject single,
            JSONObject singleTab,JSONObject dep,JSONObject arr,JSONObject date,JSONObject button,
            JSONObject passengers,boolean returnHidden,boolean multiHidden)throws Exception{
        formPath=text(form,"path");queryBoxPath=text(box,"path");tabContentPath=text(tabs,"path");
        singlePanelPath=text(single,"path");singleTabPath=text(singleTab,"path");
        departure=new Control(dep,"出发城市",index.visibleTexts(dep));
        arrival=new Control(arr,"到达城市",index.visibleTexts(arr));
        departureDate=new Control(date,"出发日期",index.visibleTexts(date));
        query=new Control(button,"查询",index.visibleTexts(button));
        need(departure.visibleTexts.contains(departure.requiredLabel)
                &&arrival.visibleTexts.contains(arrival.requiredLabel)
                &&departureDate.visibleTexts.contains(departureDate.requiredLabel)
                &&query.visibleTexts.size()==1&&"查询".equals(query.visibleTexts.get(0)),
                "actual field labels are missing or ambiguous");
        departurePlaceholder=only(departure.visibleTexts,"出发城市");
        arrivalPlaceholder=only(arrival.visibleTexts,"到达城市");
        departureCityLiteral=selectedCity(departure);
        arrivalCityLiteral=selectedCity(arrival);
        returnDateHidden=returnHidden;multiPanelHidden=multiHidden;
        Integer month=null,day=null;String weekday=null;
        for(String value:departureDate.visibleTexts){
            Matcher match=MONTH_DAY.matcher(value);
            if(match.matches()){
                need(month==null,"multiple displayed departure dates");
                int m=Integer.parseInt(match.group(1)),d=Integer.parseInt(match.group(2));
                need(m>=1&&m<=12&&d>=1&&d<=31,"invalid observed month/day");
                month=Integer.valueOf(m);day=Integer.valueOf(d);
            }else if(value.matches("周[一二三四五六日天]")){
                need(weekday==null,"multiple displayed departure weekdays");weekday=value;
            }else need("出发日期".equals(value),"unreviewed departure date display");
        }
        displayedMonth=month;displayedDay=day;displayedWeekday=weekday;
        adults=index.passenger(passengers,"成人");children=index.passenger(passengers,"儿童");infants=index.passenger(passengers,"婴儿");
    }

    /** Unsupported pages return null. A recognized but ambiguous form is rejected. */
    static CsairFlightForm read(JSONObject dom)throws Exception{
        java.net.URI url=new java.net.URI(text(dom,"href"));
        need("https".equals(url.getScheme())&&"m.csair.com".equals(url.getHost())
                &&url.getRawUserInfo()==null&&(url.getPort()==-1||url.getPort()==443)
                &&"/booking_new/".equals(url.getPath())&&"https://m.csair.com".equals(text(dom,"origin"))
                &&"complete".equals(text(dom,"ready_state")),"actual ready official booking document required");
        Index index=new Index(dom);
        List<JSONObject> forms=index.visible("div","flightQuery",null,false);
        if(forms.isEmpty())return null;
        need(forms.size()==1,"multiple visible official form roots");
        JSONObject form=forms.get(0),box=index.oneVisible("div","queryBox",form,false);
        JSONObject tabs=index.oneVisible("div","tabContent",box,false);
        JSONObject control=index.oneVisible("div","tabControl",box,false);
        JSONObject single=index.oneVisible("div","single",tabs,true);
        JSONObject singleTab=index.oneVisible("li","single",control,false);
        need("单程".equals(text(singleTab,"text")),"actual single trip tab label differs");
        JSONObject dep=index.oneVisible("div","depport",single,false);
        JSONObject arr=index.oneVisible("div","arrport",single,false);
        JSONObject date=index.oneVisible("div","depDate",single,false);
        JSONObject query=index.oneVisible("button","queryBtn",tabs,true);
        JSONObject passengers=index.oneVisible("div","psgBox",tabs,true);
        // Hidden multistage fields genuinely repeat these IDs. Only one visible
        // instance anywhere in this form may map to the current native AX ID.
        for(String id:new String[]{"depport","arrport","depDate"})
            need(index.visible("div",id,form,false).size()==1,"duplicate visible field: "+id);
        need(index.visible("button","queryBtn",form,false).size()==1,"duplicate visible query");
        need(index.all("div","arrDate",single,false).size()==1
                &&index.all("div","multistage",tabs,true).size()==1,"actual hidden return/multistage regions required");
        boolean returnHidden=index.visible("div","arrDate",single,false).isEmpty();
        boolean multiHidden=index.visible("div","multistage",tabs,true).isEmpty();
        need(returnHidden&&multiHidden,"return or multistage form is currently visible");
        return new CsairFlightForm(index,form,box,tabs,single,singleTab,dep,arr,date,query,passengers,returnHidden,multiHidden);
    }

    Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema",SCHEMA);
        out.put("form_dom_path",formPath);out.put("query_box_dom_path",queryBoxPath);
        out.put("tab_content_dom_path",tabContentPath);out.put("single_panel_dom_path",singlePanelPath);
        out.put("single_tab_dom_path",singleTabPath);out.put("return_date_hidden",returnDateHidden);
        out.put("multistage_panel_hidden",multiPanelHidden);out.put("departure_control",departure.evidence());
        out.put("arrival_control",arrival.evidence());out.put("departure_date_control",departureDate.evidence());
        out.put("query_control",query.evidence());out.put("departure_is_placeholder",departurePlaceholder);
        out.put("arrival_is_placeholder",arrivalPlaceholder);out.put("selected_departure_city",null);
        out.put("selected_arrival_city",null);out.put("observed_departure_city_literal",departureCityLiteral);
        out.put("observed_arrival_city_literal",arrivalCityLiteral);out.put("displayed_month",displayedMonth);
        out.put("displayed_day",displayedDay);out.put("displayed_weekday",displayedWeekday);
        out.put("displayed_year",null);out.put("complete_departure_date_verified",false);
        out.put("adults",adults);out.put("children",children);out.put("infants",infants);
        out.put("query_ready_verified",false);out.put("query_executed",false);
        out.put("flight_results_verified",false);out.put("grants_tool_authority",false);
        return out;
    }

    private static final class Index {
        final Map<String,JSONObject> nodes=new LinkedHashMap<String,JSONObject>();
        Index(JSONObject dom)throws Exception{
            String schema=text(dom,"schema");
            need("hepta.fixed-top-document-dom.v1".equals(schema)||"hepta.fixed-top-document-dom.v2".equals(schema)
                    ||"hepta.fixed-top-document-dom.v3".equals(schema)||"hepta.fixed-top-document-dom.v4".equals(schema),
                    "actual fixed observer DOM schema required");
            need(Boolean.FALSE.equals(dom.get("truncated"))&&dom.getJSONArray("truncation_reasons").length()==0,
                    "complete bounded DOM required");
            JSONArray rows=dom.getJSONArray("nodes");
            need(rows.length()>0&&rows.length()<=1024,"DOM node count");
            for(int i=0;i<rows.length();i++){
                JSONObject node=rows.getJSONObject(i);String path=text(node,"path");
                need(PATH.matcher(path).matches()&&!nodes.containsKey(path),"unique exact DOM paths required");
                need(text(node,"tag").matches("[a-z][a-z0-9:-]{0,63}"),"DOM tag shape");
                for(String key:new String[]{"id","role","name","aria_label","text"})text(node,key);
                flag(node,"visible_in_viewport");flag(node,"disabled");
                Object aria=node.get("aria_disabled");need(aria==JSONObject.NULL||aria instanceof String,"aria disabled type");
                nodes.put(path,node);
            }
            need(nodes.containsKey("0"),"actual document root required");
            for(Map.Entry<String,JSONObject> row:nodes.entrySet()){
                String path=row.getKey();Object parent=row.getValue().get("parent_path");
                if("0".equals(path))need(parent==JSONObject.NULL,"document root parent");
                else need(parent instanceof String&&nodes.containsKey(parent)
                        &&path.substring(0,path.lastIndexOf('/')).equals(parent),"complete direct DOM ancestry required");
            }
        }
        List<JSONObject> all(String tag,String id,JSONObject ancestor,boolean direct)throws Exception{
            List<JSONObject> found=new ArrayList<JSONObject>();String parent=ancestor==null?null:text(ancestor,"path");
            for(JSONObject node:nodes.values())if(tag.equals(text(node,"tag"))&&id.equals(text(node,"id"))
                    &&within(node,parent,direct))found.add(node);
            return found;
        }
        List<JSONObject> visible(String tag,String id,JSONObject ancestor,boolean direct)throws Exception{
            List<JSONObject> found=new ArrayList<JSONObject>();String parent=ancestor==null?null:text(ancestor,"path");
            for(JSONObject node:nodes.values())if(tag.equals(text(node,"tag"))&&id.equals(text(node,"id"))
                    &&visibleThrough(node,parent)&&within(node,parent,direct))found.add(node);
            return found;
        }
        JSONObject oneVisible(String tag,String id,JSONObject ancestor,boolean direct)throws Exception{
            List<JSONObject> found=visible(tag,id,ancestor,direct);
            need(found.size()==1,"one actual visible "+tag+"#"+id+" required");return found.get(0);
        }
        boolean within(JSONObject node,String parent,boolean direct)throws Exception{
            if(parent==null)return true;
            return direct?parent.equals(node.get("parent_path")):text(node,"path").startsWith(parent+"/");
        }
        boolean visibleThrough(JSONObject node,String ancestor)throws Exception{
            JSONObject cursor=node;
            while(cursor!=null){
                if(!flag(cursor,"visible_in_viewport"))return false;
                String path=text(cursor,"path");
                if(ancestor==null||path.equals(ancestor))return true;
                Object parent=cursor.get("parent_path");cursor=parent instanceof String?nodes.get(parent):null;
            }
            return false;
        }
        List<String> visibleTexts(JSONObject root)throws Exception{
            String prefix=text(root,"path");Set<String> values=new LinkedHashSet<String>();int characters=0;
            for(JSONObject node:nodes.values())if((text(node,"path").equals(prefix)||text(node,"path").startsWith(prefix+"/"))
                    &&visibleThrough(node,prefix)){
                String value=text(node,"text");if(!value.isEmpty()&&values.add(value)){
                    characters+=value.length();need(values.size()<=12&&characters<=256,"bounded complete field text required");
                }
            }
            return new ArrayList<String>(values);
        }
        int passenger(JSONObject root,String label)throws Exception{
            List<JSONObject> parents=new ArrayList<JSONObject>();String path=text(root,"path");
            for(JSONObject node:nodes.values())if("div".equals(text(node,"tag"))&&label.equals(text(node,"text"))
                    &&within(node,path,false)&&visibleThrough(node,path))parents.add(node);
            need(parents.size()==1,"one observed passenger label required: "+label);
            String parent=text(parents.get(0),"path");List<JSONObject> numbers=new ArrayList<JSONObject>();
            for(JSONObject node:nodes.values())if("span".equals(text(node,"tag"))&&parent.equals(node.get("parent_path"))
                    &&visibleThrough(node,parent))numbers.add(node);
            need(numbers.size()==1,"one direct observed passenger count required: "+label);
            String value=text(numbers.get(0),"text");need(value.matches("[0-9]"),"bounded actual passenger count");
            return Integer.parseInt(value);
        }
    }
    /** Only a separately visible literal city is data. Airports/codes/combined
     * strings remain unsupported rather than being translated into OWNER cities. */
    private static String selectedCity(Control control){
        String city=null;
        for(String value:control.visibleTexts){
            if(control.requiredLabel.equals(value))continue;
            need(value.matches("[\\p{IsHan}]{2,12}"),"unreviewed selected-city display");
            need(city==null,"multiple selected-city labels");city=value;
        }
        return city;
    }
    private static boolean only(List<String> values,String label){return values.size()==1&&label.equals(values.get(0));}
    private static String text(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof String,"actual string required: "+key);
        String text=(String)raw;need(text.length()<=4096,"bounded actual string");return text;
    }
    private static boolean flag(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof Boolean,"actual boolean required: "+key);return raw==Boolean.TRUE;
    }
    private static void need(boolean ok,String message){if(!ok)throw new IllegalArgumentException(message);}
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;

/** Fixed action schema bound to one real observation, never arbitrary caller GBNF. */
public final class DecisionGrammar {
    public static final String SCHEMA=ObservedTargetLabels.ACTION_SCHEMA;
    public final String observationId, currentPackage, text, sha256;
    public final List<String> actions;
    public final ObservedTargetLabels targets;
    public final String schema;
    public final ObservedAppLabels appLabels;
    public final TaskAuthorization.Frame authorization;
    public final Map<String,List<String>> scrollDirections;
    public final Set<String> submitNodes;
    public final Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedIntentTargets;
    /** Intersects OWNER authority with the current controller completion evidence. */
    public final boolean successAllowed;

    private DecisionGrammar(ObservedTargetLabels targets,String text,List<String> actions,Map<String,List<String>> scrollDirections,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization,Set<String> submits,boolean imeProtocol,Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,boolean successAllowed){
        this.successAllowed=successAllowed;
        this.submitNodes=Collections.unmodifiableSet(new TreeSet<String>(submits));
        this.fixedIntentTargets=Collections.unmodifiableMap(new TreeMap<String,org.trillionnium.hepta.background.FixedIntentTarget>(fixedTargets==null?Collections.<String,org.trillionnium.hepta.background.FixedIntentTarget>emptyMap():fixedTargets));
        this.authorization=authorization;this.appLabels=appLabels;this.schema=fixedTargets!=null?ActionDecision.FIXED_INTENT_ACTION_SCHEMA:imeProtocol?ActionDecision.IME_ACTION_SCHEMA:appLabels==null?SCHEMA:ObservedAppLabels.ACTION_SCHEMA;
        this.scrollDirections=Collections.unmodifiableMap(new TreeMap<String,List<String>>(scrollDirections));
        this.targets=targets;this.observationId=targets.observationId;this.currentPackage=targets.packageName;this.text=text;
        this.actions=Collections.unmodifiableList(new ArrayList<String>(actions));
        byte[] bytes=text.getBytes(StandardCharsets.UTF_8);
        if(bytes.length>65536)throw new IllegalArgumentException("observed action grammar exceeds bound");
        try{
            StringBuilder hash=new StringBuilder(64);
            for(byte value:MessageDigest.getInstance("SHA-256").digest(bytes))hash.append(String.format(Locale.ROOT,"%02x",value&255));
            this.sha256=hash.toString();
        }catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }

    public static DecisionGrammar create(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,ObservedTargetLabels targets){
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,targets,null,null,false,Collections.<String>emptySet(),false,null);
    }

    /** Explicit v4 entry; missing app metadata never selects the legacy grammar. */
    public static DecisionGrammar createAppLabeled(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels){
        if(appLabels==null)throw new IllegalArgumentException("observed app pairs are required");
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,targets,appLabels,null,false,Collections.<String>emptySet(),false,null);
    }

    public static DecisionGrammar createAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization){
        TaskAuthorization.require(authorization!=null,"动作语法缺少用户授权");
        if(appLabels==null)throw new IllegalArgumentException("observed app pairs are required");
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,targets,appLabels,authorization,false,Collections.<String>emptySet(),false,null);
    }

    /** A background display has no global HOME tool. Owner authorization is retained unchanged. */
    public static DecisionGrammar createBackgroundAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization){
        TaskAuthorization.require(authorization!=null,"后台动作语法缺少用户授权");
        if(appLabels==null)throw new IllegalArgumentException("observed app pairs are required");
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,targets,appLabels,authorization,true,Collections.<String>emptySet(),false,null);
    }

    /** Explicit v5 entry. Legacy grammar entry points cannot acquire submit. */
    public static DecisionGrammar createImeAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background){
        return createImeAuthorized(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                submitActions,targets,appLabels,authorization,background,null);
    }
    /** A task filter removes branches from the already observed/authorized
     * domain. Node, launcher and fixed-tool sets must be narrowed consistently. */
    public static DecisionGrammar createImeAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background,Set<String> taskTools){
        return createImeAuthorized(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                submitActions,targets,appLabels,authorization,background,taskTools,true);
    }
    /** A completion predicate can only remove success. It cannot grant a tool,
     * satisfy OWNER authority or replace the final observation/cleanup check. */
    public static DecisionGrammar createImeAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background,Set<String> taskTools,boolean successEligible){
        TaskAuthorization.require(authorization!=null,"IME 动作语法缺少用户授权");
        if(appLabels==null||targets==null||submitActions==null||submitActions.size()>200)
            throw new IllegalArgumentException("observed query action projection required");
        Set<String> submits=checkedNodes(submitActions.keySet());
        for(String id:submits)if(!targets.labels.containsKey(id)||submitActions.get(id)==null||!submitActions.get(id).queryAllowed())
            throw new IllegalArgumentException("submit is not a supplied query-labelled action");
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                targets,appLabels,authorization,background,submits,true,null,Collections.<String,String>emptyMap(),taskTools,successEligible);
    }

    /** Explicit v6: supplied installed targets are separate from launcher-open pairs. */
    public static DecisionGrammar createFixedIntentAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background,Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets){
        return createFixedIntentAuthorized(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                submitActions,targets,appLabels,authorization,background,fixedTargets,Collections.<String,String>emptyMap());
    }
    /** A caller may narrow a fixed tool to an immutable task payload; it cannot
     * supply another tool, grant authority or change the installed target. */
    public static DecisionGrammar createFixedIntentAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background,Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,
            Map<String,String> exactPayloads){
        return createFixedIntentAuthorized(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                submitActions,targets,appLabels,authorization,background,fixedTargets,exactPayloads,null);
    }
    public static DecisionGrammar createFixedIntentAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background,Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,
            Map<String,String> exactPayloads,Set<String> taskTools){
        return createFixedIntentAuthorized(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                submitActions,targets,appLabels,authorization,background,fixedTargets,exactPayloads,taskTools,true);
    }
    public static DecisionGrammar createFixedIntentAuthorized(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            Map<String,ObservedImeEnter> submitActions,ObservedTargetLabels targets,ObservedAppLabels appLabels,
            TaskAuthorization.Frame authorization,boolean background,Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,
            Map<String,String> exactPayloads,Set<String> taskTools,boolean successEligible){
        // Reuse the exact v5 validation for the existing node/action domain.
        DecisionGrammar checked=createImeAuthorized(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                submitActions,targets,appLabels,authorization,background,taskTools,successEligible);
        if(fixedTargets==null||fixedTargets.size()>2)throw new IllegalArgumentException("installed fixed targets required");
        Map<String,org.trillionnium.hepta.background.FixedIntentTarget> permitted=new TreeMap<String,org.trillionnium.hepta.background.FixedIntentTarget>();
        for(Map.Entry<String,org.trillionnium.hepta.background.FixedIntentTarget> entry:fixedTargets.entrySet()){
            org.trillionnium.hepta.background.FixedIntentTarget target=entry.getValue();
            if(target==null||!entry.getKey().equals(target.action)||!org.trillionnium.hepta.background.FixedIntentTools.isTool(target.action))
                throw new IllegalArgumentException("invalid installed fixed target");
            ObservedAppLabels.requireProjectedLabel(ObservedAppLabels.project(target.appLabel));
            TaskAuthorization.require(authorization.allows(target.action),"fixed intent exceeds owner tool authorization");
            permitted.put(target.action,target);
        }
        if(exactPayloads==null||!permitted.keySet().containsAll(exactPayloads.keySet()))
            throw new IllegalArgumentException("exact payload must belong to an already permitted fixed tool");
        for(Map.Entry<String,String> payload:exactPayloads.entrySet())
            org.trillionnium.hepta.background.FixedIntentTools.forAction(payload.getKey()).validatePayload(payload.getValue());
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                targets,appLabels,authorization,background,checked.submitNodes,true,permitted,exactPayloads,taskTools,successEligible);
    }

    private static DecisionGrammar createInternal(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization,boolean background,Set<String> submitNodes,boolean imeProtocol,Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets){
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                targets,appLabels,authorization,background,submitNodes,imeProtocol,fixedTargets,Collections.<String,String>emptyMap());
    }
    private static DecisionGrammar createInternal(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization,boolean background,Set<String> submitNodes,boolean imeProtocol,
            Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,Map<String,String> exactPayloads){
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                targets,appLabels,authorization,background,submitNodes,imeProtocol,fixedTargets,exactPayloads,null);
    }
    private static DecisionGrammar createInternal(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization,boolean background,Set<String> submitNodes,boolean imeProtocol,
            Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,Map<String,String> exactPayloads,Set<String> taskTools){
        return createInternal(observationId,currentPackage,shownApps,clickableNodes,editableNodes,scrollActions,
                targets,appLabels,authorization,background,submitNodes,imeProtocol,fixedTargets,exactPayloads,taskTools,true);
    }
    private static DecisionGrammar createInternal(String observationId,String currentPackage,Set<String> shownApps,
            Set<String> clickableNodes,Set<String> editableNodes,Map<String,ObservedScrollActions> scrollActions,
            ObservedTargetLabels targets,ObservedAppLabels appLabels,TaskAuthorization.Frame authorization,boolean background,Set<String> submitNodes,boolean imeProtocol,
            Map<String,org.trillionnium.hepta.background.FixedIntentTarget> fixedTargets,Map<String,String> exactPayloads,Set<String> taskTools,boolean successEligible){
        taskTools=checkedTaskTools(taskTools);
        if(observationId==null||!observationId.matches("[0-9a-f]{32}"))throw new IllegalArgumentException("invalid observed id");
        checkPackage(currentPackage);
        if(targets==null||!observationId.equals(targets.observationId)||!currentPackage.equals(targets.packageName))
            throw new IllegalArgumentException("observed label projection belongs to a different window");
        if(shownApps==null||shownApps.size()>40)throw new IllegalArgumentException("invalid application projection");
        TreeSet<String> apps=new TreeSet<String>();
        for(String name:shownApps){checkPackage(name);if(!currentPackage.equals(name)&&!"android".equals(name))apps.add(name);}
        if(appLabels!=null&&(!observationId.equals(appLabels.observationId)||!currentPackage.equals(appLabels.currentPackage)
                ||!apps.equals(appLabels.labels.keySet())))throw new IllegalArgumentException("app pairs differ from the current allowed projection");
        TreeSet<String> clicks=checkedNodes(clickableNodes),edits=checkedNodes(editableNodes),submits=checkedNodes(submitNodes);
        Map<String,List<String>> scrolls=checkedScrollActions(scrollActions,targets);
        if(authorization!=null){
            TaskAuthorization.require(apps.equals(authorization.openPackages(apps)),"打开目标投影超出用户授权");
            if(!authorization.allows("click"))clicks.clear();
            if(!authorization.allows("type"))edits.clear();
            if(!authorization.allows("submit"))submits.clear();
            if(!authorization.allows("scroll"))scrolls.clear();
        }
        if((!permitted(taskTools,"open")&&!apps.isEmpty())||(!permitted(taskTools,"click")&&!clicks.isEmpty())
                ||(!permitted(taskTools,"type")&&!edits.isEmpty())||(!permitted(taskTools,"submit")&&!submits.isEmpty())
                ||(!permitted(taskTools,"scroll")&&!scrolls.isEmpty())
                ||(fixedTargets!=null&&taskTools!=null&&!taskTools.containsAll(fixedTargets.keySet())))
            throw new IllegalArgumentException("task tool filter differs from the supplied capability domain");
        StringBuilder rules=new StringBuilder();List<String> branches=new ArrayList<String>();
        if(permitted(taskTools,"find_app")&&(authorization==null||authorization.allows("find_app"))){
            branches.add("find_app");
            String queryRule=authorization!=null&&authorization.authorization.requireFindAppBeforeOpen?jsonValue(authorization.authorization.findQuery):"query-string";
            rule(rules,"find-app",prefix("find_app",observationId)+field("package",jsonValue(currentPackage))+comma()+field("query",queryRule)+comma()+field("offset","app-offset")+ending());
        }
        if(!apps.isEmpty()){
            branches.add("open");
            if(appLabels==null){
                rule(rules,"open",prefix("open",observationId)+field("package","open-package")+ending());
                rule(rules,"open-package",alternatives(apps));
            }else{
                rule(rules,"open",prefix("open",observationId)+"open-target"+ending());
                rule(rules,"open-target",appPairs(appLabels));
            }
        }
        if(fixedTargets!=null)for(org.trillionnium.hepta.background.FixedIntentTarget target:fixedTargets.values()){
            branches.add(target.action);
            rule(rules,target.action.replace('.','-'),prefix(target.action,observationId)
                    +field("app_label",jsonValue(ObservedAppLabels.project(target.appLabel)))+comma()
                    +field("package",jsonValue(target.packageName))+comma()
                    +field("notes.create".equals(target.action)?"text":"query",exactPayloads.containsKey(target.action)
                            ?jsonValue(exactPayloads.get(target.action)):"fixed-payload-string")+ending());
        }
        if(!clicks.isEmpty()){
            branches.add("click");rule(rules,"click",prefix("click",observationId)+field("package",jsonValue(currentPackage))+comma()+"click-target"+ending());
            rule(rules,"click-target",targetPairs(clicks,targets));
        }
        if(!edits.isEmpty()){
            branches.add("type");rule(rules,"type",prefix("type",observationId)+field("package",jsonValue(currentPackage))+comma()+"type-target"+comma()+field("text","text-string")+ending());
            rule(rules,"type-target",targetPairs(edits,targets));
        }
        if(!submits.isEmpty()){
            if(!imeProtocol)throw new IllegalArgumentException("legacy protocol cannot submit");
            branches.add("submit");rule(rules,"submit",prefix("submit",observationId)+field("package",jsonValue(currentPackage))+comma()+"submit-target"+ending());
            rule(rules,"submit-target",targetPairs(submits,targets));
        }
        if(!scrolls.isEmpty()){
            branches.add("scroll");rule(rules,"scroll",prefix("scroll",observationId)+field("package",jsonValue(currentPackage))+comma()+"scroll-target"+ending());
            rule(rules,"scroll-target",scrollPairs(scrolls,targets));
        }
        for(String name:new String[]{"back","home"}){
            if(!permitted(taskTools,name))continue;
            if(background&&"home".equals(name))continue;
            if(authorization!=null&&!authorization.allows(name))continue;
            branches.add(name);rule(rules,name,prefix(name,observationId)+field("package",jsonValue(currentPackage))+ending());
        }
        if(permitted(taskTools,"wait")&&(authorization==null||authorization.allows("wait"))){branches.add("wait");rule(rules,"wait",prefix("wait",observationId)+field("package",jsonValue(currentPackage))+comma()+field("duration_ms","duration")+ending());}
        branches.add("done");rule(rules,"done",prefix("done",observationId)+field("package",jsonValue(currentPackage))+comma()+field("status","status")+comma()+field("summary","summary-string")+ending());
        // A brief state assessment precedes action selection in the generated JSON.
        boolean successAllowed=successEligible&&(authorization==null||authorization.successAllowed());
        rule(rules,"status",alternatives(new TreeSet<String>(java.util.Arrays.asList(successAllowed?new String[]{"success","partial","failure"}:new String[]{"partial","failure"}))));
        rule(rules,"duration","[1-9] [0-9]{2} | "+literal("1")+" [0-9]{3} | "+literal("2000"));
        rule(rules,"app-offset",literal("0")+" | [1-9] [0-9]{0,2} | [1-3] [0-9]{3} | "+literal("40")+" [0-8] [0-9] | "+literal("409")+" [0-5]");
        rule(rules,"query-string",literal("\"")+" json-char{0,64} "+literal("\""));
        rule(rules,"reason-string",literal("\"")+" json-char{1,96} "+literal("\""));
        // At most 1024 Unicode scalar values imply at most 4096 decoded UTF-8 bytes.
        rule(rules,"text-string",literal("\"")+" json-char{0,1024} "+literal("\""));
        if(fixedTargets!=null)rule(rules,"fixed-payload-string",literal("\"")+" json-char{1,1024} "+literal("\""));
        rule(rules,"summary-string",literal("\"")+" json-char{1,1024} "+literal("\""));
        rules.append("json-char ::= [^\"\\\\\\x00-\\x1F] | "+literal("\\")+" [\"\\\\/bfnrt]\n");
        rule(rules,"ws","[ \\t\\n\\r]{0,8}");
        List<String> ruleNames=new ArrayList<String>();for(String branch:branches)ruleNames.add(branch.replace('_','-').replace('.','-'));
        return new DecisionGrammar(targets,"root ::= ws ("+join(ruleNames," | ")+") ws\n"+rules.toString(),branches,scrolls,appLabels,authorization,submits,imeProtocol,fixedTargets,successAllowed);
    }

    /** Recheck the same immutable grammar predicate after native parsing and
     * immediately before controller dispatch. Service done has no phone effect;
     * accepting a report still requires the existing independent final gate. */
    public void requireCompletionStatus(ActionDecision action)throws ActionDecision.InvalidActionException{
        if("done".equals(action.action)&&"success".equals(action.status)&&!successAllowed)
            throw new ActionDecision.InvalidActionException("当前观察未满足本任务完成证据，done 只能报告 partial 或 failure");
    }

    public boolean allowsSubmit(String nodeId){return submitNodes.contains(nodeId);}

    /** A direction cannot migrate to another node that has a different action list. */
    public boolean allowsScroll(String nodeId,String direction){
        List<String> allowed=scrollDirections.get(nodeId);return allowed!=null&&allowed.contains(direction);
    }
    private static boolean permitted(Set<String> taskTools,String action){return taskTools==null||taskTools.contains(action);}
    private static Set<String> checkedTaskTools(Set<String> values){
        if(values==null)return null;
        Set<String> known=new TreeSet<String>(java.util.Arrays.asList("find_app","open","notes.create","web.search",
                "click","type","submit","scroll","back","home","wait","done"));
        if(!values.contains("done")||!known.containsAll(values))
            throw new IllegalArgumentException("task tool filter must retain terminal reporting and known tools only");
        return Collections.unmodifiableSet(new TreeSet<String>(values));
    }
    private static Map<String,List<String>> checkedScrollActions(Map<String,ObservedScrollActions> values,ObservedTargetLabels targets){
        if(values==null||values.size()>200)throw new IllegalArgumentException("invalid scroll action projection");
        checkedNodes(values.keySet());Map<String,List<String>> result=new TreeMap<String,List<String>>();
        for(Map.Entry<String,ObservedScrollActions> pair:values.entrySet()){
            if(!targets.labels.containsKey(pair.getKey())||pair.getValue()==null)
                throw new IllegalArgumentException("scroll capability is not bound to a supplied node");
            if(pair.getValue().hasAny())result.put(pair.getKey(),pair.getValue().directions);
        }
        return result;
    }
    private static String scrollPairs(Map<String,List<String>> values,ObservedTargetLabels targets){
        List<String> pairs=new ArrayList<String>();
        for(Map.Entry<String,List<String>> pair:values.entrySet()){
            String id=pair.getKey();
            pairs.add("("+field("node_label",jsonValue(targets.labels.get(id)))+comma()+field("node_id",jsonValue(id))
                    +comma()+field("direction","("+alternatives(pair.getValue())+")")+")");
        }
        return join(pairs," | ");
    }

    private static void checkPackage(String value){
        if(value==null||value.length()>255||(!"android".equals(value)&&!value.matches("[A-Za-z][A-Za-z0-9_]*(?:\\.[A-Za-z][A-Za-z0-9_]*)+")))
            throw new IllegalArgumentException("invalid observed package");
    }
    private static TreeSet<String> checkedNodes(Set<String> values){
        if(values==null||values.size()>200)throw new IllegalArgumentException("invalid node projection");
        TreeSet<String> result=new TreeSet<String>();
        for(String value:values){if(value==null||!value.matches("n[0-9]{1,5}"))throw new IllegalArgumentException("invalid observed node id");result.add(value);}
        return result;
    }
    private static String prefix(String action,String observation){return literal("{")+" ws "+field("reason","reason-string")+comma()+field("action",jsonValue(action))+comma()+field("observation_id",jsonValue(observation))+comma();}
    private static String field(String key,String valueRule){return jsonValue(key)+" ws "+literal(":")+" ws "+valueRule;}
    private static String comma(){return " ws "+literal(",")+" ws ";}
    private static String ending(){return " ws "+literal("}");}
    private static void rule(StringBuilder target,String name,String body){target.append(name).append(" ::= ").append(body).append('\n');}
    private static String alternatives(Iterable<String> values){List<String> parts=new ArrayList<String>();for(String value:values)parts.add(jsonValue(value));return join(parts," | ");}
    private static String targetPairs(Iterable<String> ids,ObservedTargetLabels targets){
        List<String> pairs=new ArrayList<String>();
        for(String id:ids){
            if(!targets.labels.containsKey(id))throw new IllegalArgumentException("action node was absent from the supplied label projection");
            pairs.add("("+field("node_label",jsonValue(targets.labels.get(id)))+comma()+field("node_id",jsonValue(id))+")");
        }
        return join(pairs," | ");
    }
    private static String appPairs(ObservedAppLabels apps){
        List<String> pairs=new ArrayList<String>();
        for(Map.Entry<String,String> pair:apps.labels.entrySet())
            pairs.add("("+field("app_label",jsonValue(pair.getValue()))+comma()+field("package",jsonValue(pair.getKey()))+")");
        return join(pairs," | ");
    }
    private static String join(Iterable<String> values,String separator){StringBuilder out=new StringBuilder();for(String value:values){if(out.length()>0)out.append(separator);out.append(value);}return out.toString();}
    private static String jsonValue(String value){
        StringBuilder out=new StringBuilder("\"");
        for(int i=0;i<value.length();i++){
            char c=value.charAt(i);
            switch(c){
                case '\"':out.append("\\\"");break;case '\\':out.append("\\\\");break;
                case '\b':out.append("\\b");break;case '\f':out.append("\\f");break;
                case '\n':out.append("\\n");break;case '\r':out.append("\\r");break;case '\t':out.append("\\t");break;
                default:if(c<32||c=='\u2028'||c=='\u2029')out.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else out.append(c);
            }
        }
        return literal(out.append('\"').toString());
    }
    private static String literal(String text){return "\""+text.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.local.web.WebShoppingGoal;
import org.trillionnium.hepta.webprotocol.WebSitePolicy;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Bounded read-only projection of an actual complete DOM-v4 record.
 * No Mi CSS selector, SKU, price, or currency is invented from a search index.
 * Only explicit visible HTML Product/Offer semantics can produce detail data;
 * a page without those semantics remains partial until its actual layout is reviewed.
 * This projection alone cannot grant an AX action or task completion.
 */
final class MiPublicProductPage {
    static final String SCHEMA="hepta.mi-public-product-page.v2";
    static final String DOM_SCHEMA="hepta.fixed-top-document-dom.v4";
    private static final Pattern MODEL=Pattern.compile("^(?:(?:Xiaomi|小米)[ ]*(?:(?:路由器|Router)[ ]*)?)?AX3000T(?: 白色)?$",Pattern.CASE_INSENSITIVE);
    private static final Pattern AMOUNT=Pattern.compile("^(?:(?:人民币|CNY|RMB|¥|￥)[ ]*)?((?:0|[1-9][0-9]{0,7})(?:\\.[0-9]{1,2})?)(?:[ ]*元)?$");
    private static final Pattern CONDITIONAL=Pattern.compile("券|会员|补贴|定金|分期|每月|月供|预售|预约|满减|到手|折后|需登录|需领|秒杀|限时|首购");
    final String url,phase;
    final boolean modalPresent;
    final List<Link> productLinks;
    final Detail detail;
    final List<String> missing;
    private final Map<String,JSONObject> nodes;
    private final Map<String,Integer> ids;
    static final class Link {
        final String path,id,label,hrefRaw,hrefResolved,target,modelPath;
        final List<String> visibleTexts;
        Link(JSONObject node,JSONObject model,List<String> texts,String resolved)throws Exception {
            path=text(node,"path");id=text(node,"id");label=text(model,"text");
            hrefRaw=text(node,"href_raw");hrefResolved=resolved;target=text(node,"link_target");
            modelPath=text(model,"path");visibleTexts=Collections.unmodifiableList(new ArrayList<String>(texts));
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("anchor_dom_path",path);out.put("anchor_dom_id",id);
            out.put("model_dom_path",modelPath);out.put("model_label",label);out.put("href_raw",hrefRaw);
            out.put("href_resolved",hrefResolved);out.put("link_target",target);out.put("visible_texts",visibleTexts);
            out.put("navigation_authorized",false);out.put("product_detail_verified",false);return out;
        }
    }
    static final class Detail {
        final String productPath,offerPath,modelPath,modelLabel,pricePath,priceRaw,currencyPath,currencyRaw;
        final String amountDecimal,priceKind,skuPath,skuRaw;
        final List<String> visibleProductTexts,visibleOfferTexts;
        final boolean exactPublicPrice;
        Detail(String product,String offer,JSONObject model,JSONObject price,JSONObject currency,
               JSONObject sku,List<String> productTexts,List<String> offerTexts,String amount,String kind)throws Exception {
            productPath=product;offerPath=offer;modelPath=text(model,"path");modelLabel=text(model,"text");
            pricePath=text(price,"path");priceRaw=text(price,"text");currencyPath=text(currency,"path");currencyRaw=text(currency,"text");
            skuPath=sku==null?null:text(sku,"path");skuRaw=sku==null?null:text(sku,"text");
            amountDecimal=amount;priceKind=kind;exactPublicPrice="public_exact_display".equals(kind);
            visibleProductTexts=Collections.unmodifiableList(new ArrayList<String>(productTexts));
            visibleOfferTexts=Collections.unmodifiableList(new ArrayList<String>(offerTexts));
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("product_dom_path",productPath);out.put("offer_dom_path",offerPath);
            out.put("model_dom_path",modelPath);out.put("model_raw",modelLabel);out.put("price_dom_path",pricePath);
            out.put("displayed_price_raw",priceRaw);out.put("amount_decimal",amountDecimal);out.put("currency_dom_path",currencyPath);
            out.put("currency_raw",currencyRaw);out.put("currency","CNY");out.put("price_kind",priceKind);
            out.put("sku_dom_path",skuPath);out.put("visible_sku_raw",skuRaw);out.put("selected_variant",null);out.put("quantity",null);
            out.put("visible_product_texts",visibleProductTexts);out.put("visible_offer_texts",visibleOfferTexts);
            out.put("exact_configuration_verified",false);out.put("specifications_verified",false);
            out.put("native_visibility_verified",false);out.put("model_navigation_verified",false);
            out.put("task_completion_verified",false);return out;
        }
    }
    private MiPublicProductPage(String url,String phase,boolean modal,List<Link> links,Detail detail,List<String> missing,
                                Map<String,JSONObject> nodes,Map<String,Integer> ids){
        this.url=url;this.phase=phase;modalPresent=modal;productLinks=Collections.unmodifiableList(new ArrayList<Link>(links));
        this.detail=detail;this.missing=Collections.unmodifiableList(new ArrayList<String>(missing));this.nodes=nodes;this.ids=ids;
    }
    static MiPublicProductPage read(WebShoppingGoal goal,WebSitePolicy policy,String committed,JSONObject dom)throws Exception{
        need(goal!=null&&policy!=null&&dom!=null,"immutable goal/policy and actual DOM required");
        need(DOM_SCHEMA.equals(text(dom,"schema"))&&Boolean.FALSE.equals(dom.get("truncated"))
                &&dom.getJSONArray("truncation_reasons").length()==0,"complete exact DOM-v4 required");
        need(committed.equals(text(dom,"href"))&&policy.origin.equals(text(dom,"origin"))&&policy.allowsMainFrame(committed),
                "same approved committed product route required");
        need("complete".equals(text(dom,"ready_state")),"public page still loading");
        JSONArray rows=dom.getJSONArray("nodes");need(rows.length()>0&&rows.length()<=1536,"bounded actual DOM nodes");
        Map<String,JSONObject> nodes=new LinkedHashMap<String,JSONObject>();Map<String,Integer> ids=new HashMap<String,Integer>();
        for(int i=0;i<rows.length();i++){
            JSONObject n=rows.getJSONObject(i);String path=text(n,"path"),id=text(n,"id");
            need(path.matches("0(?:/[0-9]{1,5}){0,32}")&&!nodes.containsKey(path),"unique complete DOM ancestry");
            for(String k:Arrays.asList("tag","role","text","aria_label","item_type","item_prop","aria_hidden","aria_modal","aria_selected","aria_checked","aria_pressed"))
                text(n,k);
            for(String k:Arrays.asList("visible_in_viewport","disabled","item_scope","hidden_attr","inert_attr"))
                need(n.get(k) instanceof Boolean,"typed DOM boolean: "+k);
            for(String k:Arrays.asList("href_raw","href_resolved","link_target"))
                need(n.get(k)==JSONObject.NULL||n.get(k) instanceof String&&((String)n.get(k)).length()<=4096,"bounded anchor field");
            nodes.put(path,n);if(!id.isEmpty())ids.put(id,ids.containsKey(id)?ids.get(id)+1:1);
        }
        for(JSONObject n:nodes.values()){
            String path=text(n,"path");Object parent=n.get("parent_path");
            need("0".equals(path)?parent==JSONObject.NULL:parent instanceof String&&nodes.containsKey(parent)
                    &&path.substring(0,path.lastIndexOf('/')).equals(parent),"recorded DOM parent required");
        }
        List<String> missing=new ArrayList<String>();List<Link> links=new ArrayList<Link>();Detail detail=null;boolean modal=false;
        for(JSONObject n:nodes.values())if(visible(n,nodes)&&("dialog".equals(text(n,"tag"))
                ||"dialog".equals(text(n,"role"))||"alertdialog".equals(text(n,"role"))||"true".equals(text(n,"aria_modal"))))modal=true;
        WebSitePolicy.Route route=policy.classify(committed);
        String phase=route==WebSitePolicy.Route.INITIAL_PUBLIC_SEARCH?"official_public_search":"official_product_detail";
        if(modal)missing.add("visible_modal_or_consent_requires_stop");
        if(route==WebSitePolicy.Route.INITIAL_PUBLIC_SEARCH){
            try{
                org.trillionnium.hepta.webprotocol.WebMiActionRegion region=
                        org.trillionnium.hepta.webprotocol.WebMiActionRegion.read(dom);
                JSONObject anchor=nodes.get(region.anchorPath),model=nodes.get(region.modelPath);
                need(anchor!=null&&model!=null,"actual scoped anchor/model disappeared");
                List<String> texts=visibleTexts(nodes,region.anchorPath,64);
                need(!containsTransaction(texts),"transaction or consent labels cannot grant public product navigation");
                links.add(new Link(anchor,model,texts,region.hrefResolved));
                missing.add("native_semantic_region_bridge_required");
            }catch(Exception unavailable){
                missing.add("complete_observed_public_search_card_region_unavailable");
            }
            if(links.size()!=1)missing.add("unique_actual_AX3000T_anchor_not_observed");
            missing.add("detail_page_not_observed");
        }else{
            List<JSONObject> products=new ArrayList<JSONObject>();
            for(JSONObject n:nodes.values())if(visible(n,nodes)&&Boolean.TRUE.equals(n.get("item_scope"))
                    &&typeIs(n,"Product")&&insideMain(n,nodes))products.add(n);
            if(products.size()!=1)missing.add("unique_visible_explicit_Product_scope_missing");
            else{
                JSONObject product=products.get(0);String productPath=text(product,"path");
                List<JSONObject> models=matchingModel(nodes,productPath),offers=new ArrayList<JSONObject>();
                for(JSONObject n:nodes.values())if(descendant(productPath,text(n,"path"))&&visible(n,nodes)
                        &&Boolean.TRUE.equals(n.get("item_scope"))&&typeIs(n,"Offer")&&prop(n,"offers"))offers.add(n);
                if(models.size()!=1)missing.add("unique_same_product_model_missing");
                if(offers.size()!=1)missing.add("unique_visible_Offer_scope_missing");
                if(models.size()==1&&offers.size()==1){
                    String offerPath=text(offers.get(0),"path");
                    List<JSONObject> prices=properties(nodes,offerPath,"price"),currencies=properties(nodes,offerPath,"priceCurrency");
                    List<JSONObject> skus=properties(nodes,productPath,"sku");
                    if(prices.size()!=1||currencies.size()!=1)missing.add("unique_visible_price_and_currency_missing");
                    else{
                        JSONObject price=prices.get(0),currency=currencies.get(0);Matcher amount=AMOUNT.matcher(text(price,"text"));
                        boolean cny=Arrays.asList("CNY","RMB","人民币","元").contains(text(currency,"text"));
                        if(!amount.matches()||!cny||struck(price,nodes))missing.add("visible_current_CNY_amount_not_verified");
                        else{
                            BigDecimal number=new BigDecimal(amount.group(1));need(number.signum()>0,"nonpositive public price");
                            List<String> productTexts=visibleTexts(nodes,productPath,256),offerTexts=visibleTexts(nodes,offerPath,96);
                            String joined=join(productTexts);String kind=CONDITIONAL.matcher(joined).find()?"conditional":
                                    joined.contains("起")?"starting_price":"public_exact_display";
                            detail=new Detail(productPath,offerPath,models.get(0),price,currency,skus.size()==1?skus.get(0):null,
                                    productTexts,offerTexts,amount.group(1),kind);
                            if(!detail.exactPublicPrice)missing.add("price_is_starting_or_conditional");
                            if(goal.singleUnitRequested)missing.add("requested_single_unit_and_selected_variant_unverified");
                            if(goal.specificationsRequested)missing.add("requested_hardware_specifications_unverified");
                        }
                    }
                }
            }
        }
        return new MiPublicProductPage(committed,phase,modal,links,detail,missing,nodes,ids);
    }
    Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema",SCHEMA);out.put("current_native_url",url);
        out.put("phase",phase);out.put("visible_modal_present",modalPresent);List<Object> links=new ArrayList<Object>();
        for(Link link:productLinks)links.add(link.evidence());out.put("actual_product_link_candidates",links);
        out.put("detail_projection",detail==null?null:detail.evidence());out.put("missing",missing);
        out.put("search_index_used",false);out.put("price_or_SKU_filled_from_goal",false);out.put("business_verified",false);
        out.put("layout_visibility_is_screen_proof",false);return out;
    }
    boolean uniqueId(String id){return id!=null&&!id.isEmpty()&&Integer.valueOf(1).equals(ids.get(id));}
    private static List<JSONObject> matchingModel(Map<String,JSONObject> nodes,String root)throws Exception{
        List<JSONObject> out=new ArrayList<JSONObject>();for(JSONObject n:nodes.values())
            if(descendant(root,text(n,"path"))&&visible(n,nodes)&&MODEL.matcher(text(n,"text")).matches())out.add(n);return out;
    }
    private static List<JSONObject> properties(Map<String,JSONObject> nodes,String root,String property)throws Exception{
        List<JSONObject> out=new ArrayList<JSONObject>();for(JSONObject n:nodes.values())
            if(descendant(root,text(n,"path"))&&visible(n,nodes)&&prop(n,property)&&!text(n,"text").isEmpty())out.add(n);return out;
    }
    private static List<String> visibleTexts(Map<String,JSONObject> nodes,String root,int max)throws Exception{
        List<String> out=new ArrayList<String>();for(JSONObject n:nodes.values())if(descendant(root,text(n,"path"))&&visible(n,nodes)){
            String s=text(n,"text");if(!s.isEmpty()){need(out.size()<max,"complete product text budget exceeded");out.add(s);}}
        return out;
    }
    private static boolean nestedControl(Map<String,JSONObject> nodes,String root)throws Exception{
        for(JSONObject n:nodes.values()){String path=text(n,"path");if(path.equals(root)||!descendant(root,path))continue;
            if(Arrays.asList("a","button","input","select","textarea").contains(text(n,"tag"))
                    ||Arrays.asList("button","checkbox","radio","textbox").contains(text(n,"role")))return true;}
        return false;
    }
    private static boolean containsTransaction(List<String> texts){String s=join(texts);
        return s.contains("购买")||s.contains("加购")||s.contains("购物车")||s.contains("付款")||s.contains("支付")
                ||s.contains("领券")||s.contains("登录")||s.contains("同意")||s.contains("下单");}
    private static boolean insideMain(JSONObject node,Map<String,JSONObject> nodes)throws Exception{
        JSONObject n=node;while(n!=null){if("main".equals(text(n,"tag"))||"main".equals(text(n,"role")))return true;
            Object p=n.get("parent_path");n=p instanceof String?nodes.get(p):null;}return false;
    }
    private static boolean struck(JSONObject node,Map<String,JSONObject> nodes)throws Exception{
        JSONObject n=node;while(n!=null){if("del".equals(text(n,"tag"))||"s".equals(text(n,"tag")))return true;
            Object p=n.get("parent_path");n=p instanceof String?nodes.get(p):null;}return false;
    }
    private static boolean typeIs(JSONObject n,String type)throws Exception{
        String value=text(n,"item_type");return value.equals("https://schema.org/"+type)||value.equals("http://schema.org/"+type);
    }
    private static boolean prop(JSONObject n,String value)throws Exception{return Arrays.asList(text(n,"item_prop").split("\\s+")).contains(value);}
    private static boolean visible(JSONObject node,Map<String,JSONObject> nodes)throws Exception{
        JSONObject n=node;while(n!=null){
            if(!Boolean.TRUE.equals(n.get("visible_in_viewport"))||Boolean.TRUE.equals(n.get("hidden_attr"))
                    ||Boolean.TRUE.equals(n.get("inert_attr"))||"true".equals(text(n,"aria_hidden")))return false;
            Object p=n.get("parent_path");if(p==JSONObject.NULL)return "0".equals(text(n,"path"));n=nodes.get(p);
        }return false;
    }
    private static String join(List<String> strings){StringBuilder out=new StringBuilder();for(String s:strings)out.append(s).append('\n');return out.toString();}
    private static boolean descendant(String root,String path){return root.equals(path)||path.startsWith(root+"/");}
    private static String text(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof String&&((String)raw).length()<=4096,"bounded actual DOM string: "+key);
        return (String)raw;
    }
    private static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
}

package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Pure checks of current Moto Notes observations, never a save API or a goal oracle.
 * The caller supplies actual observation/installed facts and binds task, native run,
 * dispatch, freshness and display continuity separately. No text is normalized.
 */
public final class NotesCompletionEvidence {
    public static final String NOTES="com.motorola.stylus";
    public static final String OBSERVED_BASE_APK_SHA256=
            "0e1a52a937c04ec8df380bff3750ce4b345fa0d8d33683e5ae8aa08e70e94017";
    public static final String PERSISTENCE_LIMIT=
            "Observed text only; trailing LF origin and persistent storage bytes are unverified.";
    public static final String LIST_TEXT_SCOPE=
            "Complete accessibility text source; visual clipping and persistent storage bytes are unverified.";
    private static final String FORTY_LF=fortyLf();
    private static final int MAX_NODES=200;
    private NotesCompletionEvidence() {}

    public static final class Frame {
        public final String observationId,packageName,backgroundGeneration;
        public final int windowId,displayId,windowType;
        public final boolean metadataObserved,nodesTruncated;
        public final List<Node> nodes;
        public Frame(String observationId,String packageName,int windowId,int displayId,
                     String backgroundGeneration,int windowType,boolean metadataObserved,
                     boolean nodesTruncated,List<Node> nodes){
            this.observationId=observationId;this.packageName=packageName;this.windowId=windowId;
            this.displayId=displayId;this.backgroundGeneration=backgroundGeneration;
            this.windowType=windowType;this.metadataObserved=metadataObserved;this.nodesTruncated=nodesTruncated;
            this.nodes=nodes==null?null:Collections.unmodifiableList(new ArrayList<Node>(nodes));
        }
    }
    public static final class Node {
        public final String id,packageName,text,label,viewId,inputTextSha256;
        public final int left,top,right,bottom;
        public final boolean editable,clickable,scrollable,enabled,password;
        public final ObservedChildText.Result childText;
        public final String observedAppTreeSignature;
        private final boolean boundsKnown;
        /** label is the complete original display label, before the existing 36-unit projection.
         * For unavailable/truncated derived child text the bridge must supply an empty label. */
        public Node(String id,String packageName,String text,String label,String viewId,String inputTextSha256,
                    int[] bounds,boolean editable,boolean clickable,boolean scrollable,boolean enabled,boolean password){
            this(id,packageName,text,label,viewId,inputTextSha256,bounds,editable,clickable,scrollable,enabled,password,ObservedChildText.notApplicable(),null);
        }
        public Node(String id,String packageName,String text,String label,String viewId,String inputTextSha256,
                    int[] bounds,boolean editable,boolean clickable,boolean scrollable,boolean enabled,boolean password,
                    ObservedChildText.Result childText,String observedAppTreeSignature){
            this.id=id;this.packageName=packageName;this.text=text;this.label=label;this.viewId=viewId;
            this.inputTextSha256=inputTextSha256;boundsKnown=bounds!=null&&bounds.length==4;
            left=boundsKnown?bounds[0]:0;top=boundsKnown?bounds[1]:0;
            right=boundsKnown?bounds[2]:0;bottom=boundsKnown?bounds[3]:0;
            this.editable=editable;this.clickable=clickable;this.scrollable=scrollable;
            this.enabled=enabled;this.password=password;
            this.childText=childText==null?ObservedChildText.notApplicable():childText;this.observedAppTreeSignature=observedAppTreeSignature;
        }
        public int[] bounds(){return new int[]{left,top,right,bottom};}
    }
    public static final class Installed {
        public final String packageName;
        public final int uid;
        /** Actual sourceDir hash under "base", and actual split hashes under "split:" + split name. */
        public final Map<String,String> apkHashes;
        public Installed(String packageName,int uid,Map<String,String> apkHashes){
            this.packageName=packageName;this.uid=uid;
            this.apkHashes=apkHashes==null?null:Collections.unmodifiableMap(new LinkedHashMap<String,String>(apkHashes));
        }
    }
    public static final class BodyEvidence {
        public final boolean matched,rawExact,persistentBytesVerified;
        public final String nodeId,actionLabel,rawTextSha256,bodySha256,matchRule,missing;
        public final int trailingLfCount;
        private BodyEvidence(boolean matched,boolean rawExact,Node node,String rawSha,String bodySha,
                             int trailingLfCount,String rule,String missing){
            this.matched=matched;this.rawExact=rawExact;persistentBytesVerified=false;
            nodeId=node==null?null:node.id;
            actionLabel=node==null?null:ObservedTargetLabels.project(node.label);
            rawTextSha256=rawSha;bodySha256=bodySha;this.trailingLfCount=trailingLfCount;
            matchRule=rule;this.missing=missing;
        }
    }
    public static final class Item {
        public final String nodeId,label,fullLabel,text;
        public final int left,top,right,bottom;
        private Item(Node node){
            nodeId=node.id;fullLabel=node.label;label=ObservedTargetLabels.project(node.label);text=node.text;
            left=node.left;top=node.top;right=node.right;bottom=node.bottom;
        }
        public int[] bounds(){return new int[]{left,top,right,bottom};}
    }
    public static final class ListEvidence {
        public final boolean matched;
        public final String missing;
        public final Item item;
        public final String matchRule,sourcePath,sourceViewId,sourceTextSha256,observedAppTreeSignature;
        private ListEvidence(String missing,Node node){
            this(missing,node,null,null);
        }
        private ListEvidence(String missing,Node node,String rule,ObservedChildText.Source source){
            this.missing=missing;matched=missing==null&&node!=null;item=matched?new Item(node):null;
            matchRule=rule;sourcePath=source==null?null:source.descendantPath;sourceViewId=source==null?null:source.viewId;
            sourceTextSha256=source==null?null:source.textSha256;observedAppTreeSignature=node==null?null:node.observedAppTreeSignature;
        }
        public Map<String,Object> evidence(){
            Map<String,Object> o=new LinkedHashMap<String,Object>();o.put("matched",matched);o.put("missing",missing);o.put("match_rule",matchRule);
            o.put("node_id",item==null?null:item.nodeId);o.put("source_path",sourcePath);o.put("source_view_id",sourceViewId);
            o.put("source_text_sha256",sourceTextSha256);o.put("node_app_tree_sha256",observedAppTreeSignature);o.put("text_scope",LIST_TEXT_SCOPE);
            o.put("persistent_bytes_verified",false);return o;
        }
    }

    public static BodyEvidence editor(Frame frame,String body,Installed installed){
        String error=frameError(frame);
        if(error!=null)return absentBody(error,body);
        if(!validBody(body))return absentBody("nonempty_valid_owner_body_required",body);
        if(!installedValid(installed))return absentBody("actual_installed_notes_identity_required",body);
        Node context=null,editor=null;int contexts=0,editors=0;
        for(Node node:frame.nodes){
            if(!NOTES.equals(node.packageName)||!node.enabled||node.password)continue;
            if(!node.editable&&"NoteEditor".equals(node.text)&&node.scrollable&&validBounds(node)){
                context=node;contexts++;
            }
            if(node.editable){editor=node;editors++;}
        }
        if(contexts!=1)return absentBody("unique_observed_NoteEditor_context_required",body);
        if(editors!=1)return absentBody("unique_enabled_nonpassword_editable_required",body);
        if(!validBounds(editor)||!inside(editor,context))return absentBody("editable_outside_observed_editor_bounds",body);
        String rawSha=sha(editor.text),bodySha=sha(body);
        boolean rawExact=body.equals(editor.text);
        boolean observedForty=(body+FORTY_LF).equals(editor.text);
        int lfCount=trailingLf(editor.text);
        String rule=rawExact?"raw_exact":observedForty?"body_plus_observed_40_lf":"unsupported_raw_difference";
        if(!isSha(editor.inputTextSha256)||!rawSha.equals(editor.inputTextSha256))
            return new BodyEvidence(false,rawExact,editor,rawSha,bodySha,lfCount,rule,"complete_input_sha_does_not_match_observed_text");
        if(!rawExact&&!observedForty)
            return new BodyEvidence(false,false,editor,rawSha,bodySha,lfCount,rule,"observed_body_differs_from_supported_forms");
        if(observedForty&&!observedSingleBase(installed))
            return new BodyEvidence(false,false,editor,rawSha,bodySha,lfCount,rule,"forty_lf_form_requires_exact_observed_single_base_apk");
        return new BodyEvidence(true,rawExact,editor,rawSha,bodySha,lfCount,rule,null);
    }

    public static ListEvidence list(Frame frame,String body){
        String error=frameError(frame);
        if(error!=null)return absentList(error);
        if(!validBody(body))return absentList("nonempty_valid_owner_body_required");
        // Native node text is limited to 96 UTF-16 units; child labels may be shorter.
        // A shortened value must never impersonate an entire requested body.
        if(body.length()>=95)return absentList("body_too_long_to_prove_complete_list_item");
        if(body.endsWith("…"))return absentList("body_ending_ellipsis_cannot_prove_unshortened_list_item");
        Node title=null,pager=null;int titles=0,pagers=0;
        for(Node node:frame.nodes){
            if(node.editable||"NoteEditor".equals(node.text))return absentList("editor_present_not_note_list");
            if(!NOTES.equals(node.packageName))continue;
            if((NOTES+":id/no_note_text").equals(node.viewId)&&!node.text.isEmpty())return absentList("empty_list_notice_present");
            if((NOTES+":id/title_text").equals(node.viewId)&&"所有笔记".equals(node.text)
                    &&node.enabled&&!node.password&&validBounds(node)){title=node;titles++;}
            if((NOTES+":id/view_pager2").equals(node.viewId)&&node.scrollable
                    &&node.enabled&&!node.password&&validBounds(node)){pager=node;pagers++;}
        }
        if(titles!=1||pagers!=1)return absentList("unique_all_notes_title_and_scrollable_pager_required");
        Node item=null;int matches=0;String rule=null;ObservedChildText.Source matchedSource=null;
        for(Node node:frame.nodes){
            if(node==title||node==pager||!NOTES.equals(node.packageName)||!node.clickable
                    ||!node.enabled||node.password||!validBounds(node)||!inside(node,pager))continue;
            // The observed header click target is not a saved item, even if the owner
            // happens to request a note whose entire body is the title "所有笔记".
            if((NOTES+":id/clickable_layout").equals(node.viewId))continue;
            boolean ownText=body.equals(node.text)&&node.text.equals(node.label);
            // A derived label can never fall back to a title/date matching the
            // body. Its real summary source and parent binding are mandatory.
            boolean fullLabel=node.text.isEmpty()&&body.equals(node.label)&&!"derived".equals(node.childText.status);
            ObservedChildText.Source source=summarySource(node,body);
            if(ownText||fullLabel||source!=null){item=node;matches++;matchedSource=source;
                rule=source!=null?"bound_note_summary_accessibility_text":ownText?"exact_own_text":"exact_nonderived_label";}
        }
        if(matches==0)return absentList("complete_body_on_one_executable_list_item_missing");
        if(matches!=1)return absentList("complete_body_list_item_is_not_unique");
        // Bounds establish only list scope, never an inferred ancestor link.
        return new ListEvidence(null,item,rule,matchedSource);
    }

    private static ObservedChildText.Source summarySource(Node node,String body){
        ObservedChildText.Result child=node.childText;
        if(!(NOTES+":id/note_item_content").equals(node.viewId)||!node.text.isEmpty()
                ||!"derived".equals(child.status)||child.truncated||!child.sourcesComplete||!node.label.equals(child.text)
                ||child.text.isEmpty()||child.text.length()>ObservedChildText.MAX_CHARACTERS
                ||child.visited<1||child.visited>ObservedChildText.MAX_DESCENDANTS||child.sources.isEmpty()
                ||child.sources.size()>ObservedChildText.MAX_PARTS||!isSha(child.rootSignature)
                ||!isSha(node.observedAppTreeSignature)||!child.bind(child.rootSignature).equals(node.observedAppTreeSignature))return null;
        Set<String> paths=new HashSet<String>();ObservedChildText.Source summary=null;int summaries=0;
        for(ObservedChildText.Source source:child.sources){
            if(source==null||!sourcePath(source.descendantPath)||!paths.add(source.descendantPath)
                    ||!("text".equals(source.property)||"description".equals(source.property))
                    ||!isSha(source.textSha256)||!isSha(source.nodeSignature)||!unicode(source.viewId))return null;
            if((NOTES+":id/note_summary").equals(source.viewId)){
                summaries++;if("text".equals(source.property)&&sha(body).equals(source.textSha256))summary=source;
            }
        }
        return summaries==1?summary:null;
    }
    private static boolean sourcePath(String path){
        if(path==null||!path.matches("[0-9]{1,2}(?:/[0-9]{1,2}){0,3}"))return false;
        for(String part:path.split("/")){
            int index=Integer.parseInt(part);
            if(index>=ObservedChildText.MAX_DESCENDANTS||!Integer.toString(index).equals(part))return false;
        }
        return true;
    }

    private static String frameError(Frame frame){
        if(frame==null)return "actual_frame_required";
        if(!id(frame.observationId)||!NOTES.equals(frame.packageName))return "actual_notes_observation_identity_required";
        if(!frame.metadataObserved||frame.windowType!=1||frame.windowId<0)return "observed_application_window_metadata_required";
        if(frame.displayId<0||(frame.displayId==0?frame.backgroundGeneration!=null:!uuid(frame.backgroundGeneration)))
            return "display_and_background_generation_must_match";
        if(frame.nodesTruncated||frame.nodes==null||frame.nodes.size()>MAX_NODES)return "complete_bounded_observed_nodes_required";
        Set<String> ids=new HashSet<String>();
        for(Node node:frame.nodes){
            if(node==null||node.id==null||!node.id.matches("n[0-9]{1,5}")||!ids.add(node.id))
                return "unique_actual_node_ids_required";
            if(!unicode(node.text)||!unicode(node.label)||!unicode(node.viewId)||!unicode(node.packageName))
                return "valid_raw_node_strings_required";
        }
        return null;
    }
    private static boolean installedValid(Installed installed){
        if(installed==null||!NOTES.equals(installed.packageName)||installed.uid<10000||installed.uid>=90000
                ||installed.apkHashes==null||installed.apkHashes.isEmpty()||installed.apkHashes.size()>128
                ||!isSha(installed.apkHashes.get("base")))return false;
        for(Map.Entry<String,String> entry:installed.apkHashes.entrySet()){
            String key=entry.getKey();
            if(key==null||(!"base".equals(key)&&(!key.startsWith("split:")||key.length()==6))
                    ||key.length()>300||!unicode(key)||!isSha(entry.getValue()))return false;
        }
        return true;
    }
    private static boolean observedSingleBase(Installed installed){
        return installed.apkHashes.size()==1&&OBSERVED_BASE_APK_SHA256.equals(installed.apkHashes.get("base"));
    }
    private static boolean validBounds(Node n){return n.boundsKnown&&n.left>=0&&n.top>=0&&n.right>n.left&&n.bottom>n.top;}
    private static boolean inside(Node n,Node outer){return outer.left<=n.left&&outer.top<=n.top&&n.right<=outer.right&&n.bottom<=outer.bottom;}
    private static boolean validBody(String body){return unicode(body)&&!body.isEmpty()&&body.indexOf('\0')<0;}
    private static boolean id(String value){return value!=null&&value.matches("[0-9a-f]{32}");}
    private static boolean isSha(String value){return value!=null&&value.matches("[0-9a-f]{64}");}
    private static boolean uuid(String value){return value!=null&&value.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");}
    private static boolean unicode(String value){
        if(value==null)return false;
        for(int i=0;i<value.length();i++){
            char c=value.charAt(i);
            if(Character.isHighSurrogate(c)){
                if(i+1>=value.length()||!Character.isLowSurrogate(value.charAt(++i)))return false;
            }else if(Character.isLowSurrogate(c))return false;
        }
        return true;
    }
    private static String sha(String value){
        try{
            byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            char[] hex=new char[64],alphabet="0123456789abcdef".toCharArray();
            for(int i=0;i<bytes.length;i++){hex[2*i]=alphabet[(bytes[i]&255)>>>4];hex[2*i+1]=alphabet[bytes[i]&15];}
            return new String(hex);
        }catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
    private static int trailingLf(String text){int n=0;for(int i=text.length()-1;i>=0&&text.charAt(i)=='\n';i--)n++;return n;}
    private static String fortyLf(){StringBuilder out=new StringBuilder(40);for(int i=0;i<40;i++)out.append('\n');return out.toString();}
    private static BodyEvidence absentBody(String missing,String body){
        return new BodyEvidence(false,false,null,null,validBody(body)?sha(body):null,-1,"unavailable",missing);
    }
    private static ListEvidence absentList(String missing){return new ListEvidence(missing,null);}
}

package org.trillionnium.hepta.local;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Bounded children of an actual model-issued notes.create, not model decisions.
 * The fixed intent still proves only draft_opened. This class never creates a
 * note, types text, chooses an unlabeled control, changes OWNER, or grants a tool.
 * Its IO must use the same live service/phase/scope dispatch gates as model IO. */
public final class NotesCreateWorkflow {
    public static final String SCHEMA="hepta.notes-create-workflow.v1";
    public static final String CHILD_SCHEMA="hepta.tool-child.v1";
    public static final int MAX_BACK=2,MAX_CHILDREN=3;
    public static final long MAX_WORKFLOW_MS=45000;
    private NotesCreateWorkflow(){}

    /** Metadata copied from one actual PhoneObservation, never inferred from text. */
    public static final class Observation {
        public final NotesCompletionEvidence.Frame frame;
        public final String treeSha256;
        public final int rotation;
        public Observation(NotesCompletionEvidence.Frame frame,String treeSha256,int rotation){
            require(frame!=null&&isId(frame.observationId)&&isSha(treeSha256)&&rotation>=0&&rotation<=3,
                    "actual observation identity required");
            this.frame=frame;this.treeSha256=treeSha256;this.rotation=rotation;
        }
        public boolean stableWith(Observation other){
            return other!=null&&frame.packageName.equals(other.frame.packageName)
                    &&frame.windowId==other.frame.windowId&&frame.displayId==other.frame.displayId
                    &&Objects.equals(frame.backgroundGeneration,other.frame.backgroundGeneration)
                    &&rotation==other.rotation&&treeSha256.equals(other.treeSha256);
        }
        public Map<String,Object> evidence(){
            Map<String,Object> o=map();o.put("observation_id",frame.observationId);o.put("package",frame.packageName);
            o.put("window_id",frame.windowId);o.put("display_id",frame.displayId);
            o.put("background_generation",frame.backgroundGeneration);o.put("tree_sha256",treeSha256);o.put("rotation",rotation);return o;
        }
    }

    /** Only the task completion gate mints this after its real parent launch/body.
     * A grant is object-bound and single use; serialized hashes are evidence, not capabilities. */
    public static final class Grant {
        public final String taskId,parentRunId,parentObservationId,createdObservationId,attemptId,workflowId;
        public final String ownerSha256,contractSha256,authorizationSha256,bodySha256;
        public final int parentStep,displayId;
        public final String generation;
        final String body;
        final NotesCompletionEvidence.Installed installed;
        final TaskAuthorization authorization;
        private boolean consumed,retired;
        private int issued;
        private ChildCall current;
        Grant(String task,int step,String run,String beforeId,String afterId,String attempt,
              TaskCompletionGate.Contract contract,TaskAuthorization authorization,
              NotesCompletionEvidence.Installed installed,int display,String generation){
            require(isId(task)&&step>0&&step<=20&&isId(run)&&isId(beforeId)&&isId(afterId)&&isSha(attempt),"parent identity required");
            require(contract!=null&&TaskCompletionGate.NOTES.equals(contract.kind)&&contract.body!=null
                    &&contract.body.length()<95&&authorization!=null&&installed!=null,"supported complete parent contract required");
            taskId=task;parentStep=step;parentRunId=run;parentObservationId=beforeId;createdObservationId=afterId;attemptId=attempt;
            this.authorization=authorization;authorizationSha256=authorization.sha256;ownerSha256=contract.ownerSha256;
            contractSha256=contract.contractSha256;body=contract.body;bodySha256=contract.bodySha256;this.installed=installed;
            displayId=display;this.generation=generation;workflowId=hash(task+"|"+run+"|"+attempt+"|"+contractSha256);
        }
        private synchronized void consume(Observation initial){
            require(!consumed&&!retired&&createdObservationId.equals(initial.frame.observationId),"workflow grant used or wrong initial frame");
            require(authorization.allows("notes.create")&&authorization.allows("back")&&authorization.allows("click"),"workflow child authority missing");
            require(body(initial),"created body required before workflow");consumed=true;
        }
        private synchronized ChildCall issue(String action,Observation before){
            require(consumed&&!retired&&current==null&&issued<MAX_CHILDREN,"workflow child grant unavailable");
            require(domain(before)&&authorization.allows(action),"child outside original owner/domain");
            String node=null,label=null;
            if("back".equals(action))require(body(before),"Back requires current created body");
            else if("click".equals(action)){
                NotesCompletionEvidence.ListEvidence list=list(before);require(list.matched,"unique complete list item required");
                node=list.item.nodeId;label=list.item.label;
            }else throw new IllegalArgumentException("workflow primitive not supported");
            current=new ChildCall(this,++issued,action,before.frame.observationId,node,label);return current;
        }
        private synchronized void finish(ChildCall child){
            require(current==child&&child.grant==this&&!child.finished,"wrong or repeated child completion");
            child.finished=true;current=null;
        }
        private synchronized void retire(){retired=true;}
        private synchronized void requireChild(ChildCall child){
            require(consumed&&!retired&&current==child&&!child.finished,"workflow child retired or replaced");
        }
        boolean domain(Observation o){
            NotesCompletionEvidence.Frame f=o==null?null:o.frame;
            return f!=null&&f.metadataObserved&&f.windowType==1&&f.windowId>=0&&!f.nodesTruncated
                    &&NotesCompletionEvidence.NOTES.equals(f.packageName)&&f.displayId==displayId
                    &&Objects.equals(generation,f.backgroundGeneration)
                    &&(displayId==0?generation==null:displayId>0&&generation!=null&&generation.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"));
        }
        boolean body(Observation o){return domain(o)&&NotesCompletionEvidence.editor(o.frame,body,installed).matched;}
        NotesCompletionEvidence.ListEvidence list(Observation o){return NotesCompletionEvidence.list(o==null?null:o.frame,body);}
        public synchronized Map<String,Object> evidence(){
            Map<String,Object> o=map();o.put("schema",SCHEMA);o.put("workflow_id",workflowId);o.put("task_id",taskId);
            o.put("parent_step",parentStep);o.put("parent_model_run_id",parentRunId);o.put("parent_observation_id",parentObservationId);
            o.put("created_observation_id",createdObservationId);o.put("parent_fixed_intent_attempt_id",attemptId);
            o.put("owner_sha256",ownerSha256);o.put("contract_sha256",contractSha256);o.put("task_authorization_sha256",authorizationSha256);
            o.put("body_sha256",bodySha256);o.put("target_package",installed.packageName);o.put("target_uid",installed.uid);
            o.put("target_apk_sha256",installed.apkHashes);o.put("display_id",displayId);o.put("background_generation",generation);
            o.put("grant_consumed",consumed);o.put("grant_retired",retired);o.put("grants_tool_authority",false);return o;
        }
    }

    /** An internal request cannot be parsed from the model's JSON. The service
     * consumes its entry once and checks it again immediately before each effect. */
    public static final class ChildCall implements ActionDecision.ToolChildOrigin {
        final Grant grant;
        public final int ordinal;
        public final String id,action,observationId,nodeId,nodeLabel;
        private boolean serviceEntered,finished;
        private ChildCall(Grant grant,int ordinal,String action,String observation,String node,String label){
            this.grant=grant;this.ordinal=ordinal;this.action=action;observationId=observation;nodeId=node;nodeLabel=label;
            id=hash(grant.workflowId+"|"+ordinal+"|"+action+"|"+observation+"|"+(node==null?"":node));
        }
        public ActionDecision decision(){return ActionDecision.toolChild(this,action,observationId,NotesCompletionEvidence.NOTES,nodeId,nodeLabel);}
        @Override public void enterService(String task,String authorizationSha,String run,String observation){
            synchronized(grant){
                grant.requireChild(this);require(!serviceEntered&&task.equals(grant.taskId)&&authorizationSha.equals(grant.authorizationSha256)
                        &&run.equals(grant.parentRunId)&&observationId.equals(observation),"child service identity or single-entry gate failed");
                serviceEntered=true;
            }
        }
        @Override public void requireDispatch(String task,String authorizationSha,String run,ActionDecision value){
            synchronized(grant){
                grant.requireChild(this);require(serviceEntered&&value!=null&&value.toolChildOrigin==this
                        &&ActionDecision.TOOL_CHILD_SCHEMA.equals(value.actionSchema)&&task.equals(grant.taskId)
                        &&authorizationSha.equals(grant.authorizationSha256)&&run.equals(grant.parentRunId)
                        &&action.equals(value.action)&&observationId.equals(value.observationId)
                        &&NotesCompletionEvidence.NOTES.equals(value.packageName)&&Objects.equals(nodeId,value.nodeId)
                        &&Objects.equals(nodeLabel,value.nodeLabel),"child dispatch binding changed");
            }
        }
        @Override public Map<String,Object> evidence(){
            synchronized(grant){
                Map<String,Object> o=new LinkedHashMap<String,Object>(grant.evidence());o.put("schema",CHILD_SCHEMA);
                o.put("child_id",id);o.put("child_ordinal",ordinal);o.put("actor_kind","tool_child");o.put("model_issued",false);
                o.put("action",action);o.put("observation_id",observationId);o.put("node_id",nodeId);o.put("node_label",nodeLabel);
                o.put("service_entered",serviceEntered);o.put("automatic_retry_allowed",false);return o;
            }
        }
        private boolean callbackMatches(Dispatch d){
            if(d==null||!d.liveLeaseVerified||d.serviceProof==null||!serviceEntered)return false;
            Map<String,Object> p=d.serviceProof;
            return CHILD_SCHEMA.equals(p.get("schema"))&&"tool_child".equals(p.get("actor_kind"))&&Boolean.FALSE.equals(p.get("model_issued"))
                    &&id.equals(p.get("child_id"))&&grant.workflowId.equals(p.get("workflow_id"))&&grant.taskId.equals(p.get("task_id"))
                    &&grant.parentRunId.equals(p.get("parent_model_run_id"))&&grant.attemptId.equals(p.get("parent_fixed_intent_attempt_id"))
                    &&grant.parentObservationId.equals(p.get("parent_observation_id"))&&grant.createdObservationId.equals(p.get("created_observation_id"))
                    &&number(p.get("parent_step"),grant.parentStep)&&number(p.get("child_ordinal"),ordinal)
                    &&grant.ownerSha256.equals(p.get("owner_sha256"))
