                &&(frame.displayId==0?frame.backgroundGeneration==null:frame.backgroundGeneration!=null&&frame.backgroundGeneration.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"));
