    Map<String,Object> promptEvidence(){
        Map<String,Object> full=evidence(),out=new java.util.LinkedHashMap<String,Object>();
        out.put("schema","hepta.web-domain-model-view.v1");out.put("source","current_independently_verified_web_domain");
        out.put("kind",flight!=null?"csair_public_flight":"mi_public_product");
        out.put("observation_id",observationId);out.put("phase",phase);out.put("current_native_url",url);
        out.put("allowed_click_ids",new java.util.ArrayList<String>(new java.util.TreeSet<String>(clickIds)));
        out.put("exact_edit_values",new java.util.TreeMap<String,String>(editValues));
        java.util.List<Map<String,Object>> controls=new java.util.ArrayList<Map<String,Object>>();
        for(String id:new java.util.TreeSet<String>(clickIds)){
            Map<String,Object> control=new java.util.LinkedHashMap<String,Object>();control.put("node_id",id);
            control.put("purpose",flight!=null?flight.purpose(id):"open_observed_official_product_detail");controls.add(control);
        }
        out.put("current_controls",controls);
        for(String key:new String[]{"next_goal","query_control_withheld","query_attempted","query_executed",
                "server_query_completed","query_retry_permitted","same_frame_public_price_observed","model_navigation_confirmed",
                "result_ready_for_completion_gate","missing"})
            if(full.containsKey(key))out.put(key,full.get(key));
        out.put("current_result_ready",resultReady());out.put("whole_scene_included",false);
        out.put("private_full_evidence_retained",true);out.put("grants_tool_authority",false);
        try{out.put("private_full_evidence_sha256",org.trillionnium.hepta.webprotocol.WebDomCanonical.sha256(new JSONObject(full)));}
        catch(Exception malformed){throw new IllegalStateException("current web domain proof cannot be projected",malformed);}
        return out;
    }
    Set<String> clicks(Set<String> original){return flight!=null?flight.clicks(original):shopping.clicks(original);}
    Set<String> edits(Set<String> original){return flight!=null?flight.edits(original):shopping.edits(original);}
    Set<String> openPackages(Set<String> original){return flight!=null?flight.openPackages(original):shopping.openPackages(original);}
    <T> Map<String,T> noNodeActions(Map<String,T> original){return flight!=null?flight.noNodeActions(original):shopping.noNodeActions(original);}
    Set<String> toolMask(Set<String> original){return flight!=null?flight.toolMask(original):shopping.toolMask(original);}
    void requireCurrent(ActionDecision action){if(flight!=null)flight.requireCurrent(action);else shopping.requireCurrent(action);}
    private static void need(boolean yes,String reason){WebEvidenceJson.need(yes,reason);}
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import java.net.URI;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Data-only interpretation of the observed Csair calendar.
 * No date comes from URL parameters, a requested goal, cell position or "today".
 * This class never maps CSS to pixels, publishes an AX identity or grants a click.
 */
final class CsairCalendar {
    static final String SCHEMA = "hepta.csair-observed-calendar.v1";
    private static final Pattern PATH = Pattern.compile("0(?:/(?:0|[1-9][0-9]{0,4})){0,32}");
    private static final Pattern MONTH = Pattern.compile("([1-9][0-9]{3})年([1-9]|1[0-2])月");
    private static final Pattern DAY = Pattern.compile("[1-9]|[12][0-9]|3[01]");
    private static final Pattern ISO = Pattern.compile("([1-9][0-9]{3})-([0][1-9]|1[0-2])-([0][1-9]|[12][0-9]|3[01])");
    private static final String[] WEEK = {"日","一","二","三","四","五","六"};

    static final class Month {
        final int year,month;
        final String headerText,headerPath,monthPath,dayListPath;
        final boolean zeroHeightDayList;
        final Map<String,Object> headerEvidence;
        Month(Index index,JSONObject header,JSONObject panel,JSONObject list,int y,int m)throws Exception{
            year=y;month=m;headerText=text(header,"text");headerPath=text(header,"path");
            monthPath=text(panel,"path");dayListPath=text(list,"path");
            zeroHeightDayList=index.zeroHeightLayoutList(list);
            headerEvidence=index.nodeEvidence(header);
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();
            out.put("year",year);out.put("month",month);out.put("header_text",headerText);
            out.put("header_dom_path",headerPath);out.put("month_dom_path",monthPath);
            out.put("day_list_dom_path",dayListPath);out.put("zero_height_layout_list",zeroHeightDayList);
            out.put("original_header",headerEvidence);return out;
        }
    }

    static final class DateTarget {
        final int year,month,day;
        final String isoDate,monthHeaderText,monthHeaderPath,monthPath,dayListPath,dayPath,dayText,domId;
        final boolean domDisabled,domVisibleInViewport,zeroHeightDayList;
        final List<Map<String,Object>> originalAncestors;
        DateTarget(Index index,Month observed,JSONObject node,int d)throws Exception{
            year=observed.year;month=observed.month;day=d;
            isoDate=String.format(java.util.Locale.ROOT,"%04d-%02d-%02d",year,month,day);
            monthHeaderText=observed.headerText;monthHeaderPath=observed.headerPath;
            monthPath=observed.monthPath;dayListPath=observed.dayListPath;
            dayPath=text(node,"path");dayText=text(node,"text");domId=text(node,"id");
            domDisabled=index.disabledThrough(node);domVisibleInViewport=flag(node,"visible_in_viewport");
            zeroHeightDayList=observed.zeroHeightDayList;
            originalAncestors=index.ancestry(node);
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();
            out.put("year",year);out.put("month",month);out.put("day",day);out.put("iso_date",isoDate);
            out.put("month_header_text",monthHeaderText);out.put("month_header_dom_path",monthHeaderPath);
            out.put("month_dom_path",monthPath);out.put("day_list_dom_path",dayListPath);
            out.put("day_dom_path",dayPath);out.put("day_dom_tag","li");out.put("day_dom_id",domId);
            out.put("observed_day_text",dayText);out.put("dom_disabled",domDisabled);
            out.put("dom_visible_in_viewport",domVisibleInViewport);
            out.put("zero_height_layout_list",zeroHeightDayList);out.put("original_dom_ancestors",originalAncestors);
            out.put("native_visibility_verified",false);out.put("native_action_click_verified",false);
            out.put("css_to_screen_mapping_verified",false);out.put("selected_date_verified",false);
            out.put("grants_tool_authority",false);return out;
        }
    }

    static final class Selection {
        final boolean ready;
        final String reason,requestedIsoDate;
        final DateTarget target;
        Selection(String requested,DateTarget observed,String why){
            requestedIsoDate=requested;target=observed;
            ready=observed!=null&&!observed.domDisabled;reason=why;
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();
            out.put("requested_iso_date",requestedIsoDate);out.put("exact_date_metadata_ready",ready);
            out.put("reason",reason);out.put("observed_target",target==null?null:target.evidence());
            out.put("selected_date_verified",false);out.put("query_ready_verified",false);
            out.put("grants_tool_authority",false);return out;
        }
    }

    final String titlePath,pagePath,weekdaysPath,calendarViewportPath,monthsPath;
    final boolean headerOnly;
    final List<Month> months;
    final List<DateTarget> dates;
    private CsairCalendar(String title,String page,String week,String viewport,String holder,
            List<Month> observedMonths,List<DateTarget> observedDates){
        titlePath=title;pagePath=page;weekdaysPath=week;calendarViewportPath=viewport;monthsPath=holder;
        months=Collections.unmodifiableList(new ArrayList<Month>(observedMonths));
        dates=Collections.unmodifiableList(new ArrayList<DateTarget>(observedDates));
        headerOnly=months.isEmpty();
    }

    /** Non-calendar official routes return null; malformed recognized calendars fail closed. */
    static CsairCalendar read(JSONObject dom)throws Exception{
        URI uri=new URI(text(dom,"href"));
        need("https".equals(uri.getScheme())&&"m.csair.com".equals(uri.getHost())
                &&uri.getRawUserInfo()==null&&(uri.getPort()==-1||uri.getPort()==443)
                &&"https://m.csair.com".equals(text(dom,"origin")),"official Csair document required");
        String fragment=uri.getRawFragment();
        if(!"/booking_new/".equals(uri.getRawPath())||fragment==null
                ||!("/newCalendar".equals(fragment)||fragment.startsWith("/newCalendar?")))return null;
        need("complete".equals(text(dom,"ready_state")),"complete calendar document required");
        Index index=new Index(dom);
        List<JSONObject> appRoots=index.match("div","root",null);
        need(appRoots.size()==1&&index.visibleThrough(appRoots.get(0),null),"one observed app root required");
        JSONObject app=appRoots.get(0);
        List<JSONObject> titles=index.texts("div","选择日期",text(app,"path"));
        need(titles.size()==1&&index.visibleThrough(titles.get(0),null),"one visible calendar title required");
        JSONObject title=titles.get(0),bar=index.parent(title,"div"),header=index.parent(bar,"div");
        JSONObject page=index.parent(header,"div"),shell=index.parent(page,"div");
        need(index.parent(shell,"div")==app&&text(title,"path").equals(text(bar,"path")+"/1")
                &&text(bar,"path").equals(text(header,"path")+"/0")
                &&text(header,"path").equals(text(page,"path")+"/0"),"observed calendar title ancestry differs");
        JSONObject body=index.require(text(page,"path")+"/1","div");
        JSONObject weekHolder=index.require(text(body,"path")+"/0","div");
        JSONObject week=index.require(text(weekHolder,"path")+"/0","ul");
        need(index.layoutListVisible(week)&&index.visibleThrough(weekHolder,null),
                "observed weekday row container required");
        List<JSONObject> weekDays=index.children(week);
        need(weekDays.size()==7,"exact seven weekday labels required");
        for(int i=0;i<WEEK.length;i++){
            JSONObject n=weekDays.get(i);
            need("li".equals(text(n,"tag"))&&WEEK[i].equals(text(n,"text"))
                    &&text(n,"path").equals(text(week,"path")+"/"+i)
                    &&index.visibleThrough(n,text(week,"path")),"actual ordered weekday row differs");
        }
        JSONObject viewport=index.require(text(body,"path")+"/2","div");
        JSONObject holder=index.require(text(viewport,"path")+"/0","div");
        List<Month> months=new ArrayList<Month>();List<DateTarget> dates=new ArrayList<DateTarget>();
        Set<String> monthKeys=new LinkedHashSet<String>(),dateKeys=new LinkedHashSet<String>();
        List<JSONObject> panels=index.children(holder);
        need(panels.size()<=24,"bounded calendar month panels required");
        for(JSONObject panel:panels){
            need("div".equals(text(panel,"tag")),"calendar month panel tag differs");
            List<JSONObject> children=index.children(panel);
            need(children.size()==2&&"h1".equals(text(children.get(0),"tag"))
                    &&"ul".equals(text(children.get(1),"tag")),"actual month header/list structure required");
            JSONObject h=children.get(0),list=children.get(1);
            if(!index.visibleThrough(h,null))continue;
            Matcher match=MONTH.matcher(text(h,"text"));
            need(match.matches(),"visible month must contain explicit year and month");
            int y=Integer.parseInt(match.group(1)),m=Integer.parseInt(match.group(2));
            need(monthKeys.add(y+"-"+m),"duplicate visible year-month heading");
            need(index.layoutListVisible(list),"day-list layout not covered by actual observed structure");
            Month observed=new Month(index,h,panel,list,y,m);months.add(observed);
            List<JSONObject> days=index.children(list);need(days.size()<=42,"bounded month grid required");
            for(JSONObject day:days){
                need("li".equals(text(day,"tag")),"month grid has an unreviewed direct child");
                if(!index.visibleThrough(day,text(list,"path")))continue;
                String label=text(day,"text");
                // Blank leading cells, holiday words and "today" do not establish a numeric date.
                if(!DAY.matcher(label).matches())continue;
                int number=Integer.parseInt(label);need(number<=daysInMonth(y,m),"invalid literal calendar day");
                DateTarget value=new DateTarget(index,observed,day,number);
                need(dateKeys.add(value.isoDate),"duplicate visible exact date");
                dates.add(value);
            }
        }
        // A visible heading elsewhere cannot silently be attached to a different month grid.
        for(JSONObject h:index.match("h1",null,text(app,"path"))){
            if(index.visibleThrough(h,null))need(text(h,"path").startsWith(text(holder,"path")+"/"),
                    "visible calendar heading is outside the observed month container");
        }
        return new CsairCalendar(text(title,"path"),text(page,"path"),text(week,"path"),
                text(viewport,"path"),text(holder,"path"),months,dates);
    }

    Selection forDate(String iso)throws Exception{
        need(iso!=null,"explicit requested date required");Matcher match=ISO.matcher(iso);
        need(match.matches(),"canonical requested yyyy-mm-dd required");
        int y=Integer.parseInt(match.group(1)),m=Integer.parseInt(match.group(2)),d=Integer.parseInt(match.group(3));
        need(d<=daysInMonth(y,m),"invalid requested calendar date");
        DateTarget target=null;
        for(DateTarget value:dates)if(value.year==y&&value.month==m&&value.day==d){
            need(target==null,"ambiguous exact target date");target=value;
        }
        if(target==null)return new Selection(iso,null,headerOnly?"recognized_calendar_header_only":"requested_literal_date_not_observed");
        return new Selection(iso,target,target.domDisabled?"observed_target_dom_disabled":"explicit_literal_year_month_day_observed");
    }

    Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema",SCHEMA);
        out.put("recognized_calendar",true);out.put("recognized_but_not_ready",headerOnly);
        out.put("title_dom_path",titlePath);out.put("page_dom_path",pagePath);out.put("weekdays_dom_path",weekdaysPath);
        out.put("calendar_viewport_dom_path",calendarViewportPath);out.put("months_dom_path",monthsPath);
        List<Map<String,Object>> observedMonths=new ArrayList<Map<String,Object>>();
        for(Month value:months)observedMonths.add(value.evidence());
        List<Map<String,Object>> observedDates=new ArrayList<Map<String,Object>>();
        for(DateTarget value:dates)observedDates.add(value.evidence());
        out.put("observed_months",observedMonths);out.put("observed_literal_dates",observedDates);
        out.put("url_date_used_as_evidence",false);out.put("relative_today_inferred",false);
        out.put("native_visibility_verified",false);out.put("selected_date_verified",false);
        out.put("query_ready_verified",false);out.put("grants_tool_authority",false);return out;
    }

    private static final class Index {
        final Map<String,JSONObject> nodes=new LinkedHashMap<String,JSONObject>();
        Index(JSONObject dom)throws Exception{
            String schema=text(dom,"schema");
            need("hepta.fixed-top-document-dom.v2".equals(schema)||"hepta.fixed-top-document-dom.v3".equals(schema)||"hepta.fixed-top-document-dom.v4".equals(schema),
                    "actual fixed observer v2/v3 DOM required");
            need(!flag(dom,"truncated")&&dom.getJSONArray("truncation_reasons").length()==0,"complete DOM required");
            JSONArray rows=dom.getJSONArray("nodes");need(rows.length()>0&&rows.length()<=1024,"bounded DOM nodes");
            Object visited=dom.get("visited");
            need((visited instanceof Integer||visited instanceof Long)&&((Number)visited).longValue()==rows.length(),
                    "complete visited/node count required");
            for(int i=0;i<rows.length();i++){
                JSONObject n=rows.getJSONObject(i);String path=text(n,"path");
                need(PATH.matcher(path).matches()&&!nodes.containsKey(path),"unique canonical DOM paths");
                need(text(n,"tag").matches("[a-z][a-z0-9:-]{0,63}"),"DOM tag shape");
                for(String key:new String[]{"id","role","name","aria_label","text"})text(n,key);
                flag(n,"visible_in_viewport");flag(n,"disabled");flag(n,"iframe_contents_read");
                need(n.get("aria_disabled")==JSONObject.NULL||n.get("aria_disabled") instanceof String,"aria-disabled type");
                rectangle(n);nodes.put(path,n);
            }
            need(nodes.containsKey("0")&&"html".equals(text(nodes.get("0"),"tag")),"actual document root");
            for(JSONObject n:nodes.values()){
                String path=text(n,"path");Object parent=n.get("parent_path");
                if("0".equals(path))need(parent==JSONObject.NULL,"root parent");
                else need(parent instanceof String&&nodes.containsKey(parent)
                        &&path.substring(0,path.lastIndexOf('/')).equals(parent),"complete direct ancestry");
            }
        }
        JSONObject require(String path,String tag)throws Exception{
            JSONObject n=nodes.get(path);need(n!=null&&tag.equals(text(n,"tag")),"expected calendar node: "+path);return n;
        }
        JSONObject parent(JSONObject node,String tag)throws Exception{return require(text(node,"parent_path"),tag);}
        List<JSONObject> children(JSONObject parent)throws Exception{
            String path=text(parent,"path");List<JSONObject> out=new ArrayList<JSONObject>();
            for(JSONObject n:nodes.values())if(path.equals(n.get("parent_path")))out.add(n);
            for(int i=0;i<out.size();i++)need(text(out.get(i),"path").equals(path+"/"+i),"ordered complete direct children");
            return out;
        }
        List<JSONObject> match(String tag,String id,String ancestor)throws Exception{
            List<JSONObject> out=new ArrayList<JSONObject>();
            for(JSONObject n:nodes.values())if(tag.equals(text(n,"tag"))&&(id==null||id.equals(text(n,"id")))
                    &&(ancestor==null||text(n,"path").startsWith(ancestor+"/")))out.add(n);
            return out;
        }
        List<JSONObject> texts(String tag,String value,String ancestor)throws Exception{
            List<JSONObject> out=new ArrayList<JSONObject>();
            for(JSONObject n:match(tag,null,ancestor))if(value.equals(text(n,"text"))&&visibleThrough(n,null))out.add(n);
            return out;
        }
        boolean zeroHeightLayoutList(JSONObject n)throws Exception{
            double[] r=rectangle(n);
            return "ul".equals(text(n,"tag"))&&!flag(n,"visible_in_viewport")
                    &&r[2]>r[0]&&r[3]==r[1]&&text(n,"text").isEmpty();
        }
        boolean layoutListVisible(JSONObject n)throws Exception{
            return (flag(n,"visible_in_viewport")&&positive(n))||zeroHeightLayoutList(n);
        }
        boolean visibleThrough(JSONObject node,String singleLayoutList)throws Exception{
            JSONObject cursor=node;
            while(cursor!=null){
                boolean exception=text(cursor,"path").equals(singleLayoutList)&&zeroHeightLayoutList(cursor);
                if(!exception&&(!flag(cursor,"visible_in_viewport")||!positive(cursor)))return false;
                Object p=cursor.get("parent_path");cursor=p instanceof String?nodes.get(p):null;
            }
            return true;
        }
        boolean disabledThrough(JSONObject node)throws Exception{
            JSONObject cursor=node;
            while(cursor!=null){
                if(flag(cursor,"disabled")||"true".equals(cursor.get("aria_disabled")))return true;
                Object p=cursor.get("parent_path");cursor=p instanceof String?nodes.get(p):null;
            }
            return false;
        }
        List<Map<String,Object>> ancestry(JSONObject node)throws Exception{
            List<Map<String,Object>> out=new ArrayList<Map<String,Object>>();JSONObject cursor=node;
            while(cursor!=null){out.add(nodeEvidence(cursor));Object p=cursor.get("parent_path");cursor=p instanceof String?nodes.get(p):null;}
            Collections.reverse(out);return Collections.unmodifiableList(out);
        }
        Map<String,Object> nodeEvidence(JSONObject n)throws Exception{
            Map<String,Object> out=new LinkedHashMap<String,Object>();
            for(String k:new String[]{"path","tag","id","text"})out.put(k,text(n,k));
            out.put("parent_path",n.get("parent_path")==JSONObject.NULL?null:n.get("parent_path"));
            out.put("visible_in_viewport",flag(n,"visible_in_viewport"));out.put("disabled",flag(n,"disabled"));
            out.put("aria_disabled",n.get("aria_disabled")==JSONObject.NULL?null:n.get("aria_disabled"));
            double[] rect=rectangle(n);List<Double> values=new ArrayList<Double>();
            for(double value:rect)values.add(Double.valueOf(value));
            out.put("original_rect_css_pixels",Collections.unmodifiableList(values));
            return Collections.unmodifiableMap(out);
        }
        boolean positive(JSONObject n)throws Exception{double[] r=rectangle(n);return r[2]>r[0]&&r[3]>r[1];}
    }
    private static double[] rectangle(JSONObject n)throws Exception{
        JSONArray raw=n.getJSONArray("rect_css_pixels");need(raw.length()==4,"four original DOM rect values");
        double[] out=new double[4];
        for(int i=0;i<4;i++){Object value=raw.get(i);need(value instanceof Number,"numeric DOM rect");
            out[i]=((Number)value).doubleValue();need(!Double.isNaN(out[i])&&!Double.isInfinite(out[i])
                    &&Math.abs(out[i])<=1000000,"finite bounded original DOM rect");}
        need(out[2]>=out[0]&&out[3]>=out[1],"ordered original DOM rect");return out;
    }
    private static int daysInMonth(int year,int month){
        need(month>=1&&month<=12,"month range");
        if(month==2)return year%4==0&&(year%100!=0||year%400==0)?29:28;
        return month==4||month==6||month==9||month==11?30:31;
    }
    private static String text(JSONObject n,String key)throws Exception{
        Object value=n.get(key);need(value instanceof String&&((String)value).length()<=4096,"bounded string: "+key);
        return (String)value;
    }
    private static boolean flag(JSONObject n,String key)throws Exception{
        Object value=n.get(key);need(value instanceof Boolean,"boolean: "+key);return value==Boolean.TRUE;
    }
    private static void need(boolean ok,String message){if(!ok)throw new IllegalArgumentException(message);}
}

package org.trillionnium.hepta.local;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One lease's actual model selection and one public-query attempt.
 * The only constructors are fed by the original executor outcome and fresh
 * captured domains. A requested city/year or a planned click is never readback.
 */
final class WebFlightProgress {
    static final String QUERY="submit_public_flight_query_once";
    private final WebFlightDomain anchor;
    private final Confirmation departure,arrival,date;
    private final Pending pending;
    private final Query query;

    private WebFlightProgress(WebFlightDomain anchor,Confirmation departure,Confirmation arrival,
                              Confirmation date,Pending pending,Query query){
        this.anchor=anchor;this.departure=departure;this.arrival=arrival;
        this.date=date;this.pending=pending;this.query=query;
    }
    static WebFlightProgress begin(WebFlightDomain frame){
        need(frame!=null,"actual flight domain required");
        return new WebFlightProgress(frame,null,null,null,null,null);
    }
    boolean matches(WebFlightDomain frame){
        return frame!=null&&anchor.taskId.equals(frame.taskId)&&anchor.ownerSha.equals(frame.ownerSha)
                &&anchor.contractSha.equals(frame.contractSha)&&anchor.authorizationSha.equals(frame.authorizationSha)
                &&anchor.bindingSha.equals(frame.bindingSha)&&anchor.generation.equals(frame.generation)
                &&anchor.instance.equals(frame.instance)&&anchor.displayId==frame.displayId
                &&anchor.windowId==frame.windowId&&frame.epoch>=anchor.epoch;
    }
    boolean hasConfirmedCities(){return departure!=null&&arrival!=null;}
    boolean selectionPending(){return pending!=null;}
    boolean queryAttempted(){return query!=null;}
    boolean queryDispatched(){return query!=null&&query.outcomeObserved&&query.nativeCallEntered
            &&query.accepted&&query.dispatched&&!query.stale;}
    boolean selectionConfirmed(String kind,WebFlightDomain now){
        need(matches(now),"selection belongs to another flight lease");
        Confirmation value="departure".equals(kind)?departure:"arrival".equals(kind)?arrival:date;
        return value!=null&&now.form!=null&&now.nativeValueMatches(kind)
                &&literalMatches(kind,now)&&now.captureStarted>=value.afterCaptureStarted&&now.epoch>=value.afterEpoch;
    }
    boolean queryReady(WebFlightDomain now){
        return matches(now)&&pending==null&&query==null&&now.form!=null
                &&now.form.adults==1&&now.form.children==0&&now.form.infants==0
                &&selectionConfirmed("departure",now)&&selectionConfirmed("arrival",now)
                &&selectionConfirmed("date",now)&&now.queryCandidate!=null;
    }
    /** Saved durably by the caller before any possible native query invocation. */
    WebFlightProgress reserveQuery(WebFlightDomain before,ActionDecision action,String run){
        need(matches(before)&&queryReady(before)&&pending==null,"actual flight selections are not query-ready");
        before.requireCurrent(action);
        need("click".equals(action.action)&&QUERY.equals(before.purpose(action.nodeId))
                &&run!=null&&run.matches("[0-9a-f]{32}"),"one model-bound query control required");
        return new WebFlightProgress(anchor,departure,arrival,date,null,new Query(before,action,run));
    }
    boolean isQueryAction(ActionDecision action,String run){
        return query!=null&&action!=null&&query.run.equals(run)&&"click".equals(action.action)
                &&query.before.observationId.equals(action.observationId)&&query.action.nodeId.equals(action.nodeId);
    }
    boolean reservedFor(WebFlightDomain before,ActionDecision action,String run){
        return query!=null&&!query.outcomeObserved&&matches(before)&&query.run.equals(run)
                &&query.before.observationId.equals(before.observationId)
                &&query.action.nodeId.equals(action.nodeId)&&"click".equals(action.action);
    }
    /** This consumes the actual result, including false/unknown dispatch facts. */
    WebFlightProgress outcome(WebFlightDomain before,ActionDecision action,String run,
            boolean accepted,boolean dispatched,boolean stale,boolean nativeQueryCallEntered,long start,long end){
        need(matches(before)&&action!=null&&run!=null&&run.matches("[0-9a-f]{32}")
                &&before.observationId.equals(action.observationId)
                &&before.captureEnded>=0&&before.captureEnded<=start&&start<=end,
                "actual same-lease model dispatch and monotonic clocks required");
        if(!"click".equals(action.action))return this;
        before.requireCurrent(action);
        String purpose=before.purpose(action.nodeId);
        need(purpose!=null,"actual observed flight capability required");
        if(QUERY.equals(purpose)){
            need(reservedFor(before,action,run),"query reservation missing or already consumed");
            need(!accepted||nativeQueryCallEntered,"accepted query requires actual native call entry");
            return new WebFlightProgress(anchor,departure,arrival,date,null,
                    new Query(query,accepted,dispatched,stale,nativeQueryCallEntered,start,end));
        }
        need(query==null,"no page action after a query attempt");
        if(!accepted||!dispatched||stale)return this;
        String kind=selectionKind(purpose);
        if(kind!=null){
            need(pending==null,"prior flight selection has no actual readback yet");
            if("date".equals(kind))need(hasConfirmedCities()
                    &&before.goal.departureDate.toString().equals(before.capability(action.nodeId).get("observed_iso_date"))
                    &&Boolean.TRUE.equals(before.capability(action.nodeId).get("native_parent_relationship_claimed")),
                    "full literal calendar date and actual native month/list relation required");
            return new WebFlightProgress(anchor,departure,arrival,"date".equals(kind)?date:null,
                    new Pending(before,action,run,kind,start,end),null);
        }
        // Reopening a field invalidates its older confirmation even if the next
        // page has not loaded. An old year cannot survive a new date edit.
        if("choose_departure_city".equals(purpose))
            return new WebFlightProgress(anchor,null,arrival,null,null,null);
        if("choose_arrival_city".equals(purpose))
            return new WebFlightProgress(anchor,departure,null,null,null,null);
        if("choose_departure_date".equals(purpose))
            return new WebFlightProgress(anchor,departure,arrival,null,null,null);
        return this;
    }
    /** Fresh capture only. No click, retry, URL construction or OWNER rewriting. */
    WebFlightProgress observed(WebFlightDomain now){
        need(matches(now),"flight progress cannot move to another lease, window or identity");
        if(now.captureStarted<0)return this;
        if(query!=null){
            if(query.outcomeObserved&&query.after==null&&now.captureStarted>=query.end)
                return new WebFlightProgress(anchor,departure,arrival,date,null,new Query(query,now));
            return this;
        }
        Confirmation dep=departure,arr=arrival,day=date;
        if(now.form!=null){
            if(dep!=null&&!literalMatches("departure",now))dep=null;
            if(arr!=null&&!literalMatches("arrival",now))arr=null;
            if(day!=null&&!literalMatches("date",now))day=null;
        }
        Pending wait=pending;
        if(wait!=null&&now.form!=null&&now.captureStarted>=wait.end&&now.epoch>=wait.before.epoch
                &&now.nativeValueMatches(wait.kind)&&literalMatches(wait.kind,now)){
            Confirmation confirmed=new Confirmation(wait,now);
            if("departure".equals(wait.kind))dep=confirmed;
            else if("arrival".equals(wait.kind))arr=confirmed;
            else day=confirmed;
            wait=null;
        }
        if(dep==departure&&arr==arrival&&day==date&&wait==pending)return this;
        return new WebFlightProgress(anchor,dep,arr,day,wait,null);
    }
    Map<String,Object> evidence(WebFlightDomain now){
        need(matches(now),"flight evidence scope");
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("schema","hepta.csair-model-query-progress.v1");
        out.put("task_id",anchor.taskId);out.put("owner_sha256",anchor.ownerSha);
        out.put("contract_sha256",anchor.contractSha);out.put("authorization_sha256",anchor.authorizationSha);
        out.put("binding_sha256",anchor.bindingSha);out.put("background_generation",anchor.generation);
        out.put("webview_instance",anchor.instance);out.put("display_id",anchor.displayId);out.put("window_id",anchor.windowId);
        out.put("departure_selection",departure==null?null:departure.evidence);
        out.put("arrival_selection",arrival==null?null:arrival.evidence);
        out.put("complete_date_selection",date==null?null:date.evidence);
        out.put("selection_readback_pending",pending==null?null:pending.evidence);
        out.put("current_departure_value_verified",selectionConfirmed("departure",now));
        out.put("current_arrival_value_verified",selectionConfirmed("arrival",now));
        out.put("current_complete_date_verified",selectionConfirmed("date",now));
        out.put("query_ready",queryReady(now));out.put("query_attempted",queryAttempted());
        out.put("query_native_dispatch_confirmed",queryDispatched());
        out.put("query_attempt",query==null?null:query.evidence());
        out.put("query_retry_permitted",false);out.put("results_verified",false);
        out.put("business_verified",false);out.put("grants_tool_authority",false);
        return Collections.unmodifiableMap(out);
    }
    private boolean literalMatches(String kind,WebFlightDomain now){
        if(now.form==null)return false;
        if("departure".equals(kind))return anchor.goal.fromCity.equals(now.form.departureCityLiteral);
        if("arrival".equals(kind))return anchor.goal.toCity.equals(now.form.arrivalCityLiteral);
        return "date".equals(kind)&&now.form.displayedMonth!=null&&now.form.displayedDay!=null
                &&now.form.displayedMonth.intValue()==anchor.goal.departureDate.getMonthValue()
                &&now.form.displayedDay.intValue()==anchor.goal.departureDate.getDayOfMonth()
                &&(now.form.displayedWeekday==null||weekday(anchor.goal.departureDate.getDayOfWeek().getValue()).equals(now.form.displayedWeekday)
                        ||anchor.goal.departureDate.getDayOfWeek().getValue()==7&&"周天".equals(now.form.displayedWeekday));
    }
    private static String weekday(int day){return "周"+new String[]{"一","二","三","四","五","六","日"}[day-1];}
    private static String selectionKind(String purpose){
        if("choose_departure_city_from_immutable_owner".equals(purpose))return "departure";
        if("choose_arrival_city_from_immutable_owner".equals(purpose))return "arrival";
        if("choose_departure_date_from_immutable_owner".equals(purpose))return "date";
        return null;
    }
    private static final class Pending {
        final WebFlightDomain before;final ActionDecision action;final String run,kind;final long start,end;
        final Map<String,Object> evidence;
        Pending(WebFlightDomain before,ActionDecision action,String run,String kind,long start,long end){
            this.before=before;this.action=action;this.run=run;this.kind=kind;this.start=start;this.end=end;
            Map<String,Object> out=dispatch(before,action,run,start,end);
            out.put("selection_kind",kind);out.put("accepted",true);out.put("dispatched",true);out.put("stale",false);
            out.put("source_capability",before.capability(action.nodeId));
            out.put("after_form_verified",false);evidence=Collections.unmodifiableMap(out);
        }
    }
    private static final class Confirmation {
        final long afterCaptureStarted,afterEpoch;final Map<String,Object> evidence;
        Confirmation(Pending pending,WebFlightDomain after){
            afterCaptureStarted=after.captureStarted;afterEpoch=after.epoch;
            Map<String,Object> out=new LinkedHashMap<String,Object>(pending.evidence);
            out.put("after_observation_id",after.observationId);out.put("after_dom_sha256",after.domSha);
            out.put("after_native_url",after.url);out.put("after_navigation_epoch",after.epoch);
            out.put("after_capture_started_elapsed_ms",after.captureStarted);
            out.put("after_form_verified",true);out.put("native_field_readback",after.nativeReadbacks.get(pending.kind));
            out.put("selected_literal_value","departure".equals(pending.kind)?after.form.departureCityLiteral:
                    "arrival".equals(pending.kind)?after.form.arrivalCityLiteral:
                            pending.before.goal.departureDate.toString());
            out.put("displayed_year",null);
            out.put("year_source","date".equals(pending.kind)?"actual_clicked_calendar_month_header":null);
            out.put("year_from_url_or_today",false);evidence=Collections.unmodifiableMap(out);
        }
    }
    private static final class Query {
        final WebFlightDomain before,after;final ActionDecision action;final String run;
        final boolean outcomeObserved,accepted,dispatched,stale,nativeCallEntered;final long start,end;
        Query(WebFlightDomain before,ActionDecision action,String run){
            this.before=before;this.action=action;this.run=run;after=null;outcomeObserved=false;
            accepted=false;dispatched=false;stale=false;nativeCallEntered=false;start=-1;end=-1;
        }
        Query(Query original,boolean accepted,boolean dispatched,boolean stale,boolean entered,long start,long end){
            before=original.before;action=original.action;run=original.run;after=null;outcomeObserved=true;
            this.accepted=accepted;this.dispatched=dispatched;this.stale=stale;nativeCallEntered=entered;this.start=start;this.end=end;
        }
        Query(Query original,WebFlightDomain after){
            before=original.before;action=original.action;run=original.run;this.after=after;outcomeObserved=original.outcomeObserved;
            accepted=original.accepted;dispatched=original.dispatched;stale=original.stale;
            nativeCallEntered=original.nativeCallEntered;start=original.start;end=original.end;
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=dispatch(before,action,run,start,end);
            out.put("source","actual_controller_query_reservation_and_executor_outcome");
            out.put("reservation_consumed",true);out.put("outcome_observed",outcomeObserved);
            out.put("native_action_click_call_entered",nativeCallEntered);
            out.put("accepted",outcomeObserved?Boolean.valueOf(accepted):null);
            out.put("dispatched",outcomeObserved?Boolean.valueOf(dispatched):null);
            out.put("stale",outcomeObserved?Boolean.valueOf(stale):null);
            out.put("before_verified_form",before.form.evidence());
            out.put("before_selection_chain",before.progressEvidence());
            out.put("query_control",before.capability(action.nodeId));
            out.put("after_observation_id",after==null?null:after.observationId);
            out.put("after_native_url",after==null?null:after.url);
            out.put("after_navigation_epoch",after==null?null:Long.valueOf(after.epoch));
            out.put("after_dom_sha256",after==null?null:after.domSha);
            out.put("after_capture_started_elapsed_ms",after==null?null:Long.valueOf(after.captureStarted));
            out.put("server_query_completed",false);out.put("flight_results_verified",false);
            return Collections.unmodifiableMap(out);
        }
    }
    private static Map<String,Object> dispatch(WebFlightDomain before,ActionDecision action,String run,long start,long end){
        Map<String,Object> out=new LinkedHashMap<String,Object>();
        out.put("model_run_id",run);out.put("model_issued",true);out.put("action",action.action);out.put("node_id",action.nodeId);
        out.put("before_observation_id",before.observationId);out.put("before_dom_sha256",before.domSha);
        out.put("before_native_url",before.url);out.put("before_navigation_epoch",before.epoch);
        out.put("before_capture_ended_elapsed_ms",before.captureEnded);
        out.put("dispatch_before_elapsed_ms",start<0?null:Long.valueOf(start));
        out.put("dispatch_after_elapsed_ms",end<0?null:Long.valueOf(end));
        return out;
    }
    private static void need(boolean yes,String reason){WebEvidenceJson.need(yes,reason);}
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.webprotocol.WebDomCanonical;
import org.trillionnium.hepta.webprotocol.WebEvidenceProtocol;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * A compiled, homepage-only booking predicate. It is neither a general
 * stable-tree waiver nor an action executor. The service keeps the original
 * NodeRef and all ordinary authority, freshness and platform-action checks.
 */
final class WebFlightNativeStability {
    static final String PURPOSE="open_public_booking_form";
    static final String LABEL="机票预订按钮，点按两次即可激活";
    static final int MAX_NATIVE_NODES=512;
    private WebFlightNativeStability(){}

    static final class Permit {
        final PhoneObservation frame;
        final String taskId,targetId,targetPath,run,actionKey,bindingSha,instance;
        final int displayId,windowId;
        final long epoch;
        private final int[] targetBounds;
        private final String domProof;
        private Permit(WebTaskDomain domain,PhoneObservation frame,PhoneObservation.Node target,
                       String run,ActionDecision action,WebEvidenceReceipt receipt,JSONObject proof)throws Exception{
            this.frame=frame;taskId=domain.taskId;targetId=target.id;targetPath=target.nativeTreePath;
            this.run=run;actionKey=key(action);bindingSha=receipt.bindingSha;instance=receipt.instance;
            displayId=receipt.displayId;windowId=receipt.windowId;epoch=receipt.epoch;
            targetBounds=new int[]{target.bounds.left,target.bounds.top,target.bounds.right,target.bounds.bottom};
            domProof=WebDomCanonical.canonical(proof);
        }
        int[] bounds(){return targetBounds.clone();}
        JSONObject domEvidence()throws Exception{return new JSONObject(domProof);}
        boolean matches(PhoneObservation current,ActionDecision action,String actualRun){
            return frame==current&&run.equals(actualRun)&&actionKey.equals(key(action))
                    &&targetId.equals(action.nodeId)&&frame.id.equals(action.observationId);
        }
    }

    static Permit prepare(WebTaskDomain domain,PhoneObservation frame,ActionDecision action,String run,
                          WebEvidenceReceipt observed,WebEvidenceReceipt fresh)throws Exception{
        if(domain==null||domain.flight==null||!"click".equals(action.action)
                ||!"official_home".equals(domain.phase)||!PURPOSE.equals(domain.flight.purpose(action.nodeId)))return null;
        need("https://m.csair.com/".equals(domain.url)&&frame!=null&&observed!=null&&fresh!=null,
                "booking exception requires the actual official homepage captures");
        need(!frame.nodesTruncated&&frame.collectionStats!=null&&!frame.collectionStats.truncated()
                &&frame.collectionStats.pending==0&&frame.collectionStats.childSlotsOmitted==0,
                "complete original native observation required");
        PhoneObservation.Node target=null;
        for(PhoneObservation.Node node:frame.nodes)if(node.id.equals(action.nodeId)){
            need(target==null,"duplicate original native target");target=node;
        }
        need(target!=null&&target.nativeTreePath!=null&&target.nativeParentClass!=null
                &&"android.widget.Button".equals(target.className)&&LABEL.equals(target.label())
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(target.packageName)&&target.viewId.isEmpty()
                &&target.clickable&&target.enabled&&!target.password&&!target.editable&&!target.scrollable,
                "original native booking button required");
        need("captured".equals(observed.status)&&"captured".equals(fresh.status)
                &&observed.stability().rawEqual&&fresh.stability().rawEqual
                &&observed.bindingSha.equals(fresh.bindingSha)&&observed.instance.equals(fresh.instance)
                &&observed.epoch==fresh.epoch&&observed.windowId==fresh.windowId
                &&observed.displayId==fresh.displayId&&observed.url.equals(fresh.url)
                &&domain.instance.equals(fresh.instance)&&domain.epoch==fresh.epoch
                &&frame.windowId==fresh.windowId&&domain.displayId==fresh.displayId,
                "same verified full-raw capture lease required");
        WebNativeGeometry before=WebNativeGeometry.read(observed.capture(),observed.dom(),observed.displayId,
                observed.windowId,observed.stability());
        WebNativeGeometry after=WebNativeGeometry.read(fresh.capture(),fresh.dom(),fresh.displayId,
                fresh.windowId,fresh.stability());
        need(before!=null&&after!=null&&before.same(after),"native capture geometry changed");
        JSONObject proof=compareDom(observed.dom(),fresh.dom())
                .put("first_dom_sha256",observed.domSha).put("fresh_dom_sha256",fresh.domSha)
                .put("first_capture_request_nonce",observed.callback().get("request_nonce"))
                .put("fresh_capture_request_nonce",fresh.callback().get("request_nonce"))
                .put("native_geometry_sha256",after.fingerprint);
        return new Permit(domain,frame,target,run,action,fresh,proof);
    }


    /**
     * Read-only observation admission for the exact compiled homepage. Callers
     * must supply complete native traversals from the private service snapshot;
     * retained rows alone can never satisfy this predicate. This produces no
     * action Permit, and does not authenticate a caller-supplied JSON record.
     */
    static JSONObject compareObservationBracket(String taskId,JSONObject beforeFrame,JSONArray beforeNative,
            JSONObject afterFrame,JSONArray afterNative,JSONObject first,JSONObject last,String targetPath)throws Exception{
        need(taskId!=null&&!taskId.isEmpty()&&beforeFrame!=null&&afterFrame!=null,
                "actual task and both original frames required");
        requireCompleteObservation(beforeFrame,beforeNative);requireCompleteObservation(afterFrame,afterNative);
        need(WebDomCanonical.same(without(beforeFrame,"observation_id","screen_sha256","app_tree_sha256",
                        "observation_state_sha256","nodes","collection"),
                without(afterFrame,"observation_id","screen_sha256","app_tree_sha256",
                        "observation_state_sha256","nodes","collection")),
                "observation window, Selection, IME or other frame metadata changed");
        need(WebDomCanonical.same(without(beforeFrame.getJSONObject("collection"),"elapsed_ms"),
                        without(afterFrame.getJSONObject("collection"),"elapsed_ms")),
                "observation traversal counters changed");
        JSONObject binding=first.getJSONObject("binding"),bg=binding.getJSONObject("background");
        need(WebDomCanonical.same(binding,last.getJSONObject("binding"))
                &&taskId.equals(binding.getString("task_id"))
                &&"csair_public_flight".equals(binding.getString("goal_kind"))
                &&"csair_public_flight_v1".equals(binding.getString("site_policy_id"))
                &&"https://m.csair.com/".equals(binding.getString("initial_url")),
                "same actual Flight task binding required");
        JSONObject selected=beforeFrame.getJSONObject("background_session");
        int display=beforeFrame.getJSONObject("window").getInt("display_id"),window=beforeFrame.getInt("window_id");
        need(display>0&&window>=0&&bg.getInt("display_id")==display
                &&bg.getString("generation").equals(selected.getString("generation"))
                &&WebDomCanonical.same(bg.getJSONArray("selected_packages"),selected.getJSONArray("allowed_packages")),
                "capture does not belong to the original background Selection");
        for(JSONObject capture:new JSONObject[]{first,last}){
            need("https://m.csair.com/".equals(capture.getString("committed_main_frame_url"))
                    &&"https://m.csair.com/".equals(capture.getString("current_native_url"))
                    &&capture.getInt("display_id")==display&&capture.getInt("actual_window_id")==window
                    &&WebEvidenceProtocol.HELPER_PACKAGE.equals(capture.getString("helper_package"))
                    &&capture.isNull("observed_link_navigation")&&!capture.getBoolean("truncated"),
                    "observation exception is only for the unchanged official homepage");
        }
        for(String key:new String[]{"webview_instance","navigation_epoch","helper_uid","helper_pid",
                "commit_elapsed_ms","observer_script_sha256"})
            need(WebDomCanonical.same(first.get(key),last.get(key)),"capture identity changed: "+key);
        need(!first.getString("webview_instance").isEmpty()
                &&first.getLong("ended_elapsed_ms")<=last.getLong("started_elapsed_ms"),
                "ordered independent captures required");
        String raw=first.getString("before_dom_raw_utf8");
        need(raw.equals(first.getString("dom_raw_utf8"))&&raw.equals(last.getString("before_dom_raw_utf8"))
                &&raw.equals(last.getString("dom_raw_utf8")),"all four complete homepage DOM raws must be equal");
        JSONObject dom=WebEvidenceJson.parseDom(raw);
        JSONObject domProof=compareDom(dom,dom);
        WebNativeGeometry a=WebNativeGeometry.read(first,dom,display,window);
        WebNativeGeometry b=WebNativeGeometry.read(last,dom,display,window);
        need(a!=null&&b!=null&&a.same(b),"same independently replayed native WebView geometry required");
        Map<String,JSONObject> nativeRows=nativeNodes(beforeNative);
        String webview=ancestorClass(nativeRows,targetPath,"android.webkit.WebView");
        need(webview!=null&&java.util.Arrays.equals(intRect(nativeRows.get(webview)),a.bounds),
                "actual native WebView ancestor differs from capture geometry");
        JSONObject nativeProof=compareNative(beforeNative,afterNative,targetPath);
        nativeProof.put("retained_node_pairing",compareRetained(beforeFrame.getJSONArray("nodes"),
                afterFrame.getJSONArray("nodes"),nativeProof.getString("native_slider_path")));
        return new JSONObject().put("schema","hepta.csair-home-observation-bracket.v1")
                .put("purpose","readonly_current_page_observation")
                .put("task_id",taskId).put("first_observation",beforeFrame).put("last_observation",afterFrame)
                .put("first_capture_challenge",first.getString("challenge"))
                .put("last_capture_challenge",last.getString("challenge"))
                .put("binding_sha256",WebDomCanonical.sha256(binding))
                .put("webview_instance",first.get("webview_instance")).put("navigation_epoch",first.get("navigation_epoch"))
                .put("display_id",display).put("window_id",window)
                .put("all_four_dom_raws_equal",true).put("dom_sha256",first.getString("dom_sha256"))
                .put("dom_stability_sha256",first.getString("dom_stability_sha256"))
                .put("native_geometry_sha256",b.fingerprint).put("dom",domProof).put("native",nativeProof)
                .put("complete_native_snapshot_structure_replayed",true)
                .put("retained_rows_are_not_the_complete_traversal",true)
                .put("action_permit_created",false).put("coordinates_used_for_input",false)
                .put("pixel_equality_claimed",false).put("fully_unoccluded_claimed",false)
                .put("business_verified",false);
    }
    private static void requireCompleteObservation(JSONObject frame,JSONArray nativeRows)throws Exception{
        need(WebEvidenceProtocol.HELPER_PACKAGE.equals(frame.get("package"))
                &&Boolean.FALSE.equals(frame.get("nodes_truncated"))&&Boolean.FALSE.equals(frame.get("ime_visible"))
                &&frame.getString("observation_id").length()>0,"complete helper observation with hidden IME required");
        JSONObject window=frame.getJSONObject("window"),bg=frame.getJSONObject("background_session");
        need("observed".equals(window.get("metadata_status"))&&window.getInt("window_id")==frame.getInt("window_id")
                &&window.getInt("display_id")>0&&window.getInt("type")==1
                &&Boolean.FALSE.equals(window.get("root_class_truncated"))&&Boolean.FALSE.equals(window.get("title_truncated"))
                &&"background".equals(bg.get("mode"))&&bg.getInt("display_id")==window.getInt("display_id")
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(bg.get("bootstrap_package"))
                &&bg.getJSONArray("allowed_packages").length()==1
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(bg.getJSONArray("allowed_packages").get(0)),
                "exact observed background window metadata required");
        JSONObject collection=frame.getJSONObject("collection");
        need("hepta.observation-collection.v1".equals(collection.get("schema"))
                &&"same_observed_accessibility_traversal".equals(collection.get("source"))
                &&nativeRows!=null&&nativeRows.length()==collection.getInt("visited_nodes")
                &&frame.getJSONArray("nodes").length()==collection.getInt("retained_nodes")
                &&collection.getJSONArray("truncation_reasons").length()==0,"complete same-traversal evidence required");
        for(String key:new String[]{"pending_nodes_at_stop","child_slots_omitted_by_traversal_limit",
                "nodes_omitted_by_node_limit","nodes_omitted_by_text_limit"})
            need(collection.getLong(key)==0,"omitted native traversal records");
        JSONObject root=nativeNodes(nativeRows).get("0");
        need(root.getInt("window_id")==frame.getInt("window_id")
                &&root.getString("class").equals(window.getString("root_class"))
                &&WebDomCanonical.same(root.getJSONArray("bounds"),window.getJSONArray("root_bounds")),
                "actual complete native root differs from the observed window");
    }

    /** Complete DOM comparison; only this observed eight-image slider may move. */
    static JSONObject compareDom(JSONObject before,JSONObject after)throws Exception{
        Map<String,JSONObject> a=domNodes(before),b=domNodes(after);
        need(a.keySet().equals(b.keySet()),"homepage DOM membership changed");
